insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (204, 18, 75, 82, 'سورة الكهف ٧٥ – ٨٢', '«هذا فراق بيني وبينك»، وإقامة الجدار، وتأويل ما لم يستطع موسى ﵇ عليه صبراً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 204) = $j$[{"lbl": "الآيات ٧٥ – ٧٨", "q": "۞قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ﴿٧٥﴾ قَالَ إِن سَأَلۡتُكَ عَن شَيۡءِۭ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي عُذۡرٗا ﴿٧٦﴾ فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهۡلَ قَرۡيَةٍ ٱسۡتَطۡعَمَآ أَهۡلَهَا فَأَبَوۡاْ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارٗا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَجۡرٗا ﴿٧٧﴾ قَالَ هَٰذَا فِرَاقُ بَيۡنِي وَبَيۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِيلِ مَا لَمۡ تَسۡتَطِع عَّلَيۡهِ صَبۡرًا ﴿٧٨﴾", "w": [["ألم أقل لك", "قال الخضر لموسى ﵉."], ["بعدها", "بعد هذه المرة."], ["فلا تصاحبني", "لا تتركني أتبعك."], ["من لدنّي عذراً", "من قِبَلي عذراً في عدم مصاحبتي لك."], ["أهل قرية", "مدينة، قيل إنها أنطاكية."], ["استطعما أهلها", "طلبا منهم الطعام الواجب للضيف."], ["يريد أن ينقضّ", "قارب السقوط لميلانه."], ["أجراً", "جُعلاً على إقامته وإصلاحه."], ["هذا فراق بيني وبينك", "قولك هذا نهاية الصحبة وبداية المفارقة."], ["بتأويل", "تفسير ما كنت تنكره على حسب علمك."]], "m": "ما زال السياق في محاورة الخضر وموسى: لما بالغ موسى في إنكار قتل الغلام قال الخضر: ألم أقل لك إنك لن تستطيع معي صبراً؟ قال موسى: إن سألتك عن شيء بعد هذه المرة فاترك صحبتي، فقد بلغت من جهتي عذراً في تركك إياي. فانطلقا حتى أتيا أهل قرية، قيل إنها أنطاكية، ووصلاها ليلاً والجو بارد، فطلبا منهم طعام الضيف الواجب، فأبوا أن يضيّفوهما، فوجدا فيها جداراً قارب السقوط فأقامه الخضر وأصلحه، فقال موسى: لو شئت لاتخذت عليه جُعلاً، لا سيما أن أهل القرية لم يعطونا حقنا من الضيافة. فقال الخضر: هذا فراق بيني وبينك، لأنك تعهّدت إن سألتني بعد قتل الغلام ألا تطلب صحبتي، سأخبرك بتأويل ما لم تستطع عليه صبراً من خرق السفينة وقتل الغلام وإقامة الجدار.", "h": ["وجوب الوفاء بما التزم به الإنسان لآخر.", "وجوب الضيافة لمن استحقها.", "جواز التبرّع بأي خير أو عمل ابتغاء وجه الله تعالى."], "k": "«لو شئت لاتخذت عليه أجراً»… أقام الجدار لمن منعوه الطعام؛ فهل أحسن لمن لم يحسن إليّ؟"}, {"lbl": "الآيات ٧٩ – ٨٢", "q": "أَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا ﴿٧٩﴾ وَأَمَّا ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنٗا وَكُفۡرٗا ﴿٨٠﴾ فَأَرَدۡنَآ أَن يُبۡدِلَهُمَا رَبُّهُمَا خَيۡرٗا مِّنۡهُ زَكَوٰةٗ وَأَقۡرَبَ رُحۡمٗا ﴿٨١﴾ وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ تَحۡتَهُۥ كَنزٞ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا ﴿٨٢﴾", "w": [["للمساكين", "جمع مسكين، وهو الضعيف العاجز عن الكسب."], ["يعملون في البحر", "يؤجّرون سفينتهم للركاب."], ["أعيبها", "أجعلها معيبة حتى لا يُرغب فيها."], ["غصباً", "قهراً."], ["أن يرهقهما طغياناً وكفراً", "يغشاهما ظلماً وجحوداً."], ["وأقرب رحماً", "رحمة، إذ الرحم والرحمة بمعنى واحد."], ["وما فعلته عن أمري", "عن اختيار مني، بل بأمر ربي جل جلاله."]], "m": "هذا آخر حديث موسى والخضر ﵉، فقد وعده عند فراقه أن يبيّن له التأويل: أما السفينة التي خرقتها فكانت لمساكين يؤجّرونها بما يحصل لهم بعض القوت، فأردت أن أعيبها لا لأغرق أهلها، وكان وراءهم ملك ظالم يأخذ كل سفينة صالحة قهراً، فأردت أن أبقيها لهم، إذ هو لا يأخذ إلا السفن الصالحة. وأما الغلام الذي قتلته فكان أبواه مؤمنين، فخشينا إن كبر أن يغشيهما طغياناً وكفراً، فأردنا أن يبدلهما ربهما خيراً منه طهراً وصلاحاً، وأقرب رحمة وبراً بهما. وأما الجدار فكان لغلامين يتيمين في المدينة، وكان تحته كنز لهما، وكان أبوهما صالحاً، فأراد ربك أن يبلغا سن الرشد ويستخرجا كنزهما رحمة من ربك، وما فعلته عن إرادتي واختياري، بل بأمر ربي وتعليمه، ذلك تأويل ما لم تستطع عليه صبراً.", "h": ["بيان ضروب من خفي ألطاف الله تعالى، فعلى المؤمن أن يرضى بقضاء الله تعالى وإن كان ظاهره ضاراً.", "بيان حسن تدبير الله تعالى لأوليائه بما ظاهره عذاب ولكن في باطنه رحمة.", "مراعاة صلاح الآباء في إصلاح حال الأبناء.", "كل ما أتاه الخضر كان بوحي إلهي، وقد قال الخضر لموسى: أنا على علم مما علّمني ربي، وأنت على علم مما علّمك الله، وإن علمي وعلمك إلى علم الله إلا كما يأخذ الطائر بمنقاره من البحر."], "k": "«وكان أبوهما صالحاً»… صلاحي اليوم قد يحفظ أبنائي غداً؛ فأي صلاح أدّخره لهم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 204;
insert into public.tdb_cards(topic, i, body) select 204, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٥ – ٧٨", "q": "۞قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ﴿٧٥﴾ قَالَ إِن سَأَلۡتُكَ عَن شَيۡءِۭ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي عُذۡرٗا ﴿٧٦﴾ فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهۡلَ قَرۡيَةٍ ٱسۡتَطۡعَمَآ أَهۡلَهَا فَأَبَوۡاْ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارٗا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَجۡرٗا ﴿٧٧﴾ قَالَ هَٰذَا فِرَاقُ بَيۡنِي وَبَيۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِيلِ مَا لَمۡ تَسۡتَطِع عَّلَيۡهِ صَبۡرًا ﴿٧٨﴾", "w": [["ألم أقل لك", "قال الخضر لموسى ﵉."], ["بعدها", "بعد هذه المرة."], ["فلا تصاحبني", "لا تتركني أتبعك."], ["من لدنّي عذراً", "من قِبَلي عذراً في عدم مصاحبتي لك."], ["أهل قرية", "مدينة، قيل إنها أنطاكية."], ["استطعما أهلها", "طلبا منهم الطعام الواجب للضيف."], ["يريد أن ينقضّ", "قارب السقوط لميلانه."], ["أجراً", "جُعلاً على إقامته وإصلاحه."], ["هذا فراق بيني وبينك", "قولك هذا نهاية الصحبة وبداية المفارقة."], ["بتأويل", "تفسير ما كنت تنكره على حسب علمك."]], "m": "ما زال السياق في محاورة الخضر وموسى: لما بالغ موسى في إنكار قتل الغلام قال الخضر: ألم أقل لك إنك لن تستطيع معي صبراً؟ قال موسى: إن سألتك عن شيء بعد هذه المرة فاترك صحبتي، فقد بلغت من جهتي عذراً في تركك إياي. فانطلقا حتى أتيا أهل قرية، قيل إنها أنطاكية، ووصلاها ليلاً والجو بارد، فطلبا منهم طعام الضيف الواجب، فأبوا أن يضيّفوهما، فوجدا فيها جداراً قارب السقوط فأقامه الخضر وأصلحه، فقال موسى: لو شئت لاتخذت عليه جُعلاً، لا سيما أن أهل القرية لم يعطونا حقنا من الضيافة. فقال الخضر: هذا فراق بيني وبينك، لأنك تعهّدت إن سألتني بعد قتل الغلام ألا تطلب صحبتي، سأخبرك بتأويل ما لم تستطع عليه صبراً من خرق السفينة وقتل الغلام وإقامة الجدار.", "h": ["وجوب الوفاء بما التزم به الإنسان لآخر.", "وجوب الضيافة لمن استحقها.", "جواز التبرّع بأي خير أو عمل ابتغاء وجه الله تعالى."], "k": "«لو شئت لاتخذت عليه أجراً»… أقام الجدار لمن منعوه الطعام؛ فهل أحسن لمن لم يحسن إليّ؟"}, {"lbl": "الآيات ٧٩ – ٨٢", "q": "أَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا ﴿٧٩﴾ وَأَمَّا ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنٗا وَكُفۡرٗا ﴿٨٠﴾ فَأَرَدۡنَآ أَن يُبۡدِلَهُمَا رَبُّهُمَا خَيۡرٗا مِّنۡهُ زَكَوٰةٗ وَأَقۡرَبَ رُحۡمٗا ﴿٨١﴾ وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ تَحۡتَهُۥ كَنزٞ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا ﴿٨٢﴾", "w": [["للمساكين", "جمع مسكين، وهو الضعيف العاجز عن الكسب."], ["يعملون في البحر", "يؤجّرون سفينتهم للركاب."], ["أعيبها", "أجعلها معيبة حتى لا يُرغب فيها."], ["غصباً", "قهراً."], ["أن يرهقهما طغياناً وكفراً", "يغشاهما ظلماً وجحوداً."], ["وأقرب رحماً", "رحمة، إذ الرحم والرحمة بمعنى واحد."], ["وما فعلته عن أمري", "عن اختيار مني، بل بأمر ربي جل جلاله."]], "m": "هذا آخر حديث موسى والخضر ﵉، فقد وعده عند فراقه أن يبيّن له التأويل: أما السفينة التي خرقتها فكانت لمساكين يؤجّرونها بما يحصل لهم بعض القوت، فأردت أن أعيبها لا لأغرق أهلها، وكان وراءهم ملك ظالم يأخذ كل سفينة صالحة قهراً، فأردت أن أبقيها لهم، إذ هو لا يأخذ إلا السفن الصالحة. وأما الغلام الذي قتلته فكان أبواه مؤمنين، فخشينا إن كبر أن يغشيهما طغياناً وكفراً، فأردنا أن يبدلهما ربهما خيراً منه طهراً وصلاحاً، وأقرب رحمة وبراً بهما. وأما الجدار فكان لغلامين يتيمين في المدينة، وكان تحته كنز لهما، وكان أبوهما صالحاً، فأراد ربك أن يبلغا سن الرشد ويستخرجا كنزهما رحمة من ربك، وما فعلته عن إرادتي واختياري، بل بأمر ربي وتعليمه، ذلك تأويل ما لم تستطع عليه صبراً.", "h": ["بيان ضروب من خفي ألطاف الله تعالى، فعلى المؤمن أن يرضى بقضاء الله تعالى وإن كان ظاهره ضاراً.", "بيان حسن تدبير الله تعالى لأوليائه بما ظاهره عذاب ولكن في باطنه رحمة.", "مراعاة صلاح الآباء في إصلاح حال الأبناء.", "كل ما أتاه الخضر كان بوحي إلهي، وقد قال الخضر لموسى: أنا على علم مما علّمني ربي، و