insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (205, 18, 83, 101, 'سورة الكهف ٨٣ – ١٠١', '«ويسألونك عن ذي القرنين»: رحلتاه إلى المغرب والمشرق، وبناء السد على يأجوج ومأجوج', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 205) = $j$[{"lbl": "الآيات ٨٣ – ٩٣", "q": "وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا ﴿٨٣﴾ إِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا ﴿٨٤﴾ فَأَتۡبَعَ سَبَبًا ﴿٨٥﴾ حَتَّىٰٓ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِي عَيۡنٍ حَمِئَةٖ وَوَجَدَ عِندَهَا قَوۡمٗاۖ قُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمۡ حُسۡنٗا ﴿٨٦﴾ قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابٗا نُّكۡرٗا ﴿٨٧﴾ وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَلَهُۥ جَزَآءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرٗا ﴿٨٨﴾ ثُمَّ أَتۡبَعَ سَبَبًا ﴿٨٩﴾ حَتَّىٰٓ إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمٖ لَّمۡ نَجۡعَل لَّهُم مِّن دُونِهَا سِتۡرٗا ﴿٩٠﴾ كَذَٰلِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَيۡهِ خُبۡرٗا ﴿٩١﴾ ثُمَّ أَتۡبَعَ سَبَبًا ﴿٩٢﴾ حَتَّىٰٓ إِذَا بَلَغَ بَيۡنَ ٱلسَّدَّيۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمٗا لَّا يَكَادُونَ يَفۡقَهُونَ قَوۡلٗا ﴿٩٣﴾", "w": [["ويسألونك", "كفار قريش بتعليم يهود لهم."], ["ذي القرنين", "الإسكندر باني الإسكندرية المصرية، الحميري، أحد الملوك التبابعة، وكان عبداً صالحاً."], ["سأتلو عليكم منه ذكراً", "سأقصّ عليكم من حاله خبراً يحمل موعظة وعلماً."], ["مكّنا له في الأرض", "بالحكم والتصرف في ممالكها."], ["من كل شيء سبباً", "من كل شيء يحتاج إليه سبباً موصلاً إلى مراده."], ["فأتبع سبباً", "أتبع السبب سبباً آخر حتى انتهى إلى مراده."], ["تغرب في عين حمئة", "ذات حمأة، وهي الطين الأسود، وغروبها إنما هو في نظر العين، وإلا فالشمس في السماء والبحر في الأرض."], ["قوماً", "كافرين."], ["عذاباً نكراً", "عظيماً فظيعاً."], ["يسراً", "ليّناً من القول، سهلاً من العمل."], ["مطلع الشمس", "مكاناً تطلع منه."], ["لم نجعل لهم من دونها ستراً", "لم يكن لهم يومئذ ثياب يلبسونها ولا منازل يسكنونها، وإنما لهم أسراب في الأرض يدخلون فيها."], ["بين السدّين", "بين الجبلين."], ["لا يكادون يفقهون قولاً", "لا يفهمون كلام من يخاطبهم إلا بشدة وبطء."]], "m": "هذه قصة العبد الصالح ذي القرنين، وقد تضمّنها سؤال قريش للنبي ﷺ بإيعاز من يهود المدينة، إذ قالوا: سلوه عن الروح وأصحاب الكهف وذي القرنين، فإن أجابكم فهو نبي، فكان الجواب عن الروح في الإسراء، وعن الفتية وذي القرنين في الكهف. قل للسائلين: سأقرأ عليكم من أمره خبراً يحمل الموعظة. إنا مكّنا له في الأرض بالملك والسلطان، وأعطيناه من كل شيء يحتاج إليه في فتح الأرض ونشر العدل سبباً يوصله، فأتبع السبب سبباً حسب سنة الله في تكامل الأشياء، فمن صنع إبرة وتابع الأسباب صنع المسلّة. حتى إذا بلغ مغرب الشمس وجدها تغرب في عين حمئة على ساحل المحيط بحسب رأي العين، ووجد عندها قوماً كافرين، فيسّر الله له الغلبة عليهم، وقال له: إما أن تعذّبهم بالأسر والقتل، وإما أن تتخذ فيهم حسناً. قال: أما من ظلم بالشرك فسوف نعذّبه بالقتل والأسر، ثم يُردّ إلى ربه فيعذّبه عذاباً فظيعاً، وأما من آمن وعمل صالحاً فله الجنة جزاءً، وسنقول له من أمرنا قولاً ليّناً ولا نكلّفه ما يشق عليه. ثم استخدم ما تحصّل له من القوة في مواصلة الفتح في المشرق، حتى إذا بلغ مطلع الشمس وجدها تطلع على قوم بدائيين لا يبنون الدور ولا يلبسون الثياب، بل يسكنون الكهوف والمغارات، كذلك، وقد أحطنا بما لديه من قوة وأسباب علماً كاملاً. ثم واصل طريقه حتى إذا بلغ بين الجبلين وجد من دونهما قوماً لا يكادون يفهمون ما يقال لهم إلا بشدة وبطء.", "h": ["تقرير نبوة النبي محمد ﷺ، إذ هذا جواب آخر أسئلة قريش الثلاثة.", "إتباع السبب السبب يصل به ذو الرأي والإرادة إلى تحقيق ما هو كالمعجزات.", "قول ذي القرنين: «أما من ظلم فسوف نعذّبه…» يجب أن يكون مادة دستورية يُحكم به الأفراد والجماعات لصدقها وموافقتها لحكم الله تعالى، ومن الأسف أن يُعكس هذا القول السديد فيصبح أهل الظلم مكرّمين وأهل الإيمان والاستقامة مهانين.", "بيان وجود أمم بدائية إلى عهد ما بعد ذي القرنين لا يلبسون ثياباً ولا يسكنون سوى الكهوف والمغارات.", "تقرير أن هذا الملك الصالح قد ملك الأرض، فهو أحد أربعة حكموا الناس شرقاً وغرباً."], "k": "«وآتيناه من كل شيء سبباً فأتبع سبباً»… ما الأسباب التي بين يديّ، وهل أُتبعها بالعمل؟"}, {"lbl": "الآيات ٩٤ – ١٠١", "q": "قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدّٗا ﴿٩٤﴾ قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا ﴿٩٥﴾ ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارٗا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرٗا ﴿٩٦﴾ فَمَا ٱسۡطَٰعُوٓاْ أَن يَظۡهَرُوهُ وَمَا ٱسۡتَطَٰعُواْ لَهُۥ نَقۡبٗا ﴿٩٧﴾ قَالَ هَٰذَا رَحۡمَةٞ مِّن رَّبِّيۖ فَإِذَا جَآءَ وَعۡدُ رَبِّي جَعَلَهُۥ دَكَّآءَۖ وَكَانَ وَعۡدُ رَبِّي حَقّٗا ﴿٩٨﴾ ۞وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِذٖ يَمُوجُ فِي بَعۡضٖۖ وَنُفِخَ فِي ٱلصُّورِ فَجَمَعۡنَٰهُمۡ جَمۡعٗا ﴿٩٩﴾ وَعَرَضۡنَا جَهَنَّمَ يَوۡمَئِذٖ لِّلۡكَٰفِرِينَ عَرۡضًا ﴿١٠٠﴾ ٱلَّذِينَ كَانَتۡ أَعۡيُنُهُمۡ فِي غِطَآءٍ عَن ذِكۡرِي وَكَانُواْ لَا يَسۡتَطِيعُونَ سَمۡعًا ﴿١٠١﴾", "w": [["يأجوج ومأجوج", "قبيلتان من أولاد يافث بن نوح ﵇، والله أعلم."], ["نجعل لك خرجاً", "جُعلاً مقابل العمل."], ["سدّاً", "الحاجز المانع بين شيئين."], ["ردماً", "حاجزاً حصيناً، وهو السد."], ["زبر الحديد", "جمع زبرة، قطعة من حديد على قدر الحجرة التي يُبنى بها."], ["بين الصدفين", "جانبي الجبلين."], ["قطراً", "النحاس المذاب."], ["فما اسطاعوا أن يظهروه", "عجزوا عن الظهور فوقه لعلوّه وملاسته."], ["نقباً", "فتح ثغرة تحته ليخرجوا منها."], ["جعله دكّاء", "تراباً مساوياً للأرض."], ["وتركنا بعضهم يومئذ يموج في بعض", "يذهبون ويجيئون في اضطراب كموج البحر."], ["أعينهم في غطاء عن ذكري", "أعين قلوبهم، وهي البصائر، في أكنّة لا تبصر الحق ولا تعرفه."], ["لا يستطيعون سمعاً", "لبغضهم للحق والداعي إليه."]], "m": "شكا سكان المنطقة الشمالية الشرقية إلى ذي القرنين: إن يأجوج ومأجوج مفسدون في الأرض بالقتل والتدمير، فهل نجعل لك جُعلاً على أن تجعل بيننا وبينهم سداً؟ قال: ما مكّنني فيه ربي من المال والقوة خير من جُعلكم، فأعينوني بقوة أجعل بينكم وبينهم حاجزاً حصيناً، آتوني قطع الحديد، فأخذ يبني حتى ساوى بين جانبي الجبلين، قال: انفخوا النار على الحديد، حتى إذا جعله ناراً قال: آتوني النحاس المذاب أفرغه عليه، فصار كأنه صفيحة واحدة، فما استطاع يأجوج ومأجوج أن يعلوه، وما استطاعوا له خرقاً. فلما نظر إليه وهو جبل شامخ قال: هذا من أثر رحمة ربي عليّ وعلى الناس، فإذا جاء وعد ربي بخروج يأجوج ومأجوج عند قرب الساعة جعله تراباً مساوياً للأرض، وكان وعد ربي حقاً. وتركنا بعضهم يومئذ مختلطين مضطربين، ونُفخ في الصور نفخة البعث فجمعناهم للحساب، وعرضنا جهنم يومئذ للكافرين عرضاً يشاهدونها من قرب، الذين كانت أعين قلوبهم في غطاء عن آيات الله الكونية والقرآنية فلا يستدلّون بها على توحيده، وكانوا لا يستطيعون سمعاً للحق.", "h": ["مشروعية الجعالة للقيام بالمهام من الأعمال.", "فضيلة التبرّع بالجهد الذاتي والعقلي.", "مشروعية التعاون على ما هو خير، أو دفع للشر.", "تقرير وجود أمة يأجوج ومأجوج، وأن خروجهم من أشراط الساعة.", "تقرير البعث والجزاء."], "k": "«هذا رحمة من ربي»… بنى السد العظيم ثم نسبه إلى ربه؛ فهل أنسب إنجازاتي إليه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 205;
insert into public.tdb_cards(topic, i, body) select 205, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٣ – ٩٣", "q": "وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا ﴿٨٣﴾ إِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا ﴿٨٤﴾ فَأَتۡبَعَ سَبَبًا ﴿٨٥﴾ حَتَّىٰٓ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِي عَيۡنٍ حَمِئَةٖ وَوَجَدَ عِندَهَا قَوۡمٗاۖ قُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمۡ حُسۡنٗا ﴿٨٦﴾ قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابٗا نُّكۡرٗا ﴿٨٧﴾ وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَلَهُۥ جَزَآءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرٗا ﴿٨٨﴾ ثُمَّ أَتۡبَعَ سَبَبًا ﴿٨٩﴾ حَتَّىٰٓ إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمٖ لَّمۡ نَجۡعَل لَّهُم مِّن دُونِهَا سِتۡرٗا ﴿٩٠﴾ كَذَٰلِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَيۡهِ خُبۡرٗا ﴿٩١﴾ ثُمَّ أَتۡبَعَ سَبَبًا ﴿٩٢﴾ حَتَّىٰٓ إِذَا بَلَغَ بَيۡنَ ٱلسَّدَّيۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمٗا لَّا يَكَادُونَ يَفۡقَهُونَ قَوۡلٗا ﴿٩٣﴾", "w": [["ويسألونك", "كفار قريش بتعليم يهود لهم."], ["ذي القرنين", "الإسكندر باني الإسكندرية المصرية، الحميري، أحد الملوك التبابعة، وكان عبداً صالحاً."], ["سأتلو عليكم منه ذكراً", "سأقصّ عليكم من حاله خبراً يحمل موعظة وعلماً."], ["مكّنا له في الأرض", "بالحكم والتصرف في ممالكها."], ["من كل شيء سبباً", "من كل شيء يحتاج إليه سبباً موصلاً إلى مراده."], ["فأتبع سبباً", "أتبع السبب سبباً آخر حتى انتهى إلى مراده."], ["تغرب في عين حمئة", "ذات حمأة، وهي الطين الأسود، وغروبها إنما هو في نظر العين، وإلا فالشمس في السماء والبحر في الأرض."], ["قوماً", "كافرين."], ["عذاباً نكراً", "عظيماً فظيعاً."], ["يسراً", "ليّناً من القول، سهلاً من العمل."], ["مطلع الشمس", "مكاناً تطلع منه."], ["لم نجعل لهم من دونها ستراً", "لم يكن لهم يومئذ ثياب يلبسونها ولا منازل يسكنونها، وإنما لهم أسراب في الأرض يدخلون فيها."], ["بين السدّين", "بين الجبلين."], ["لا يكادون يفقهون قولاً", "لا يفهمون كلام من يخاطبهم إلا بشدة وبطء."]], "m": "هذه قصة العبد الصالح ذي القرنين، وقد تضمّنها سؤال قريش للنبي ﷺ بإيعاز من يهود المدينة، إذ قالوا: سلوه عن الروح وأصحاب الكهف وذي القرنين، فإن أجابكم فهو نبي، فكان الجواب عن الروح في الإسراء، وعن الفتية وذي القرنين في الكهف. قل للسائلين: سأقرأ عليكم من أمره خبراً يحمل الموعظة. إنا مكّنا له في الأرض بالملك والسلطان، وأعطيناه من كل شيء يحتاج إليه في فتح الأرض ونشر العدل سبباً يوصله، فأتبع السبب سبباً حسب سنة الله في تكامل الأشياء، فمن صنع إبرة وتابع الأسباب صنع المسلّة. حتى إذا بلغ مغرب الشمس وجدها تغرب في عين حمئة على ساحل المحيط بحسب رأي العين، ووجد عندها قوماً كافرين، فيسّر الله له الغلبة عليهم، وقال له: إما أن تعذّبهم بالأسر والقتل، وإما أن تتخذ فيهم حسناً. قال: أما من ظلم بالشرك فسوف نعذّبه بالقتل والأسر، ثم يُردّ إلى ربه فيعذّبه عذاباً فظيعاً، وأما من آمن وعمل صالحاً فله الجنة جزاءً، وسنقول له من أمرنا قولاً ليّناً ولا نكلّفه ما يشق عليه. ثم استخدم ما تحصّل له من القوة في مواصلة الفتح في المشرق، حتى إذا بلغ مطلع الشمس وجدها تطلع على قوم بدائيين لا يبنون الدور ولا يلبسون الثياب، بل يسكنون الكهوف والمغارات، كذلك، وقد أحطنا بما لديه من قوة وأسباب علماً كاملاً. ثم واصل طريقه حتى إذا بلغ بين الجبلين وجد من دونهما قوماً لا يكادون يفهمون ما يقال لهم إلا بشدة وبطء.", "h": ["تقرير نبوة النبي محمد ﷺ، إذ هذا جواب آخر أسئلة قريش الثلاثة.", "إتباع السبب السبب يصل به ذو الرأي والإرادة إلى تحقيق ما هو كالمعجزات.", "قول ذي القرنين: «أما من ظلم فسوف نعذّبه…» يجب أن يكون مادة دستورية يُحكم به الأفراد والجماعات لصدقها وموافقتها لحكم الله تعالى، ومن الأسف أن يُعكس هذا القول السديد فيصبح أهل الظلم مكرّمين وأهل الإيمان والاستقامة مهانين.", "بيان وجود أمم بدائية إلى عهد ما بعد ذي القرنين لا يلبسون ثياباً ولا يسكنون سوى الكهوف والمغارات.", "تقرير أن هذا الملك الصالح قد ملك الأرض، فهو أحد أربعة حكموا الناس شرقاً وغرباً."], "k": "«وآتيناه من كل شيء سبباً فأتبع سبباً»… ما الأسباب التي بين يديّ، وهل أُتبعها بالعمل؟"}, {"lbl": "الآيات ٩٤ – ١٠١", "q": "قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدّٗا ﴿٩٤﴾ قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا ﴿٩٥﴾ ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارٗا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرٗا ﴿٩٦﴾ فَمَا ٱسۡطَٰعُوٓاْ أَن يَظۡهَرُوهُ وَمَا ٱسۡتَطَٰعُواْ لَهُۥ نَقۡبٗا ﴿٩٧﴾ قَالَ هَٰذَا رَحۡمَةٞ مِّن رَّبِّيۖ فَإِذَا جَآءَ وَعۡدُ رَبِّي جَعَلَهُۥ دَكَّآءَۖ وَكَانَ وَعۡدُ رَبِّي حَقّٗا ﴿٩٨﴾ ۞وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِذٖ يَمُوجُ فِي بَعۡضٖۖ وَنُفِخَ فِي ٱلصُّورِ فَجَمَعۡنَٰهُمۡ جَمۡعٗا ﴿٩٩﴾ وَعَرَضۡنَا جَهَنَّمَ يَوۡمَئِذٖ لِّلۡكَٰفِرِينَ عَرۡضًا ﴿١٠٠﴾ ٱلَّذِينَ كَانَتۡ أَعۡيُنُهُمۡ فِي غِطَآءٍ عَن ذِكۡرِي وَكَانُواْ لَا يَسۡتَطِيعُونَ سَمۡعًا ﴿١٠١﴾", "w": [["يأجوج ومأجوج", "قبيلتان من أولاد يافث بن نوح ﵇، والله أعلم."], ["نجعل لك خرجاً", "جُعلاً مقابل العمل."], ["سدّاً", "الحاجز المانع بين شيئين."], ["ردماً", "حاجزاً حصيناً، وهو السد."], ["زبر الحديد", "جمع زبرة، قطعة من حديد على قدر الحجرة التي يُبنى بها."], ["بين الصدفين", "جانبي الجبلين."], ["قطراً", "النحاس المذاب."], ["فما اسطاعوا أن يظهروه", "عجزوا عن الظهور فوقه لعلوّه وملاسته."], ["نقباً", "فتح ثغرة تحته ليخرجوا منها."], ["جعله دكّاء", "تراباً مساوياً للأرض."], ["وتركنا بعضهم يومئذ يموج في بعض", "يذهبون ويجيئون في اضطراب كموج البحر."], ["أعينهم في غطاء عن ذكري", "أعين قلوبهم، وهي البصائر، في أكنّة لا تبصر الحق ولا تعرفه."], ["لا يستطيعون سمعاً", "لبغضهم للحق والداعي إليه."]], "m": "شكا سكان المنطقة الشمالية الشرقية إلى ذي القرنين: إن يأجوج ومأجوج مفسدون في الأرض بالقتل والتدمير، فهل نجعل لك جُعلاً على أن تجعل بيننا وبينهم سداً؟ قال: ما مكّنني فيه ربي من المال والقوة خير من جُعلكم، فأعينوني بقوة أجعل بينكم وبينهم حاجزاً حصيناً، آتوني قطع الحديد، فأخذ يبني حتى ساوى بين جانبي الجبلين، قال: انفخوا النار على الحديد، حتى إذا جعله ناراً قال: آتوني النحاس المذاب أفرغه عليه، فصار كأنه صفيحة واحدة، فما استطاع يأجوج ومأجوج أن يعلوه، وما استطاعوا له خرقاً. فلما نظر إليه وهو جبل شامخ قال: هذا من أثر رحمة ربي عليّ وعلى الناس، فإذا جاء وعد ربي بخروج يأجوج ومأجوج عند قرب الساعة جعله تراباً مساوياً للأرض، وكان وعد ربي حقاً. وتركنا بعضهم يومئذ مختلطين مضطربين، ونُفخ في الصور نفخة البعث فجمعناهم للحساب، وعرضنا جهنم يومئذ للكافرين عرضاً يشاهدونها من قرب، الذين كانت أعين قلوبهم في غطاء عن آيات الله الكونية والقرآنية فلا يستدلّون بها على توحيده، وكانوا لا يستطيعون سمعاً للحق.", "h": ["مشروعية الجعالة للقيام بالمهام من الأعمال.", "فضيلة التبرّع بالجهد الذاتي والعقلي.", "مشروعية التعاون على ما هو خير، أو دفع للشر.", "تقرير وجود أمة يأجوج ومأجوج، وأن خروجهم من أشراط الساعة.", "تقرير البعث والجزاء."], "k": "«هذا رحمة من ربي»… بنى السد العظيم ثم نسبه إلى ربه؛ فهل أنسب إنجازاتي إليه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (206, 18, 102, 110, 'سورة الكهف ١٠٢ – ١١٠', '«قل هل ننبئكم بالأخسرين أعمالاً»، وجنات الفردوس، و«فمن كان يرجو لقاء ربه فليعمل عملاً صالحاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 206) = $j$[{"lbl": "الآيات ١٠٢ – ١٠٦", "q": "أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓاْ أَن يَتَّخِذُواْ عِبَادِي مِن دُونِيٓ أَوۡلِيَآءَۚ إِنَّآ أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ نُزُلٗا ﴿١٠٢﴾ قُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ أَعۡمَٰلًا ﴿١٠٣﴾ ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ صُنۡعًا ﴿١٠٤﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَلِقَآئِهِۦ فَحَبِطَتۡ أَعۡمَٰلُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَزۡنٗا ﴿١٠٥﴾ ذَٰلِكَ جَزَآؤُهُمۡ جَهَنَّمُ بِمَا كَفَرُواْ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَرُسُلِي هُزُوًا ﴿١٠٦﴾", "w": [["أفحسب الذين كفروا", "الاستفهام للتقريع والتوبيخ."], ["أن يتخذوا عبادي", "كالملائكة وعيسى ابن مريم والعزير وغيرهم."], ["أولياء", "أرباباً يعبدونهم بأنواع من العبادات."], ["نزلاً", "ما يُعدّ للضيف من قرى، وهو طعامه وشرابه ومنامه."], ["ضلّ سعيهم", "بطل عملهم وفسد عليهم فلم ينتفعوا به."], ["يحسنون صنعاً", "يعملون عملاً يجازون عليه بالخير وحسن الجزاء."], ["بآيات ربهم", "بالقرآن وما فيه من دلائل التوحيد والأحكام الشرعية."], ["ولقائه", "كفروا بالبعث والجزاء."], ["وزناً", "لا نجعل لهم قدراً ولا قيمة، بل نزدريهم ونذمّهم."], ["ذلك", "أُطلق بدل «أولئك» لأنهم بكفرهم وحبوط أعمالهم أصبحوا غثاءً كغثاء السيل لا خير فيه ولا وزن له."]], "m": "ينكر تعالى على المشركين ظنّهم أن اتخاذهم عباده من دونه أولياء يعبدونهم، كالملائكة حيث عبدهم بعض العرب، والمسيح حيث عبده النصارى، والعزير حيث عبده بعض اليهود، لا يغضبه ولا يعاقبهم عليه، وكيف لا وقد أعدّ جهنم للكافرين دار ضيافة، فيها طعامهم وشرابهم وفراشهم؟ ثم قال مشوّقاً للخبر: قل هل ننبئكم بالأخسرين أعمالاً؟ الذين بطل سعيهم في الحياة الدنيا وهم يحسبون أنهم يحسنون عملاً، أولئك الذين كفروا بآيات ربهم ولقائه فلم يعملوا العمل الذي يرضيه، وهو الإيمان الصحيح والعمل الصالح الذي شرعه، فحبطت أعمالهم لأنها شرك وكفر وفساد، فلا نقيم لهم يوم القيامة وزناً، فإن أحدهم لا يزن جناح بعوضة. ذلك المذكور من غثاء الخلق جزاؤهم جهنم بسبب كفرهم واستهزائهم بآيات ربهم ورسله، فكان الحكم عادلاً والجزاء موافقاً.", "h": ["تقرير شرك من يتخذ الملائكة أو الأنبياء أو الأولياء آلهة يعبدونهم تحت شعار التقرب إلى الله تعالى والاستشفاع بهم.", "تقرير هلاك أصحاب الأهواء الذين يعبدون الله تعالى بغير ما شرع، ويتوسّلون إليه بغير ما جعله وسيلة لرضاه وجنته، كالخوارج والرهبان من النصارى وغلاة المبتدعة في العقائد والعبادات والأحكام الشرعية.", "لا قيمة ولا ثقل ولا وزن لعمل لا يوافق رضا الله تعالى، كما لا وزن عند الله تعالى لصاحبه، وإن مات خوفاً من الله أو شوقاً إليه."], "k": "«وهم يحسبون أنهم يحسنون صنعاً»… هل أزن عملي بميزان الشرع، لا بحسن ظني به؟"}, {"lbl": "الآيات ١٠٧ – ١١٠", "q": "إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ كَانَتۡ لَهُمۡ جَنَّـٰتُ ٱلۡفِرۡدَوۡسِ نُزُلًا ﴿١٠٧﴾ خَٰلِدِينَ فِيهَا لَا يَبۡغُونَ عَنۡهَا حِوَلٗا ﴿١٠٨﴾ قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادٗا لِّكَلِمَٰتِ رَبِّي لَنَفِدَ ٱلۡبَحۡرُ قَبۡلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّي وَلَوۡ جِئۡنَا بِمِثۡلِهِۦ مَدَدٗا ﴿١٠٩﴾ قُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَمَن كَانَ يَرۡجُواْ لِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلٗا صَٰلِحٗا وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا ﴿١١٠﴾", "w": [["كانت لهم", "جزاء إيمانهم وعملهم الصالح."], ["الفردوس نزلاً", "وسط الجنة وأعلاها، ونزلاً: منزل إكرام وإنعام."], ["لا يبغون عنها حولاً", "لا يطلبون تحوّلاً منها، لأنه لا خير منها أبداً."], ["لو كان البحر", "ماؤه مداداً."], ["قبل أن تنفد كلمات ربي", "قبل أن تفرغ."], ["يرجو لقاء ربه", "يأمل وينتظر البعث والجزاء يوم القيامة حيث يلقى ربه تعالى."], ["ولا يشرك بعبادة ربه أحداً", "لا يرائي بعمله أحداً، ولا يشرك في عبادة الله تعالى غيره."]], "m": "بعد ذكر جزاء أهل الشرك والأهواء ناسب ذكر جزاء أهل الإيمان والتقوى: إن الذين آمنوا بالله ورسوله ولقائه، وعملوا الصالحات فأدّوا الفرائض وسارعوا في النوافل، كانت لهم في علم الله بساتين الفردوس منزلاً يُكرمون فيه، والفردوس أعلى الجنة وأوسطها، قال ﷺ: «إن سألتم الله فاسألوه الفردوس، فإنها أوسط الجنة وأعلى الجنة، وفوقها عرش الرحمن، ومنه تفجّر أنهار الجنة»، ماكثين فيها أبداً لا يطلبون عنها تحوّلاً، إذ نعيمها لا يُملّ وسرورها لا يُنغّص بموت ولا مرض ولا تعب. ولما قال اليهود: أوتينا التوراة وفيها علم كل شيء، نزل: قل لو كان ماء البحر مداداً، وكل غصن في أشجار الدنيا قلماً، لنفد البحر والأغصان ولم تنفد كلمات ربي التي تحمل العلوم والمعارف الإلهية، ولو جئنا بمثله مدداً. قل للمشركين الذين يطلبون المعجزات: إنما أنا بشر مثلكم لا أقدر على ما لا تقدرون عليه، والفرق أنه يوحى إليّ أنما معبودكم الحق إله واحد. فمن كان يأمل لقاء ربه خوفاً منه وطمعاً فيه، فليعمل عملاً صالحاً وهو مؤمن، ولا يشرك بعبادة ربه أحداً، فإن الشرك محبط للعمل، وبهذا يكون رجاؤه صادقاً.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان أفضل الجنان، وهو الفردوس الأعلى.", "علم الله غير متناهٍ، لأن كلماته غير متناهية.", "تقرير صفة الكلام لله تعالى.", "تقرير بشرية النبي ﷺ، وأنه ليس روحاً ولا نوراً فحسب كما يقول الغلاة الباطنية.", "تقرير التوحيد والتنديد بالشرك."], "k": "«فليعمل عملاً صالحاً ولا يشرك بعبادة ربه أحداً»… عمل صالح أنويه اليوم، هل أخلصه من الرياء؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 206;
insert into public.tdb_cards(topic, i, body) select 206, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠٢ – ١٠٦", "q": "أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓاْ أَن يَتَّخِذُواْ عِبَادِي مِن دُونِيٓ أَوۡلِيَآءَۚ إِنَّآ أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ نُزُلٗا ﴿١٠٢﴾ قُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ أَعۡمَٰلًا ﴿١٠٣﴾ ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ صُنۡعًا ﴿١٠٤﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَلِقَآئِهِۦ فَحَبِطَتۡ أَعۡمَٰلُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَزۡنٗا ﴿١٠٥﴾ ذَٰلِكَ جَزَآؤُهُمۡ جَهَنَّمُ بِمَا كَفَرُواْ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَرُسُلِي هُزُوًا ﴿١٠٦﴾", "w": [["أفحسب الذين كفروا", "الاستفهام للتقريع والتوبيخ."], ["أن يتخذوا عبادي", "كالملائكة وعيسى ابن مريم والعزير وغيرهم."], ["أولياء", "أرباباً يعبدونهم بأنواع من العبادات."], ["نزلاً", "ما يُعدّ للضيف من قرى، وهو طعامه وشرابه ومنامه."], ["ضلّ سعيهم", "بطل عملهم وفسد عليهم فلم ينتفعوا به."], ["يحسنون صنعاً", "يعملون عملاً يجازون عليه بالخير وحسن الجزاء."], ["بآيات ربهم", "بالقرآن وما فيه من دلائل التوحيد والأحكام الشرعية."], ["ولقائه", "كفروا بالبعث والجزاء."], ["وزناً", "لا نجعل لهم قدراً ولا قيمة، بل نزدريهم ونذمّهم."], ["ذلك", "أُطلق بدل «أولئك» لأنهم بكفرهم وحبوط أعمالهم أصبحوا غثاءً كغثاء السيل لا خير فيه ولا وزن له."]], "m": "ينكر تعالى على المشركين ظنّهم أن اتخاذهم عباده من دونه أولياء يعبدونهم، كالملائكة حيث عبدهم بعض العرب، والمسيح حيث عبده النصارى، والعزير حيث عبده بعض اليهود، لا يغضبه ولا يعاقبهم عليه، وكيف لا وقد أعدّ جهنم للكافرين دار ضيافة، فيها طعامهم وشرابهم وفراشهم؟ ثم قال مشوّقاً للخبر: قل هل ننبئكم بالأخسرين أعمالاً؟ الذين بطل سعيهم في الحياة الدنيا وهم يحسبون أنهم يحسنون عملاً، أولئك الذين كفروا بآيات ربهم ولقائه فلم يعملوا العمل الذي يرضيه، وهو الإيمان الصحيح والعمل الصالح الذي شرعه، فحبطت أعمالهم لأنها شرك وكفر وفساد، فلا نقيم لهم يوم القيامة وزناً، فإن أحدهم لا يزن جناح بعوضة. ذلك المذكور من غثاء الخلق جزاؤهم جهنم بسبب كفرهم واستهزائهم بآيات ربهم ورسله، فكان الحكم عادلاً والجزاء موافقاً.", "h": ["تقرير شرك من يتخذ الملائكة أو الأنبياء أو الأولياء آلهة يعبدونهم تحت شعار التقرب إلى الله تعالى والاستشفاع بهم.", "تقرير هلاك أصحاب الأهواء الذين يعبدون الله تعالى بغير ما شرع، ويتوسّلون إليه بغير ما جعله وسيلة لرضاه وجنته، كالخوارج والرهبان من النصارى وغلاة المبتدعة في العقائد والعبادات والأحكام الشرعية.", "لا قيمة ولا ثقل ولا وزن لعمل لا يوافق رضا الله تعالى، كما لا وزن عند الله تعالى لصاحبه، وإن مات خوفاً من الله أو شوقاً إليه."], "k": "«وهم يحسبون أنهم يحسنون صنعاً»… هل أزن عملي بميزان الشرع، لا بحسن ظني به؟"}, {"lbl": "الآيات ١٠٧ – ١١٠", "q": "إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ كَانَتۡ لَهُمۡ جَنَّـٰتُ ٱلۡفِرۡدَوۡسِ نُزُلًا ﴿١٠٧﴾ خَٰلِدِينَ فِيهَا لَا يَبۡغُونَ عَنۡهَا حِوَلٗا ﴿١٠٨﴾ قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادٗا لِّكَلِمَٰتِ رَبِّي لَنَفِدَ ٱلۡبَحۡرُ قَبۡلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّي وَلَوۡ جِئۡنَا بِمِثۡلِهِۦ مَدَدٗا ﴿١٠٩﴾ قُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَمَن كَانَ يَرۡجُواْ لِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلٗا صَٰلِحٗا وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا ﴿١١٠﴾", "w": [["كانت لهم", "جزاء إيمانهم وعملهم الصالح."], ["الفردوس نزلاً", "وسط الجنة وأعلاها، ونزلاً: منزل إكرام وإنعام."], ["لا يبغون عنها حولاً", "لا يطلبون تحوّلاً منها، لأنه لا خير منها أبداً."], ["لو كان البحر", "ماؤه مداداً."], ["قبل أن تنفد كلمات ربي", "قبل أن تفرغ."], ["يرجو لقاء ربه", "يأمل وينتظر البعث والجزاء يوم القيامة حيث يلقى ربه تعالى."], ["ولا يشرك بعبادة ربه أحداً", "لا يرائي بعمله أحداً، ولا يشرك في عبادة الله تعالى غيره."]], "m": "بعد ذكر جزاء أهل الشرك والأهواء ناسب ذكر جزاء أهل الإيمان والتقوى: إن الذين آمنوا بالله ورسوله ولقائه، وعملوا الصالحات فأدّوا الفرائض وسارعوا في النوافل، كانت لهم في علم الله بساتين الفردوس منزلاً يُكرمون فيه، والفردوس أعلى الجنة وأوسطها، قال ﷺ: «إن سألتم الله فاسألوه الفردوس، فإنها أوسط الجنة وأعلى الجنة، وفوقها عرش الرحمن، ومنه تفجّر أنهار الجنة»، ماكثين فيها أبداً لا يطلبون عنها تحوّلاً، إذ نعيمها لا يُملّ وسرورها لا يُنغّص بموت ولا مرض ولا تعب. ولما قال اليهود: أوتينا التوراة وفيها علم كل شيء، نزل: قل لو كان ماء البحر مداداً، وكل غصن في أشجار الدنيا قلماً، لنفد البحر والأغصان ولم تنفد كلمات ربي التي تحمل العلوم والمعارف الإلهية، ولو جئنا بمثله مدداً. قل للمشركين الذين يطلبون المعجزات: إنما أنا بشر مثلكم لا أقدر على ما لا تقدرون عليه، والفرق أنه يوحى إليّ أنما معبودكم الحق إله واحد. فمن كان يأمل لقاء ربه خوفاً منه وطمعاً فيه، فليعمل عملاً صالحاً وهو مؤمن، ولا يشرك بعبادة ربه أحداً، فإن الشرك محبط للعمل، وبهذا يكون رجاؤه صادقاً.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان أفضل الجنان، وهو الفردوس الأعلى.", "علم الله غير متناهٍ، لأن كلماته غير متناهية.", "تقرير صفة الكلام لله تعالى.", "تقرير بشرية النبي ﷺ، وأنه ليس روحاً ولا نوراً فحسب كما يقول الغلاة الباطنية.", "تقرير التوحيد والتنديد بالشرك."], "k": "«فليعمل عملاً صالحاً ولا يشرك بعبادة ربه أحداً»… عمل صالح أنويه اليوم، هل أخلصه من الرياء؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (207, 19, 1, 15, 'سورة مريم ١ – ١٥', '«ذكر رحمة ربك عبده زكريا»: نداؤه الخفي وبشارته بيحيى، و«يا يحيى خذ الكتاب بقوة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 207) = $j$[{"lbl": "الآيات ١ – ٧", "q": "كٓهيعٓصٓ ﴿١﴾ ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ ﴿٢﴾ إِذۡ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيّٗا ﴿٣﴾ قَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا ﴿٤﴾ وَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا ﴿٥﴾ يَرِثُنِي وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِيّٗا ﴿٦﴾ يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيّٗا ﴿٧﴾", "w": [["كهيعص", "من الحروف المقطّعة، تُقرأ: كاف ها يا عين صاد، ومذهب السلف أن يقال فيها: الله أعلم بمراده."], ["ذكر رحمة ربك", "هذا ذكر رحمة ربك."], ["نادى ربه", "قال: يا رب، يسأله الولد."], ["خفيّاً", "سراً بعيداً عن الرياء."], ["وهن العظم مني", "رقّ وضعف لكبر سني."], ["واشتعل الرأس شيباً", "انتشر الشيب في شعر رأسي انتشار النار في الحطب."], ["ولم أكن بدعائك رب شقيّاً", "إنك لم تخيّبني فيما دعوتك فيه قبل، فلا تخيّبني اليوم."], ["وإني خفت الموالي", "خشيت بني عمي أن يضيّعوا الدين بعد موتي."], ["امرأتي عاقراً", "لا تلد."], ["فهب لي من لدنك وليّاً", "ارزقني من عندك ولداً."], ["ويرث من آل يعقوب", "العلم والنبوة."], ["واجعله رب رضيّاً", "مرضيّاً عندك."], ["سميّاً", "مسمّى بيحيى."]], "m": "كهيعص: من المتشابه الذي نؤمن به ونفوّض معناه لمنزله، فنقول: الله أعلم بمراده. ومما نتلوه عليك في هذا القرآن، فيكون دليلاً على نبوتك، ذكر رحمة ربك التي رحم بها عبده زكريا، حيث كبرت سنه وامرأته عاقر، ورغب في الولد لمصلحة الدعوة، إذ لا يوجد من بني عمه ومواليه كفء يخلفه فيها، فنادى ربه نداءً خفياً: رب إني رقّ عظمي وضعف، وشاب شعر رأسي لكبر سني، ولم أكن بدعائك شقياً في يوم من الأيام، فقد عوّدتني الاستجابة. وإني خفت الموالي أن يضيّعوا دعوة الحق بعد موتي، وكانت امرأتي عاقراً، فهب لي من عندك تفضّلاً، إذ الأسباب غير متوفّرة، ولداً يلي أمر هذه الدعوة بعدي، يرثني فيها، ويرث من آل يعقوب دعوة أبيهم إبراهيم، الحنيفية، واجعله رب عبداً صالحاً ترضاه. فأجابه الرب: يا زكريا إنا نبشّرك بغلام اسمه يحيى، لم نجعل له من قبل من سُمّي باسمه.", "h": ["تقرير نبوة محمد ﷺ بإخباره بهذا الذي أخبر به عن زكريا ﵇.", "استحباب السرّية في الدعاء، لأنه أقرب إلى الاستجابة.", "وجود العقم في بعض النساء.", "قدرة الله تعالى فوق الأسباب، إن شاء تعالى أوقف الأسباب وأعطى بدونها.", "تقرير مبدأ أن الأنبياء لا يورّثون فيما يخلّفون من المال، وإنما يورّثهم الله أولادهم في النبوة والعلم والحكمة."], "k": "«ولم أكن بدعائك رب شقيّاً»… تذكّر استجاباته السابقة؛ فهل يقوّي ذلك رجائي فيما أدعوه الآن؟"}, {"lbl": "الآيات ٨ – ١٥", "q": "قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا ﴿٨﴾ قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنٞ وَقَدۡ خَلَقۡتُكَ مِن قَبۡلُ وَلَمۡ تَكُ شَيۡـٔٗا ﴿٩﴾ قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٖ سَوِيّٗا ﴿١٠﴾ فَخَرَجَ عَلَىٰ قَوۡمِهِۦ مِنَ ٱلۡمِحۡرَابِ فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةٗ وَعَشِيّٗا ﴿١١﴾ يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةٖۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيّٗا ﴿١٢﴾ وَحَنَانٗا مِّن لَّدُنَّا وَزَكَوٰةٗۖ وَكَانَ تَقِيّٗا ﴿١٣﴾ وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا ﴿١٤﴾ وَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا ﴿١٥﴾", "w": [["أنّى يكون لي غلام", "من أي وجه وجهة يكون لي ولد؟"], ["عتيّاً", "يبست مفاصلي وعظامي."], ["آية", "علامة تدلّني على حمل امرأتي."], ["سويّاً", "حال كونك سويّ الخلق ما بك خرس."], ["من المحراب", "المصلّى الذي يصلّي فيه، وهو المسجد."], ["فأوحى إليهم", "أومأ إليهم وأشار."], ["وآتيناه الحكم صبيّاً", "الحكم والحكمة بمعنى واحد، وهما الفقه في الدين ومعرفة أسرار الشرع."], ["وحناناً من لدنّا", "عطفاً على الناس موهوباً له من عندنا."], ["وزكاة", "طهارة من الذنوب والآثام."], ["جبّاراً عصيّاً", "متعالياً لا يقبل الحق، عصيّاً لا يطيع أمر الله عز وجل وأمر والديه."], ["وسلام عليه", "أمان له من الشيطان يوم يولد، ومن فتّاني القبر يوم يموت، ومن الفزع الأكبر يوم يبعث حياً."]], "m": "لما بُشّر زكريا بيحيى قال: رب من أي وجه يكون لي ولد، أمن امرأة غير امرأتي أم منها، وقد بلغت من الكبر حداً يبست فيه عظامي ومفاصلي، وامرأتي عاقر؟ قال: الأمر كما قلت، ولكن قال ربك: إعطاؤك الولد على ضعفك وعقم امرأتك سهل يسير، وقد خلقتك من قبل ولم تك شيئاً. قال: رب اجعل لي علامة على وقت حمل امرأتي، قال: علامتك ألا تكلّم الناس ثلاث ليالٍ وأنت سويّ البدن ما بك خرس ولا مرض. فخرج على قومه من المصلّى فأشار إليهم: أن اذكروا الله بالصلاة والتسبيح بكرة وعشياً. ولما بلغ الغلام قال الله له: يا يحيى خذ التوراة فتعلّمها واعمل بها بجدّ وحزم، ووهبناه الفقه في الكتاب ومعرفة أسرار الشرع وهو صبي لم يبلغ، ورحمة منا ومحبة، وكان ذا حنان على أبويه والمسلمين، وطهارة من الذنوب باستعمال بدنه في طاعة ربه، وكان تقياً خائفاً من ربه فلا يترك فريضة ولا يفعل حراماً، وبرّاً بوالديه لا يؤذيهما أدنى أذى، ولم يكن مستكبراً ولا عاصياً لربه ولا لأبويه، وسلام عليه يوم ولد، ويوم يموت، ويوم يُبعث حياً، فسبحان الله ما أعظم فضله على أوليائه.", "h": ["طلب معرفة السبب الذي يتأتّى به الفعل غير قادح في صاحبه، فسؤال زكريا عن الوجه الذي يأتي به الولد كسؤال إبراهيم عن كيفية إحياء الموتى.", "جواز طلب العلامات الدالة على الشيء للمعرفة.", "آية عجيبة أن يصبح زكريا لا يتكلّم، فيُفهم غيره بالإشارة فقط.", "فضل التسبيح في الصباح والمساء.", "وجوب أخذ القرآن بجدّ وحزم: قراءةً وحفظاً وعملاً بما فيه.", "صدق قول أهل العلم: من حفظ القرآن في سن ما قبل البلوغ فقد أوتي الحكم صبياً.", "وجوب البر بالوالدين ورحمتهما والحنان عليهما والتواضع لهما."], "k": "«يا يحيى خذ الكتاب بقوة»… ما الآية التي أحتاج أن آخذها بقوة هذا الأسبوع؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 207;
insert into public.tdb_cards(topic, i, body) select 207, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٧", "q": "كٓهيعٓصٓ ﴿١﴾ ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ ﴿٢﴾ إِذۡ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيّٗا ﴿٣﴾ قَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا ﴿٤﴾ وَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا ﴿٥﴾ يَرِثُنِي وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِيّٗا ﴿٦﴾ يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيّٗا ﴿٧﴾", "w": [["كهيعص", "من الحروف المقطّعة، تُقرأ: كاف ها يا عين صاد، ومذهب السلف أن يقال فيها: الله أعلم بمراده."], ["ذكر رحمة ربك", "هذا ذكر رحمة ربك."], ["نادى ربه", "قال: يا رب، يسأله الولد."], ["خفيّاً", "سراً بعيداً عن الرياء."], ["وهن العظم مني", "رقّ وضعف لكبر سني."], ["واشتعل الرأس شيباً", "انتشر الشيب في شعر رأسي انتشار النار في الحطب."], ["ولم أكن بدعائك رب شقيّاً", "إنك لم تخيّبني فيما دعوتك فيه قبل، فلا تخيّبني اليوم."], ["وإني خفت الموالي", "خشيت بني عمي أن يضيّعوا الدين بعد موتي."], ["امرأتي عاقراً", "لا تلد."], ["فهب لي من لدنك وليّاً", "ارزقني من عندك ولداً."], ["ويرث من آل يعقوب", "العلم والنبوة."], ["واجعله رب رضيّاً", "مرضيّاً عندك."], ["سميّاً", "مسمّى بيحيى."]], "m": "كهيعص: من المتشابه الذي نؤمن به ونفوّض معناه لمنزله، فنقول: الله أعلم بمراده. ومما نتلوه عليك في هذا القرآن، فيكون دليلاً على نبوتك، ذكر رحمة ربك التي رحم بها عبده زكريا، حيث كبرت سنه وامرأته عاقر، ورغب في الولد لمصلحة الدعوة، إذ لا يوجد من بني عمه ومواليه كفء يخلفه فيها، فنادى ربه نداءً خفياً: رب إني رقّ عظمي وضعف، وشاب شعر رأسي لكبر سني، ولم أكن بدعائك شقياً في يوم من الأيام، فقد عوّدتني الاستجابة. وإني خفت الموالي أن يضيّعوا دعوة الحق بعد موتي، وكانت امرأتي عاقراً، فهب لي من عندك تفضّلاً، إذ الأسباب غير متوفّرة، ولداً يلي أمر هذه الدعوة بعدي، يرثني فيها، ويرث من آل يعقوب دعوة أبيهم إبراهيم، الحنيفية، واجعله رب عبداً صالحاً ترضاه. فأجابه الرب: يا زكريا إنا نبشّرك بغلام اسمه يحيى، لم نجعل له من قبل من سُمّي باسمه.", "h": ["تقرير نبوة محمد ﷺ بإخباره بهذا الذي أخبر به عن زكريا ﵇.", "استحباب السرّية في الدعاء، لأنه أقرب إلى الاستجابة.", "وجود العقم في بعض النساء.", "قدرة الله تعالى فوق الأسباب، إن شاء تعالى أوقف الأسباب وأعطى بدونها.", "تقرير مبدأ أن الأنبياء لا يورّثون فيما يخلّفون من المال، وإنما يورّثهم الله أولادهم في النبوة والعلم والحكمة."], "k": "«ولم أكن بدعائك رب شقيّاً»… تذكّر استجاباته السابقة؛ فهل يقوّي ذلك رجائي فيما أدعوه الآن؟"}, {"lbl": "الآيات ٨ – ١٥", "q": "قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا ﴿٨﴾ قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنٞ وَقَدۡ خَلَقۡتُكَ مِن قَبۡلُ وَلَمۡ تَكُ شَيۡـٔٗا ﴿٩﴾ قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٖ سَوِيّٗا ﴿١٠﴾ فَخَرَجَ عَلَىٰ قَوۡمِهِۦ مِنَ ٱلۡمِحۡرَابِ فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةٗ وَعَشِيّٗا ﴿١١﴾ يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةٖۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيّٗا ﴿١٢﴾ وَحَنَانٗا مِّن لَّدُنَّا وَزَكَوٰةٗۖ وَكَانَ تَقِيّٗا ﴿١٣﴾ وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا ﴿١٤﴾ وَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا ﴿١٥﴾", "w": [["أنّى يكون لي غلام", "من أي وجه وجهة يكون لي ولد؟"], ["عتيّاً", "يبست مفاصلي وعظامي."], ["آية", "علامة تدلّني على حمل امرأتي."], ["سويّاً", "حال كونك سويّ الخلق ما بك خرس."], ["من المحراب", "المصلّى الذي يصلّي فيه، وهو المسجد."], ["فأوحى إليهم", "أومأ إليهم وأشار."], ["وآتيناه الحكم صبيّاً", "الحكم والحكمة بمعنى واحد، وهما الفقه في الدين ومعرفة أسرار الشرع."], ["وحناناً من لدنّا", "عطفاً على الناس موهوباً له من عندنا."], ["وزكاة", "طهارة من الذنوب والآثام."], ["جبّاراً عصيّاً", "متعالياً لا يقبل الحق، عصيّاً لا يطيع أمر الله عز وجل وأمر والديه."], ["وسلام عليه", "أمان له من الشيطان يوم يولد، ومن فتّاني القبر يوم يموت، ومن الفزع الأكبر يوم يبعث حياً."]], "m": "لما بُشّر زكريا بيحيى قال: رب من أي وجه يكون لي ولد، أمن امرأة غير امرأتي أم منها، وقد بلغت من الكبر حداً يبست فيه عظامي ومفاصلي، وامرأتي عاقر؟ قال: الأمر كما قلت، ولكن قال ربك: إعطاؤك الولد على ضعفك وعقم امرأتك سهل يسير، وقد خلقتك من قبل ولم تك شيئاً. قال: رب اجعل لي علامة على وقت حمل امرأتي، قال: علامتك ألا تكلّم الناس ثلاث ليالٍ وأنت سويّ البدن ما بك خرس ولا مرض. فخرج على قومه من المصلّى فأشار إليهم: أن اذكروا الله بالصلاة والتسبيح بكرة وعشياً. ولما بلغ الغلام قال الله له: يا يحيى خذ التوراة فتعلّمها واعمل بها بجدّ وحزم، ووهبناه الفقه في الكتاب ومعرفة أسرار الشرع وهو صبي لم يبلغ، ورحمة منا ومحبة، وكان ذا حنان على أبويه والمسلمين، وطهارة من الذنوب باستعمال بدنه في طاعة ربه، وكان تقياً خائفاً من ربه فلا يترك فريضة ولا يفعل حراماً، وبرّاً بوالديه لا يؤذيهما أدنى أذى، ولم يكن مستكبراً ولا عاصياً لربه ولا لأبويه، وسلام عليه يوم ولد، ويوم يموت، ويوم يُبعث حياً، فسبحان الله ما أعظم فضله على أوليائه.", "h": ["طلب معرفة السبب الذي يتأتّى به الفعل غير قادح في صاحبه، فسؤال زكريا عن الوجه الذي يأتي به الولد كسؤال إبراهيم عن كيفية إحياء الموتى.", "جواز طلب العلامات الدالة على الشيء للمعرفة.", "آية عجيبة أن يصبح زكريا لا يتكلّم، فيُفهم غيره بالإشارة فقط.", "فضل التسبيح في الصباح والمساء.", "وجوب أخذ القرآن بجدّ وحزم: قراءةً وحفظاً وعملاً بما فيه.", "صدق قول أهل العلم: من حفظ القرآن في سن ما قبل البلوغ فقد أوتي الحكم صبياً.", "وجوب البر بالوالدين ورحمتهما والحنان عليهما والتواضع لهما."], "k": "«يا يحيى خذ الكتاب بقوة»… ما الآية التي أحتاج أن آخذها بقوة هذا الأسبوع؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (208, 19, 16, 26, 'سورة مريم ١٦ – ٢٦', '«واذكر في الكتاب مريم»: بشارة جبريل ﵇ لها بغلام زكي، والمخاض إلى جذع النخلة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 208) = $j$[{"lbl": "الآيات ١٦ – ٢١", "q": "وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مَرۡيَمَ إِذِ ٱنتَبَذَتۡ مِنۡ أَهۡلِهَا مَكَانٗا شَرۡقِيّٗا ﴿١٦﴾ فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابٗا فَأَرۡسَلۡنَآ إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرٗا سَوِيّٗا ﴿١٧﴾ قَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا ﴿١٨﴾ قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمٗا زَكِيّٗا ﴿١٩﴾ قَالَتۡ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞ وَلَمۡ أَكُ بَغِيّٗا ﴿٢٠﴾ قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٞۖ وَلِنَجۡعَلَهُۥٓ ءَايَةٗ لِّلنَّاسِ وَرَحۡمَةٗ مِّنَّاۚ وَكَانَ أَمۡرٗا مَّقۡضِيّٗا ﴿٢١﴾", "w": [["واذكر في الكتاب", "في القرآن."], ["مريم", "بنت عمران، والدة عيسى ﵇، أي خبرها وقصتها."], ["إذ انتبذت", "حين اعتزلت أهلها باتخاذها مكاناً خاصاً تخلو فيه بنفسها."], ["شرقيّاً", "شرق الدار التي بها أهلها."], ["حجاباً", "ساتراً يسترها عن أهلها وذويها."], ["روحنا", "جبريل ﵇."], ["بشراً سويّاً", "تام الخلق حتى لا تفزع ولا تُروّع منه."], ["إن كنت تقيّاً", "عاملاً بإيمانك وتقواك لله فابتعد عني ولا تؤذني."], ["غلاماً زكيّاً", "ولداً طاهراً لم يتلوّث بذنب قط."], ["ولم يمسسني بشر", "لم أتزوج."], ["ولم أك بغيّاً", "زانية."], ["قال كذلك", "الأمر كذلك، وهو خلق غلام منك من غير أب."], ["هو عليّ هيّن", "ما هو إلا أن ينفخ رسولنا في كمّ درعك حتى يكون الولد."], ["ولنجعله آية للناس", "على عظيم قدرتنا."], ["ورحمة منا", "ليكون الولد رحمة بمن آمن به واتبع ما جاء به."], ["أمراً مقضيّاً", "حكم الله به وفرغ منه فهو كائن لا محالة."]], "m": "هذه بداية قصة مريم: اذكر في القرآن خبرها ليكون دليلاً على نبوتك، إذ اعتزلت أهلها في موضع شرقي دار قومها، ولا حجة للنصارى في اتخاذهم المشرق قبلة، فقبلة كل مصلٍّ لله الكعبة. فاتخذت من دونهم ساتراً، فأرسل الله إليها جبريل في صورة بشر سويّ الخلقة، فدخل عليها، فقالت: إني أحتمي بالرحمن الذي يرحم الضعيفات مثلي منك، إن كنت مؤمناً تقياً فاذهب عني ولا تروّعني. قال: إنما أنا رسول ربك لأهب لك غلاماً طاهراً لا يتلوّث بذنب. قالت: من أي وجه يأتيني الولد ولم أتزوج ولم أك زانية؟ قال: الأمر كما قلت، ولكن ربك قال: خلقه بدون أب هيّن عليّ، ولنجعله آية للناس دالة على قدرتنا على خلق آدم بلا أب ولا أم، وعلى البعث الآخر، ورحمة منا لكل من آمن به واتبع طريقته، وكان أمراً حكم الله فيه وقضى به فهو كائن. ونفخ جبريل في جيب قميصها فسرت النفخة في جسمها فحملت به.", "h": ["بيان شرف مريم وكرامتها على ربها.", "فضيلة العفّة والحياء.", "كون الملائكة يتشكّلون كما أذن الله تعالى لهم.", "مشروعية التعوّذ بالله من كل ما يُخاف من إنسان أو جان.", "التقوى مانعة من فعل الأذى بالناس أو إدخال الضرر عليهم.", "خلق عيسى آية مبصرة تتجلّى فيها قدرة الله تعالى على الخلق بدءاً وإعادة."], "k": "«إني أعوذ بالرحمن منك إن كنت تقيّاً»… حين أخاف، هل أفزع أولاً إلى الاستعاذة بالرحمن؟"}, {"lbl": "الآيات ٢٢ – ٢٦", "q": "۞فَحَمَلَتۡهُ فَٱنتَبَذَتۡ بِهِۦ مَكَانٗا قَصِيّٗا ﴿٢٢﴾ فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا ﴿٢٣﴾ فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا ﴿٢٤﴾ وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا ﴿٢٥﴾ فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا ﴿٢٦﴾", "w": [["فانتبذت به", "فاعتزلت به."], ["مكاناً قصيّاً", "بعيداً من أهلها."], ["فأجاءها المخاض", "ألجأها الطلق واضطرّها وجع الولادة."], ["إلى جذع النخلة", "لتعتمد عليها وهي تعاني من آلام الولادة."], ["نسياً منسيّاً", "شيئاً متروكاً لا يُعرف ولا يُذكر."], ["فناداها من تحتها", "عيسى ﵇ بعدما وضعته."], ["تحتك سريّاً", "نهراً يقال له سريّ."], ["رطباً جنيّاً", "ما طاب وصلح للاجتناء."], ["فكلي واشربي", "كلي من الرطب واشربي من السريّ."], ["وقرّي عيناً", "طيبي نفساً وافرحي بولادتك إياي ولا تحزني."], ["نذرت للرحمن صوماً", "إمساكاً عن الكلام وصمتاً."]], "m": "ما زال السياق في قصة مريم: بعد أن نفخ جبريل في جيب قميصها حملته فوراً، فاعتزلت به في مكان بعيد، فألجأها وجع الطلق إلى جذع النخلة تعتمد عليه، فلما وضعته قالت متحسّرة: يا ليتني متّ قبل هذا الوقت وكنت شيئاً متروكاً لا يُذكر. فناداها عيسى من تحتها يحملها على الصبر: ألا تحزني، قد جعل ربك تحتك نهراً، وهزّي إليك بجذع النخلة تتساقط عليك رطباً طيباً، فكلي من الرطب واشربي من النهر، وطيبي نفساً وافرحي بولدك، فإن سألك أحد من البشر عن حالك أو ولدك فلا تكلّميه، واكتفي بقولك: إني نذرت للرحمن صمتاً فلن أكلّم اليوم إنسياً. هذا كله من قول عيسى، أنطقه الله كرامة لها ليذهب عنها حزنها وألمها النفسي من الولادة وهي بكر لم تتزوج.", "h": ["من مظاهر قدرة الله تعالى حملها ووضعها في خلال ساعة من نهار.", "إثبات كرامات الله لأوليائه، إذ أكرم الله تعالى مريم بنطق عيسى ساعة وضعه فأرشدها وبشّرها وأذهب عنها الألم والحزن، وأثمر لها النخلة، وأجرى لها النهر.", "تقرير نظام الأسباب التي في مكنة الإنسان القيام بها؛ فإن الله تعالى أثمر لمريم النخلة، إذ هذا لا يمكنها القيام به، ثم أمرها أن تحرّك النخلة من جذعها ليتساقط عليها الرطب، إذ هذا في استطاعتها.", "مشروعية النذر، إلا أنه بالامتناع عن الكلام منسوخ في الإسلام."], "k": "«وهزّي إليك بجذع النخلة»… امرأة في آلام الولادة أُمرت أن تأخذ بالسبب؛ فما السبب الذي أتركه أنا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 208;
insert into public.tdb_cards(topic, i, body) select 208, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٦ – ٢١", "q": "وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مَرۡيَمَ إِذِ ٱنتَبَذَتۡ مِنۡ أَهۡلِهَا مَكَانٗا شَرۡقِيّٗا ﴿١٦﴾ فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابٗا فَأَرۡسَلۡنَآ إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرٗا سَوِيّٗا ﴿١٧﴾ قَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا ﴿١٨﴾ قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمٗا زَكِيّٗا ﴿١٩﴾ قَالَتۡ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞ وَلَمۡ أَكُ بَغِيّٗا ﴿٢٠﴾ قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٞۖ وَلِنَجۡعَلَهُۥٓ ءَايَةٗ لِّلنَّاسِ وَرَحۡمَةٗ مِّنَّاۚ وَكَانَ أَمۡرٗا مَّقۡضِيّٗا ﴿٢١﴾", "w": [["واذكر في الكتاب", "في القرآن."], ["مريم", "بنت عمران، والدة عيسى ﵇، أي خبرها وقصتها."], ["إذ انتبذت", "حين اعتزلت أهلها باتخاذها مكاناً خاصاً تخلو فيه بنفسها."], ["شرقيّاً", "شرق الدار التي بها أهلها."], ["حجاباً", "ساتراً يسترها عن أهلها وذويها."], ["روحنا", "جبريل ﵇."], ["بشراً سويّاً", "تام الخلق حتى لا تفزع ولا تُروّع منه."], ["إن كنت تقيّاً", "عاملاً بإيمانك وتقواك لله فابتعد عني ولا تؤذني."], ["غلاماً زكيّاً", "ولداً طاهراً لم يتلوّث بذنب قط."], ["ولم يمسسني بشر", "لم أتزوج."], ["ولم أك بغيّاً", "زانية."], ["قال كذلك", "الأمر كذلك، وهو خلق غلام منك من غير أب."], ["هو عليّ هيّن", "ما هو إلا أن ينفخ رسولنا في كمّ درعك حتى يكون الولد."], ["ولنجعله آية للناس", "على عظيم قدرتنا."], ["ورحمة منا", "ليكون الولد رحمة بمن آمن به واتبع ما جاء به."], ["أمراً مقضيّاً", "حكم الله به وفرغ منه فهو كائن لا محالة."]], "m": "هذه بداية قصة مريم: اذكر في القرآن خبرها ليكون دليلاً على نبوتك، إذ اعتزلت أهلها في موضع شرقي دار قومها، ولا حجة للنصارى في اتخاذهم المشرق قبلة، فقبلة كل مصلٍّ لله الكعبة. فاتخذت من دونهم ساتراً، فأرسل الله إليها جبريل في صورة بشر سويّ الخلقة، فدخل عليها، فقالت: إني أحتمي بالرحمن الذي يرحم الضعيفات مثلي منك، إن كنت مؤمناً تقياً فاذهب عني ولا تروّعني. قال: إنما أنا رسول ربك لأهب لك غلاماً طاهراً لا يتلوّث بذنب. قالت: من أي وجه يأتيني الولد ولم أتزوج ولم أك زانية؟ قال: الأمر كما قلت، ولكن ربك قال: خلقه بدون أب هيّن عليّ، ولنجعله آية للناس دالة على قدرتنا على خلق آدم بلا أب ولا أم، وعلى البعث الآخر، ورحمة منا لكل من آمن به واتبع طريقته، وكان أمراً حكم الله فيه وقضى به فهو كائن. ونفخ جبريل في جيب قميصها فسرت النفخة في جسمها فحملت به.", "h": ["بيان شرف مريم وكرامتها على ربها.", "فضيلة العفّة والحياء.", "كون الملائكة يتشكّلون كما أذن الله تعالى لهم.", "مشروعية التعوّذ بالله من كل ما يُخاف من إنسان أو جان.", "التقوى مانعة من فعل الأذى بالناس أو إدخال الضرر عليهم.", "خلق عيسى آية مبصرة تتجلّى فيها قدرة الله تعالى على الخلق بدءاً وإعادة."], "k": "«إني أعوذ بالرحمن منك إن كنت تقيّاً»… حين أخاف، هل أفزع أولاً إلى الاستعاذة بالرحمن؟"}, {"lbl": "الآيات ٢٢ – ٢٦", "q": "۞فَحَمَلَتۡهُ فَٱنتَبَذَتۡ بِهِۦ مَكَانٗا قَصِيّٗا ﴿٢٢﴾ فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا ﴿٢٣﴾ فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا ﴿٢٤﴾ وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا ﴿٢٥﴾ فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا ﴿٢٦﴾", "w": [["فانتبذت به", "فاعتزلت به."], ["مكاناً قصيّاً", "بعيداً من أهلها."], ["فأجاءها المخاض", "ألجأها الطلق واضطرّها وجع الولادة."], ["إلى جذع النخلة", "لتعتمد عليها وهي تعاني من آلام الولادة."], ["نسياً منسيّاً", "شيئاً متروكاً لا يُعرف ولا يُذكر."], ["فناداها من تحتها", "عيسى ﵇ بعدما وضعته."], ["تحتك سريّاً", "نهراً يقال له سريّ."], ["رطباً جنيّاً", "ما طاب وصلح للاجتناء."], ["فكلي واشربي", "كلي من الرطب واشربي من السريّ."], ["وقرّي عيناً", "طيبي نفساً وافرحي بولادتك إياي ولا تحزني."], ["نذرت للرحمن صوماً", "إمساكاً عن الكلام وصمتاً."]], "m": "ما زال السياق في قصة مريم: بعد أن نفخ جبريل في جيب قميصها حملته فوراً، فاعتزلت به في مكان بعيد، فألجأها وجع الطلق إلى جذع النخلة تعتمد عليه، فلما وضعته قالت متحسّرة: يا ليتني متّ قبل هذا الوقت وكنت شيئاً متروكاً لا يُذكر. فناداها عيسى من تحتها يحملها على الصبر: ألا تحزني، قد جعل ربك تحتك نهراً، وهزّي إليك بجذع النخلة تتساقط عليك رطباً طيباً، فكلي من الرطب واشربي من النهر، وطيبي نفساً وافرحي بولدك، فإن سألك أحد من البشر عن حالك أو ولدك فلا تكلّميه، واكتفي بقولك: إني نذرت للرحمن صمتاً فلن أكلّم اليوم إنسياً. هذا كله من قول عيسى، أنطقه الله كرامة لها ليذهب عنها حزنها وألمها النفسي من الولادة وهي بكر لم تتزوج.", "h": ["من مظاهر قدرة الله تعالى حملها ووضعها في خلال ساعة من نهار.", "إثبات كرامات الله لأوليائه، إذ أكرم الله تعالى مريم بنطق عيسى ساعة وضعه فأرشدها وبشّرها وأذهب عنها الألم والحزن، وأثمر لها النخلة، وأجرى لها النهر.", "تقرير نظام الأسباب التي في مكنة الإنسان القيام بها؛ فإن الله تعالى أثمر لمريم النخلة، إذ هذا لا يمكنها القيام به، ثم أمرها أن تحرّك النخلة من جذعها ليتساقط عليها الرطب، إذ هذا في استطاعتها.", "مشروعية النذر، إلا أنه بالامتناع عن الكلام منسوخ في الإسلام."], "k": "«وهزّي إليك بجذع النخلة»… امرأة في آلام الولادة أُمرت أن تأخذ بالسبب؛ فما السبب الذي أتركه أنا؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (209, 19, 27, 40, 'سورة مريم ٢٧ – ٤٠', '«إني عبد الله آتاني الكتاب وجعلني نبيّاً»، و«ذلك عيسى ابن مريم قول الحق»، و«وأنذرهم يوم الحسرة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 209) = $j$[{"lbl": "الآيات ٢٧ – ٣٣", "q": "فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُواْ يَٰمَرۡيَمُ لَقَدۡ جِئۡتِ شَيۡـٔٗا فَرِيّٗا ﴿٢٧﴾ يَـٰٓأُخۡتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءٖ وَمَا كَانَتۡ أُمُّكِ بَغِيّٗا ﴿٢٨﴾ فَأَشَارَتۡ إِلَيۡهِۖ قَالُواْ كَيۡفَ نُكَلِّمُ مَن كَانَ فِي ٱلۡمَهۡدِ صَبِيّٗا ﴿٢٩﴾ قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا ﴿٣٠﴾ وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا ﴿٣١﴾ وَبَرَّۢا بِوَٰلِدَتِي وَلَمۡ يَجۡعَلۡنِي جَبَّارٗا شَقِيّٗا ﴿٣٢﴾ وَٱلسَّلَٰمُ عَلَيَّ يَوۡمَ وُلِدتُّ وَيَوۡمَ أَمُوتُ وَيَوۡمَ أُبۡعَثُ حَيّٗا ﴿٣٣﴾", "w": [["فأتت به", "بولدها عيسى ﵇."], ["جئت شيئاً فريّاً", "عظيماً، حيث أتيت بولد من غير أب."], ["يا أخت هارون", "يا أخت الرجل الصالح هارون."], ["امرأ سوء", "رجلاً يأتي الفواحش."], ["فأشارت إليه", "إلى عيسى وهو في المهد."], ["آتاني الكتاب", "الإنجيل، باعتبار ما يكون مستقبلاً."], ["مباركاً أين ما كنت", "حيثما وُجدت كانت البركة فيّ ومعي، ينتفع الناس بي."], ["وبرّاً بوالدتي", "محسناً بها مطيعاً لها لا ينالها مني أدنى أذى."], ["جبّاراً شقيّاً", "ظالماً متعالياً، ولا عاصياً لربي خارجاً عن طاعته."]], "m": "ما زال السياق في قصة مريم مع قومها: بعد أن تماثلت للشفاء حملت ولدها وأتت به قومها، فما إن رأوهما حتى قال قائلهم: يا مريم لقد جئت أمراً عظيماً، ولداً من غير أب! يا أخت هارون، نسبوها إلى عبد صالح يسمّى هارون، ما كان أبوك عمران رجلاً يأتي الفواحش، وما كانت أمك زانية، فكيف حصل لك هذا وأنت بنت البيت الطاهر؟ فأشارت إلى عيسى الرضيع: سلوه يخبركم، لما سبق أن ناداها ساعة وضعه. فردّوا مستخفّين متعجّبين: كيف نكلّم من كان في المهد صبياً؟ فأنطق الله عيسى فقال: إني عبد الله آتاني الكتاب وجعلني نبياً، وجعلني مباركاً أينما كنت، وأوصاني بالصلاة والزكاة ما دمت حياً، وبرّاً بوالدتي، ولم يجعلني جباراً شقياً. وكان عيسى كما أخبر عن نفسه: عبداً لله أُنزل عليه الإنجيل، ورسولاً إلى بني إسرائيل، مباركاً يشفي المرضى ويحيي الموتى بإذن الله، مقيماً للصلاة مؤدّياً للزكاة طوال حياته. والسلام عليه، أي الأمان التام، يوم ولد فلم يقربه شيطان، ويوم يموت فلا يُفتن في قبره، ويوم يُبعث حياً فلا يحزنه الفزع الأكبر.", "h": ["تقرير نبوة محمد ﷺ، وعبودية عيسى ونبوته ﵇.", "آية نطق عيسى في المهد، وإخباره بما أولاه الله من الكمالات.", "وجوب برّ الوالدين بالإحسان بهما وطاعتهما بالمعروف وكفّ الأذى عنهما.", "التنديد بالتعالي والكبر والظلم والشقاوة، التي هي التمرّد والعصيان."], "k": "«وجعلني مباركاً أين ما كنت»… أين أكون اليوم، وهل يجد الناس معي بركة؟"}, {"lbl": "الآيات ٣٤ – ٤٠", "q": "ذَٰلِكَ عِيسَى ٱبۡنُ مَرۡيَمَۖ قَوۡلَ ٱلۡحَقِّ ٱلَّذِي فِيهِ يَمۡتَرُونَ ﴿٣٤﴾ مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٖۖ سُبۡحَٰنَهُۥٓۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ ﴿٣٥﴾ وَإِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٣٦﴾ فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِن مَّشۡهَدِ يَوۡمٍ عَظِيمٍ ﴿٣٧﴾ أَسۡمِعۡ بِهِمۡ وَأَبۡصِرۡ يَوۡمَ يَأۡتُونَنَا لَٰكِنِ ٱلظَّـٰلِمُونَ ٱلۡيَوۡمَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٣٨﴾ وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِيَ ٱلۡأَمۡرُ وَهُمۡ فِي غَفۡلَةٖ وَهُمۡ لَا يُؤۡمِنُونَ ﴿٣٩﴾ إِنَّا نَحۡنُ نَرِثُ ٱلۡأَرۡضَ وَمَنۡ عَلَيۡهَا وَإِلَيۡنَا يُرۡجَعُونَ ﴿٤٠﴾", "w": [["ذلك عيسى ابن مريم", "هذا الذي بيّنت لكم صفته وأخبرتكم خبره هو عيسى ابن مريم."], ["قول الحق", "هو قول الحق الذي أخبر تعالى به."], ["يمترون", "يشكّون."], ["ما كان لله أن يتخذ", "ليس من شأن الله أن يتخذ ولداً، وهو الذي يقول للشيء كن فيكون."], ["سبحانه", "تنزيهاً له عن الولد والشريك والشبيه والنظير."], ["صراط مستقيم", "طريق مستقيم لا يضل سالكه."], ["فاختلف الأحزاب", "في شأن عيسى، فقال اليهود: ساحر وابن زنا، وقال النصارى: هو الله وابن الله، تعالى الله عما يصفون."], ["من مشهد يوم عظيم", "هو يوم القيامة."], ["أسمع بهم وأبصر", "ما أسمعهم وما أبصرهم يوم القيامة عند معاينة العذاب."], ["وأنذرهم يوم الحسرة", "خوّفهم بما يقع يوم القيامة من الحسرة والندامة، حين يرث أهل الجنة منازلهم فيها، ويرثون هم منازل أهل الجنة في النار."]], "m": "بعد أن قصّ قصة مريم وكلام عيسى في المهد قال: ذلك الذي بيّنت لكم صفته هو عيسى ابن مريم، وما أخبرتكم به هو قول الحق الذي فيه يشكّون، إذ قال اليهود: ابن زنا وساحر، وقال النصارى: هو الله، وابن الله، وثالث ثلاثة. ما كان لله أن يتخذ من ولد، وكيف وهو الغني عما سواه، سبحانه، إذا قضى أمراً فإنما يقول له كن فيكون، فعيسى كان بكلمة الله له: كن. وقال عيسى لبني إسرائيل: وإن الله ربي وربكم فاعبدوه وحده بما شرع، هذا صراط مستقيم مفضٍ بسالكه إلى السعادة. فاختلف الأحزاب من بينهم في شأنه: فمن قائل هو الله، ومن قائل ابن الله، ومن قائل هو وأمه إلهان من دون الله، فويل للذين كفروا من مشهد يوم القيامة ذي الأهوال. ما أسمعهم وما أبصرهم يوم يأتوننا، وقد كانوا في الدنيا متعامين متصامّين عن الحجج، ولكن حين لا ينفعهم سمع ولا بصر، لكن الظالمون اليوم في ضلال مبين. وأنذرهم يوم الحسرة إذ قُضي الأمر: حين يرث الموحّدون منازل المشركين في الجنة، ويرث المشركون منازل الموحّدين في النار، وحين يؤتى بالموت في صورة كبش فيُذبح بين الجنة والنار، وينادي منادٍ: يا أهل الجنة خلود فلا موت، ويا أهل النار خلود فلا موت، وهم اليوم في غفلة وهم لا يؤمنون. إنا نحن نرث الأرض ومن عليها وإلينا يرجعون، فلا تحزن وامض في دعوتك.", "h": ["تقرير أن عيسى عبد الله ورسوله، وليس كما قال اليهود، ولا كما قالت النصارى.", "استحالة اتخاذ الله الولد، وهو الذي يقول للشيء كن فيكون.", "تقرير التوحيد على لسان عيسى ﵇.", "الإخبار بما عليه النصارى من خلاف في شأن عيسى ﵇.", "بيان سبب الحسرة يوم القيامة، وهو الكفر بالله والشرك به.", "تقرير فناء الدنيا ورجوع الناس إلى ربهم بعد بعثهم، وهو تقرير لعقيدة البعث والجزاء التي تعالجها السور المكية."], "k": "«وأنذرهم يوم الحسرة إذ قضي الأمر وهم في غفلة»… ما الغفلة التي أخشى أن أتحسّر عليها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 209;
insert into public.tdb_cards(topic, i, body) select 209, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٧ – ٣٣", "q": "فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُواْ يَٰمَرۡيَمُ لَقَدۡ جِئۡتِ شَيۡـٔٗا فَرِيّٗا ﴿٢٧﴾ يَـٰٓأُخۡتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءٖ وَمَا كَانَتۡ أُمُّكِ بَغِيّٗا ﴿٢٨﴾ فَأَشَارَتۡ إِلَيۡهِۖ قَالُواْ كَيۡفَ نُكَلِّمُ مَن كَانَ فِي ٱلۡمَهۡدِ صَبِيّٗا ﴿٢٩﴾ قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا ﴿٣٠﴾ وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا ﴿٣١﴾ وَبَرَّۢا بِوَٰلِدَتِي وَلَمۡ يَجۡعَلۡنِي جَبَّارٗا شَقِيّٗا ﴿٣٢﴾ وَٱلسَّلَٰمُ عَلَيَّ يَوۡمَ وُلِدتُّ وَيَوۡمَ أَمُوتُ وَيَوۡمَ أُبۡعَثُ حَيّٗا ﴿٣٣﴾", "w": [["فأتت به", "بولدها عيسى ﵇."], ["جئت شيئاً فريّاً", "عظيماً، حيث أتيت بولد من غير أب."], ["يا أخت هارون", "يا أخت الرجل الصالح هارون."], ["امرأ سوء", "رجلاً يأتي الفواحش."], ["فأشارت إليه", "إلى عيسى وهو في المهد."], ["آتاني الكتاب", "الإنجيل، باعتبار ما يكون مستقبلاً."], ["مباركاً أين ما كنت", "حيثما وُجدت كانت البركة فيّ ومعي، ينتفع الناس بي."], ["وبرّاً بوالدتي", "محسناً بها مطيعاً لها لا ينالها مني أدنى أذى."], ["جبّاراً شقيّاً", "ظالماً متعالياً، ولا عاصياً لربي خارجاً عن طاعته."]], "m": "ما زال السياق في قصة مريم مع قومها: بعد أن تماثلت للشفاء حملت ولدها وأتت به قومها، فما إن رأوهما حتى قال قائلهم: يا مريم لقد جئت أمراً عظيماً، ولداً من غير أب! يا أخت هارون، نسبوها إلى عبد صالح يسمّى هارون، ما كان أبوك عمران رجلاً يأتي الفواحش، وما كانت أمك زانية، فكيف حصل لك هذا وأنت بنت البيت الطاهر؟ فأشارت إلى عيسى الرضيع: سلوه يخبركم، لما سبق أن ناداها ساعة وضعه. فردّوا مستخفّين متعجّبين: كيف نكلّم من كان في المهد صبياً؟ فأنطق الله عيسى فقال: إني عبد الله آتاني الكتاب وجعلني نبياً، وجعلني مباركاً أينما كنت، وأوصاني بالصلاة والزكاة ما دمت حياً، وبرّاً بوالدتي، ولم يجعلني جباراً شقياً. وكان عيسى كما أخبر عن نفسه: عبداً لله أُنزل عليه الإنجيل، ورسولاً إلى بني إسرائيل، مباركاً يشفي المرضى ويحيي الموتى بإذن الله، مقيماً للصلاة مؤدّياً للزكاة طوال حياته. والسلام عليه، أي الأمان التام، يوم ولد فلم يقربه شيطان، ويوم يموت فلا يُفتن في قبره، ويوم يُبعث حياً فلا يحزنه الفزع الأكبر.", "h": ["تقرير نبوة محمد ﷺ، وعبودية عيسى ونبوته ﵇.", "آية نطق عيسى في المهد، وإخباره بما أولاه الله من الكمالات.", "وجوب برّ الوالدين بالإحسان بهما وطاعتهما بالمعروف وكفّ الأذى عنهما.", "التنديد بالتعالي والكبر والظلم والشقاوة، التي هي التمرّد والعصيان."], "k": "«وجعلني مباركاً أين ما كنت»… أين أكون اليوم، وهل يجد الناس معي بركة؟"}, {"lbl": "الآيات ٣٤ – ٤٠", "q": "ذَٰلِكَ عِيسَى ٱبۡنُ مَرۡيَمَۖ قَوۡلَ ٱلۡحَقِّ ٱلَّذِي فِيهِ يَمۡتَرُونَ ﴿٣٤﴾ مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٖۖ سُبۡحَٰنَهُۥٓۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ ﴿٣٥﴾ وَإِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٣٦﴾ فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِن مَّشۡهَدِ يَوۡمٍ عَظِيمٍ ﴿٣٧﴾ أَسۡمِعۡ بِهِمۡ وَأَبۡصِرۡ يَوۡمَ يَأۡتُونَنَا لَٰكِنِ ٱلظَّـٰلِمُونَ ٱلۡيَوۡمَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٣٨﴾ وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِيَ ٱلۡأَمۡرُ وَهُمۡ فِي غَفۡلَةٖ وَهُمۡ لَا يُؤۡمِنُونَ ﴿٣٩﴾ إِنَّا نَحۡنُ نَرِثُ ٱلۡأَرۡضَ وَمَنۡ عَلَيۡهَا وَإِلَيۡنَا يُرۡجَعُونَ ﴿٤٠﴾", "w": [["ذلك عيسى ابن مريم", "هذا الذي بيّنت لكم صفته وأخبرتكم خبره هو عيسى ابن مريم."], ["قول الحق", "هو قول الحق الذي أخبر تعالى به."], ["يمترون", "يشكّون."], ["ما كان لله أن يتخذ", "ليس من شأن الله أن يتخذ ولداً، وهو الذي يقول للشيء كن فيكون."], ["سبحانه", "تنزيهاً له عن الولد والشريك والشبيه والنظير."], ["صراط مستقيم", "طريق مستقيم لا يضل سالكه."], ["فاختلف الأحزاب", "في شأن عيسى، فقال اليهود: ساحر وابن زنا، وقال النصارى: هو الله وابن الله، تعالى الله عما يصفون."], ["من مشهد يوم عظيم", "هو يوم القيامة."], ["أسمع بهم وأبصر", "ما أسمعهم وما أبصرهم يوم القيامة عند معاينة العذاب."], ["وأنذرهم يوم الحسرة", "خوّفهم بما يقع يوم القيامة من الحسرة والندامة، حين يرث أهل الجنة منازلهم فيها، ويرثون هم منازل أهل الجنة في النار."]], "m": "بعد أن قصّ قصة مريم وكلام عيسى في المهد قال: ذلك الذي بيّنت لكم صفته هو عيسى ابن مريم، وما أخبرتكم به هو قول الحق الذي فيه يشكّون، إذ قال اليهود: ابن زنا وساحر، وقال النصارى: هو الله، وابن الله، وثالث ثلاثة. ما كان لله أن يتخذ من ولد، وكيف وهو الغني عما سواه، سبحانه، إذا قضى أمراً فإنما يقول له كن فيكون، فعيسى كان بكلمة الله له: كن. وقال عيسى لبني إسرائيل: وإن الله ربي وربكم فاعبدوه وحده بما شرع، هذا صراط مستقيم مفضٍ بسالكه إلى السعادة. فاختلف الأحزاب من بينهم في شأنه: فمن قائل هو الله، ومن قائل ابن الله، ومن قائل هو وأمه إلهان من دون الله، فويل للذين كفروا من مشهد يوم القيامة ذي الأهوال. ما أسمعهم وما أبصرهم يوم يأتوننا، وقد كانوا في الدنيا متعامين متصامّين عن الحجج، ولكن حين لا ينفعهم سمع ولا بصر، لكن الظالمون اليوم في ضلال مبين. وأنذرهم يوم الحسرة إذ قُضي الأمر: حين يرث الموحّدون منازل المشركين في الجنة، ويرث المشركون منازل الموحّدين في النار، وحين يؤتى بالموت في صورة كبش فيُذبح بين الجنة والنار، وينادي منادٍ: يا أهل الجنة خلود فلا موت، ويا أهل النار خلود فلا موت، وهم اليوم في غفلة وهم لا يؤمنون. إنا نحن نرث الأرض ومن عليها وإلينا يرجعون، فلا تحزن وامض في دعوتك.", "h": ["تقرير أن عيسى عبد الله ورسوله، وليس كما قال اليهود، ولا كما قالت النصارى.", "استحالة اتخاذ الله الولد، وهو الذي يقول للشيء كن فيكون.", "تقرير التوحيد على لسان عيسى ﵇.", "الإخبار بما عليه النصارى من خلاف في شأن عيسى ﵇.", "بيان سبب الحسرة يوم القيامة، وهو الكفر بالله والشرك به.", "تقرير فناء الدنيا ورجوع الناس إلى ربهم بعد بعثهم، وهو تقرير لعقيدة البعث والجزاء التي تعالجها السور المكية."], "k": "«وأنذرهم يوم الحسرة إذ قضي الأمر وهم في غفلة»… ما الغفلة التي أخشى أن أتحسّر عليها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (210, 19, 41, 50, 'سورة مريم ٤١ – ٥٠', '«واذكر في الكتاب إبراهيم إنه كان صدّيقاً نبيّاً»: دعوته الرحيمة لأبيه، و«سلام عليك سأستغفر لك ربي»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 210) = $j$[{"lbl": "الآيات ٤١ – ٤٥", "q": "وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيًّا ﴿٤١﴾ إِذۡ قَالَ لِأَبِيهِ يَـٰٓأَبَتِ لِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُبۡصِرُ وَلَا يُغۡنِي عَنكَ شَيۡـٔٗا ﴿٤٢﴾ يَـٰٓأَبَتِ إِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَٱتَّبِعۡنِيٓ أَهۡدِكَ صِرَٰطٗا سَوِيّٗا ﴿٤٣﴾ يَـٰٓأَبَتِ لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلرَّحۡمَٰنِ عَصِيّٗا ﴿٤٤﴾ يَـٰٓأَبَتِ إِنِّيٓ أَخَافُ أَن يَمَسَّكَ عَذَابٞ مِّنَ ٱلرَّحۡمَٰنِ فَتَكُونَ لِلشَّيۡطَٰنِ وَلِيّٗا ﴿٤٥﴾", "w": [["واذكر في الكتاب", "في القرآن."], ["إنه كان صدّيقاً", "كثير الصدق بالغ الحد الأعلى فيه."], ["يا أبتِ", "يا أبي، وهو آزر."], ["صراطاً سويّاً", "طريقاً مستقيماً لا اعوجاج فيه يفضي بك إلى الجنة."], ["لا تعبد الشيطان", "لا تطعه في دعوته إياك إلى عبادة الأصنام."], ["عصيّاً", "عاصياً لله تعالى فاسقاً عن أمره."], ["فتكون للشيطان وليّاً", "قريباً منه قريناً له في النار."]], "m": "هذه بداية قصة إبراهيم الخليل مع والده آزر: واذكر في القرآن إبراهيم، إنه كان صادقاً في أقواله وأعماله بالغاً في الصدق مستوى عظيماً، نبياً من أنبيائنا، فهو جدير بالذكر ليكون قدوة صالحة للمؤمنين، إذ قال لأبيه: يا أبت، لم تعبد بالدعاء والتقرّب ما لا يسمع دعاءك ولا يبصر عبادتك، ولا يدفع عنك ضراً ولا يجلب لك نفعاً؟ يا أبت إني قد جاءني من العلم من قبل ربي ما لم يأتك، فاتبعني أرشدك طريقاً مستقيماً يفضي بك إلى السعادة والنجاة. يا أبت لا تعبد الشيطان بطاعته فيما يدعوك إليه من عبادة هذه الأصنام، إن الشيطان كان للرحمن عاصياً فاسقاً عن أمره. يا أبت إني أخاف إن بقيت على شركك حتى متّ أن يمسّك عذاب من الرحمن، فتكون قريناً للشيطان في جهنم فتهلك وتخسر.", "h": ["تقرير التوحيد بالدعوة إليه.", "كمال إبراهيم بذكره في الكتاب.", "بطلان عبادة غير الله تعالى.", "عبادة الأوثان والأصنام، وكل عبادة لغير الله، تعتبر عبادة للشيطان، لأنه الآمر بها والداعي إليها."], "k": "«يا أبتِ… يا أبتِ… يا أبتِ»… دعا أباه المشرك بهذا اللطف؛ فكيف أحدّث أهلي حين أنصحهم؟"}, {"lbl": "الآيات ٤٦ – ٥٠", "q": "قَالَ أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِي يَـٰٓإِبۡرَٰهِيمُۖ لَئِن لَّمۡ تَنتَهِ لَأَرۡجُمَنَّكَۖ وَٱهۡجُرۡنِي مَلِيّٗا ﴿٤٦﴾ قَالَ سَلَٰمٌ عَلَيۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّيٓۖ إِنَّهُۥ كَانَ بِي حَفِيّٗا ﴿٤٧﴾ وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُواْ رَبِّي عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّي شَقِيّٗا ﴿٤٨﴾ فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۖ وَكُلّٗا جَعَلۡنَا نَبِيّٗا ﴿٤٩﴾ وَوَهَبۡنَا لَهُم مِّن رَّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِدۡقٍ عَلِيّٗا ﴿٥٠﴾", "w": [["أراغب أنت عن آلهتي", "أكاره لها تعيبها؟"], ["لئن لم تنته", "عن التعرض لها وعيبها."], ["لأرجمنّك", "بالحجارة أو بالقول القبيح، فاحذرني."], ["واهجرني مليّاً", "ابتعد عني ما دمت سليماً من عقوبتي."], ["سلام عليك", "أمان مني لك أن أعاودك فيما كرهت مني."], ["إنه كان بي حفيّاً", "لطيفاً بي مكرماً لي يجيبني لما أدعوه له."], ["عسى ألا أكون بدعاء ربي شقيّاً", "بل يجيب دعائي ويعطيني مسألتي."], ["فلما اعتزلهم", "بأن هاجر إلى أرض القدس وتركهم."], ["وهبنا له إسحاق ويعقوب", "وهبنا له ولدين يأنس بهما مجازاة منا له على هجرته قومه."], ["ووهبنا لهم من رحمتنا", "خيراً كثيراً: المال والولد بعد النبوة والعلم."], ["لسان صدق عليّاً", "رفيعاً، بأن يُثنى عليهم ويُذكرون بأطيب الخصال."]], "m": "بعد تلك الدعوة الرحيمة بالألفاظ الطيبة ردّ آزر بعبارات خالية من الرحمة ملؤها الغلظة والوعيد: أراغب أنت عن آلهتي يا إبراهيم تعيبها؟ لئن لم تنته عن التعرّض لها لأرجمنّك بأبشع الألفاظ، وابتعد عني ما دمت سليم البدن قبل أن ينالك مني ما تكره. فأجاب المؤمن الموحّد: سلام عليك، أمان لك مني يا أبتاه، فلا أعاودك فيما كرهت، وسأقابل إساءتك بإحسان، سأستغفر لك ربي، أطلب منه أن يهديك للإيمان فيغفر لك، إنه كان بي لطيفاً مكرماً لا يخيّبني فيما أدعوه. وأعتزلكم وما تدعون من دون الله من الأصنام، وأدعو ربي، رجائي ألا أشقى بعبادته كما شقيتم بعبادة الأصنام. فلما حقّق ما وعد من هجرته إلى ديار القدس تاركاً أباه وأهله وداره، كافأناه بأن وهبنا له إسحاق ويعقوب ابن إسحاق يأنس بهما في وحشته، وكلاً جعلناه نبياً، ووهبنا لهم من رحمتنا الخير العظيم من المال والولد والرزق الحسن، وجعلنا لهم لسان صدق رفيعاً، فسائر أهل الأديان الإلهية يثنون على إبراهيم وذريته بأطيب الثناء، جزاء صدقه وصبره وهجرته.", "h": ["بيان الفرق بين ما يخرج من فم المؤمن الموحّد من طيّب القول وسلامة اللفظ ولين الجانب، وبين ما يخرج من فم الكافر المشرك من سوء القول وقبح اللفظ وقسوة الجانب.", "مشروعية سلام المتاركة والموادعة، وهو أن يقال للمسيء من الناس: سلام عليك، وهو لا يريد بذلك تحيته، ولكن تركه وما هو فيه.", "مشروعية الهجرة وبيان فضلها، وهجرة إبراهيم هذه أول هجرة كانت في الأرض.", "الترغيب في حسن الأحدوثة، بأن يكون للمرء حسن ثناء بين الناس لما يقدّم من جميل وما يورّث من خير وإفضال."], "k": "«سلام عليك سأستغفر لك ربي»… هُدّد بالرجم فقابله بالسلام؛ فبماذا أقابل من يغلظ لي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 210;
insert into public.tdb_cards(topic, i, body) select 210, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٤٥", "q": "وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيًّا ﴿٤١﴾ إِذۡ قَالَ لِأَبِيهِ يَـٰٓأَبَتِ لِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُبۡصِرُ وَلَا يُغۡنِي عَنكَ شَيۡـٔٗا ﴿٤٢﴾ يَـٰٓأَبَتِ إِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَٱتَّبِعۡنِيٓ أَهۡدِكَ صِرَٰطٗا سَوِيّٗا ﴿٤٣﴾ يَـٰٓأَبَتِ لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلرَّحۡمَٰنِ عَصِيّٗا ﴿٤٤﴾ يَـٰٓأَبَتِ إِنِّيٓ أَخَافُ أَن يَمَسَّكَ عَذَابٞ مِّنَ ٱلرَّحۡمَٰنِ فَتَكُونَ لِلشَّيۡطَٰنِ وَلِيّٗا ﴿٤٥﴾", "w": [["واذكر في الكتاب", "في القرآن."], ["إنه كان صدّيقاً", "كثير الصدق بالغ الحد الأعلى فيه."], ["يا أبتِ", "يا أبي، وهو آزر."], ["صراطاً سويّاً", "طريقاً مستقيماً لا اعوجاج فيه يفضي بك إلى الجنة."], ["لا تعبد الشيطان", "لا تطعه في دعوته إياك إلى عبادة الأصنام."], ["عصيّاً", "عاصياً لله تعالى فاسقاً عن أمره."], ["فتكون للشيطان وليّاً", "قريباً منه قريناً له في النار."]], "m": "هذه بداية قصة إبراهيم الخليل مع والده آزر: واذكر في القرآن إبراهيم، إنه كان صادقاً في أقواله وأعماله بالغاً في الصدق مستوى عظيماً، نبياً من أنبيائنا، فهو جدير بالذكر ليكون قدوة صالحة للمؤمنين، إذ قال لأبيه: يا أبت، لم تعبد بالدعاء والتقرّب ما لا يسمع دعاءك ولا يبصر عبادتك، ولا يدفع عنك ضراً ولا يجلب لك نفعاً؟ يا أبت إني قد جاءني من العلم من قبل ربي ما لم يأتك، فاتبعني أرشدك طريقاً مستقيماً يفضي بك إلى السعادة والنجاة. يا أبت لا تعبد الشيطان بطاعته فيما يدعوك إليه من عبادة هذه الأصنام، إن الشيطان كان للرحمن عاصياً فاسقاً عن أمره. يا أبت إني أخاف إن بقيت على شركك حتى متّ أن يمسّك عذاب من الرحمن، فتكون قريناً للشيطان في جهنم فتهلك وتخسر.", "h": ["تقرير التوحيد بالدعوة إليه.", "كمال إبراهيم بذكره في الكتاب.", "بطلان عبادة غير الله تعالى.", "عبادة الأوثان والأصنام، وكل عبادة لغير الله، تعتبر عبادة للشيطان، لأنه الآمر بها والداعي إليها."], "k": "«يا أبتِ… يا أبتِ… يا أبتِ»… دعا أباه المشرك بهذا اللطف؛ فكيف أحدّث أهلي حين أنصحهم؟"}, {"lbl": "الآيات ٤٦ – ٥٠", "q": "قَالَ أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِي يَـٰٓإِبۡرَٰهِيمُۖ لَئِن لَّمۡ تَنتَهِ لَأَرۡجُمَنَّكَۖ وَٱهۡجُرۡنِي مَلِيّٗا ﴿٤٦﴾ قَالَ سَلَٰمٌ عَلَيۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّيٓۖ إِنَّهُۥ كَانَ بِي حَفِيّٗا ﴿٤٧﴾ وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُواْ رَبِّي عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّي شَقِيّٗا ﴿٤٨﴾ فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۖ وَكُلّٗا جَعَلۡنَا نَبِيّٗا ﴿٤٩﴾ وَوَهَبۡنَا لَهُم مِّن رَّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِدۡقٍ عَلِيّٗا ﴿٥٠﴾", "w": [["أراغب أنت عن آلهتي", "أكاره لها تعيبها؟"], ["لئن لم تنته", "عن التعرض لها وعيبها."], ["لأرجمنّك", "بالحجارة أو بالقول القبيح، فاحذرني."], ["واهجرني مليّاً", "ابتعد عني ما دمت سليماً من عقوبتي."], ["سلام عليك", "أمان مني لك أن أعاودك فيما كرهت مني."], ["إنه كان بي حفيّاً", "لطيفاً بي مكرماً لي يجيبني لما أدعوه له."], ["عسى ألا أكون بدعاء ربي شقيّاً", "بل يجيب دعائي ويعطيني مسألتي."], ["فلما اعتزلهم", "بأن هاجر إلى أرض القدس وتركهم."], ["وهبنا له إسحاق ويعقوب", "وهبنا له ولدين يأنس بهما مجازاة منا له على هجرته قومه."], ["ووهبنا لهم من رحمتنا", "خيراً كثيراً: المال والولد بعد النبوة والعلم."], ["لسان صدق عليّاً", "رفيعاً، بأن يُثنى عليهم ويُذكرون بأطيب الخصال."]], "m": "بعد تلك الدعوة الرحيمة بالألفاظ الطيبة ردّ آزر بعبارات خالية من الرحمة ملؤها الغلظة والوعيد: أراغب أنت عن آلهتي يا إبراهيم تعيبها؟ لئن لم تنته عن التعرّض لها لأرجمنّك بأبشع الألفاظ، وابتعد عني ما دمت سليم البدن قبل أن ينالك مني ما تكره. فأجاب المؤمن الموحّد: سلام عليك، أمان لك مني يا أبتاه، فلا أعاودك فيما كرهت، وسأقابل إساءتك بإحسان، سأستغفر لك ربي، أطلب منه أن يهديك للإيمان فيغفر لك، إنه كان بي لطيفاً مكرماً لا يخيّبني فيما أدعوه. وأعتزلكم وما تدعون من دون الله من الأصنام، وأدعو ربي، رجائي ألا أشقى بعبادته كما شقيتم بعبادة الأصنام. فلما حقّق ما وعد من هجرته إلى ديار القدس تاركاً أباه وأهله وداره، كافأناه بأن وهبنا له إسحاق ويعقوب ابن إسحاق يأنس بهما في وحشته، وكلاً جعلناه نبياً، ووهبنا لهم من رحمتنا الخير العظيم من المال والولد والرزق الحسن، وجعلنا لهم لسان ص