insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (211, 19, 51, 58, 'سورة مريم ٥١ – ٥٨', '«واذكر في الكتاب موسى… إسماعيل… إدريس»، و«إذا تتلى عليهم آيات الرحمن خرّوا سجّداً وبكيّاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 211) = $j$[{"lbl": "الآيات ٥١ – ٥٣", "q": "وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مُوسَىٰٓۚ إِنَّهُۥ كَانَ مُخۡلَصٗا وَكَانَ رَسُولٗا نَّبِيّٗا ﴿٥١﴾ وَنَٰدَيۡنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلۡأَيۡمَنِ وَقَرَّبۡنَٰهُ نَجِيّٗا ﴿٥٢﴾ وَوَهَبۡنَا لَهُۥ مِن رَّحۡمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيّٗا ﴿٥٣﴾", "w": [["واذكر في الكتاب", "في القرآن تشريفاً وتعظيماً."], ["موسى", "ابن عمران، نبي بني إسرائيل ﵇."], ["مخلَصاً", "مختاراً مصطفى على قراءة فتح اللام، وموحّداً لربه مفرداً إياه بعبادته على قراءة كسرها."], ["جانب الطور", "الطور: جبل بسيناء بين مدين ومصر."], ["وقرّبناه نجيّاً", "أدنيناه إدناء تشريف وتكريم مناجياً لنا مكلَّماً من قِبلنا."], ["أخاه هارون نبيّاً", "إذ سأل ربه لأخيه الرسالة فأعطاه، فنبّأه وأرسله معه إلى فرعون."]], "m": "هذا موجز قصة موسى: واذكر في هذه السلسلة الذهبية من عباد الله الصالحين أهل التوحيد موسى بن عمران، إنه كان مختاراً مصطفى للإبلاغ عنا عبادنا ما خلقناهم لأجله، وهو ذكرنا بألسنتهم وقلوبهم وشكرنا بجوارحهم، وكان رسولاً نبياً أرسلناه إلى فرعون وملئه. وناديناه وهو في طريقه من مدين إلى مصر من جانب الطور الأيمن فنبّأناه وأرسلناه، وقرّبناه نجياً، فصار يناجينا فنسمعه كلامنا ونسمع كلامه، وأعظم بهذا التكريم. ووهبنا له من رحمتنا أخاه هارون نبياً، إذ سأل ربه أن يرسل معه أخاه فاستجاب له، وما كان هذا إلا برحمة خاصة، إذ النبوة لا تُطلب ولا يُتوصّل إليها بالاجتهاد في العبادة ولا بالدعاء.", "h": ["فضيلة الإخلاص، وهو إرادة الله تعالى بالعبادة ظاهراً وباطناً.", "إثبات صفة الكلام والمناجاة لله تعالى.", "بيان إكرام الله تعالى وإنعامه على موسى، إذ أعطاه ما لم يعط أحداً من العالمين باستجابة دعائه بأن جعل أخاه هارون رسولاً نبياً.", "تقرير أن كل رسول نبي، والعكس لا، أي ليس كل نبي رسولاً."], "k": "«ووهبنا له من رحمتنا أخاه هارون نبيّاً»… دعا لأخيه بأعظم خير؛ فبماذا أدعو لإخوتي؟"}, {"lbl": "الآيات ٥٤ – ٥٨", "q": "وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا ﴿٥٤﴾ وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِيّٗا ﴿٥٥﴾ وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِدۡرِيسَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيّٗا ﴿٥٦﴾ وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا ﴿٥٧﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنۡ حَمَلۡنَا مَعَ نُوحٖ وَمِن ذُرِّيَّةِ إِبۡرَٰهِيمَ وَإِسۡرَـٰٓءِيلَ وَمِمَّنۡ هَدَيۡنَا وَٱجۡتَبَيۡنَآۚ إِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُ ٱلرَّحۡمَٰنِ خَرُّواْۤ سُجَّدٗاۤ وَبُكِيّٗا۩ ﴿٥٨﴾", "w": [["واذكر في الكتاب إسماعيل", "اذكر في القرآن تشريفاً وتعظيماً إسماعيل بن إبراهيم الخليل ﵉."], ["صادق الوعد", "لم يخلف وعداً قط."], ["بالصلاة والزكاة", "بإقامة الصلاة وإيتاء الزكاة."], ["مرضيّاً", "رضي الله تعالى قوله وعمله ليقينه وإخلاصه."], ["إدريس", "هو جد أبي نوح ﵇."], ["ورفعناه مكاناً عليّاً", "إلى السماء الرابعة."], ["إسرائيل", "يعقوب بن إسحاق بن إبراهيم ﵈."], ["وممن هدينا واجتبينا", "من جملة من هديناهم لطريقنا واجتبيناهم بنبوتنا."], ["إذا تتلى عليهم آيات الرحمن", "تُقرأ عليهم وهم يستمعون إليها."], ["سجّداً وبكيّاً", "جمع ساجد وباكٍ، أي ساجدين وهم يبكون."]], "m": "كما ذكرت مريم وابنها وإبراهيم وموسى، اذكر إسماعيل، إنه كان صادق الوعد لم يخلف وعداً قط، كان ينتظر الموعود الليالي وهو قائم في مكانه، وكان رسولاً نبياً، نبّأه الله بمكة وأرسله إلى قبيلة جرهم، ومنها تزوّج، ومن ذريته محمد ﷺ، وكان يأمر أهله وقومه بإقامة الصلاة وإيتاء الزكاة، وكان عند ربه مرضياً، أقواله وأفعاله مقبولة. واذكر في الكتاب إدريس، جد أبي نوح، إنه كان كثير الصدق لم يجر على لسانه كذب قط، نبياً، ورفعناه إلى السماء الرابعة في حياته. أولئك الذين أنعم الله عليهم من النبيين من ذرية آدم كإدريس، وممن حملنا مع نوح كإبراهيم، ومن ذرية إبراهيم كإسحاق وإسماعيل، ومن ذرية إسرائيل كموسى وهارون وداود وسليمان وزكريا ويحيى وعيسى، وممن هديناهم لطريقنا واجتبيناهم لوحينا، إذا تُتلى عليهم آيات الرحمن الحاملة للعظات والحجج خرّوا لربهم سجّداً، وبكيّاً مما يرون من تقصيرهم في جنب ربهم.", "h": ["تقرير النبوة، إذ الذي نبّأ هؤلاء وأرسلهم لا يُنكر عليه أن ينبّئ محمداً ﷺ ويرسله.", "فضيلة الأمر بالصلاة والزكاة.", "فضيلة الوفاء بالوعد والصدق في القول والعمل.", "سنيّة السجود لمن تلا هذه الآية، أو تُليت وهو يستمع إليها: «خرّوا سجّداً وبكيّاً».", "فضيلة البكاء حال السجود، فقد كان عمر إذا تلا هذه الآية سجد ثم يقول: هذا السجود، فأين البكيّ؟ يعني البكاء."], "k": "«وكان صادق الوعد»… وعد قطعته ولم أفِ به بعد؛ متى أفي به؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 211;
insert into public.tdb_cards(topic, i, body) select 211, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥١ – ٥٣", "q": "وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مُوسَىٰٓۚ إِنَّهُۥ كَانَ مُخۡلَصٗا وَكَانَ رَسُولٗا نَّبِيّٗا ﴿٥١﴾ وَنَٰدَيۡنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلۡأَيۡمَنِ وَقَرَّبۡنَٰهُ نَجِيّٗا ﴿٥٢﴾ وَوَهَبۡنَا لَهُۥ مِن رَّحۡمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيّٗا ﴿٥٣﴾", "w": [["واذكر في الكتاب", "في القرآن تشريفاً وتعظيماً."], ["موسى", "ابن عمران، نبي بني إسرائيل ﵇."], ["مخلَصاً", "مختاراً مصطفى على قراءة فتح اللام، وموحّداً لربه مفرداً إياه بعبادته على قراءة كسرها."], ["جانب الطور", "الطور: جبل بسيناء بين مدين ومصر."], ["وقرّبناه نجيّاً", "أدنيناه إدناء تشريف وتكريم مناجياً لنا مكلَّماً من قِبلنا."], ["أخاه هارون نبيّاً", "إذ سأل ربه لأخيه الرسالة فأعطاه، فنبّأه وأرسله معه إلى فرعون."]], "m": "هذا موجز قصة موسى: واذكر في هذه السلسلة الذهبية من عباد الله الصالحين أهل التوحيد موسى بن عمران، إنه كان مختاراً مصطفى للإبلاغ عنا عبادنا ما خلقناهم لأجله، وهو ذكرنا بألسنتهم وقلوبهم وشكرنا بجوارحهم، وكان رسولاً نبياً أرسلناه إلى فرعون وملئه. وناديناه وهو في طريقه من مدين إلى مصر من جانب الطور الأيمن فنبّأناه وأرسلناه، وقرّبناه نجياً، فصار يناجينا فنسمعه كلامنا ونسمع كلامه، وأعظم بهذا التكريم. ووهبنا له من رحمتنا أخاه هارون نبياً، إذ سأل ربه أن يرسل معه أخاه فاستجاب له، وما كان هذا إلا برحمة خاصة، إذ النبوة لا تُطلب ولا يُتوصّل إليها بالاجتهاد في العبادة ولا بالدعاء.", "h": ["فضيلة الإخلاص، وهو إرادة الله تعالى بالعبادة ظاهراً وباطناً.", "إثبات صفة الكلام والمناجاة لله تعالى.", "بيان إكرام الله تعالى وإنعامه على موسى، إذ أعطاه ما لم يعط أحداً من العالمين باستجابة دعائه بأن جعل أخاه هارون رسولاً نبياً.", "تقرير أن كل رسول نبي، والعكس لا، أي ليس كل نبي رسولاً."], "k": "«ووهبنا له من رحمتنا أخاه هارون نبيّاً»… دعا لأخيه بأعظم خير؛ فبماذا أدعو لإخوتي؟"}, {"lbl": "الآيات ٥٤ – ٥٨", "q": "وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا ﴿٥٤﴾ وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِيّٗا ﴿٥٥﴾ و