ا سجّداً وبكيّاً».", "فضيلة البكاء حال السجود، فقد كان عمر إذا تلا هذه الآية سجد ثم يقول: هذا السجود، فأين البكيّ؟ يعني البكاء."], "k": "«وكان صادق الوعد»… وعد قطعته ولم أفِ به بعد؛ متى أفي به؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (212, 19, 59, 65, 'سورة مريم ٥٩ – ٦٥', '«فخلف من بعدهم خلف أضاعوا الصلاة واتبعوا الشهوات»، و«وما نتنزّل إلا بأمر ربك»، و«فاعبده واصطبر لعبادته»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 212) = $j$[{"lbl": "الآيات ٥٩ – ٦٣", "q": "۞فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٌ أَضَاعُواْ ٱلصَّلَوٰةَ وَٱتَّبَعُواْ ٱلشَّهَوَٰتِۖ فَسَوۡفَ يَلۡقَوۡنَ غَيًّا ﴿٥٩﴾ إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ شَيۡـٔٗا ﴿٦٠﴾ جَنَّـٰتِ عَدۡنٍ ٱلَّتِي وَعَدَ ٱلرَّحۡمَٰنُ عِبَادَهُۥ بِٱلۡغَيۡبِۚ إِنَّهُۥ كَانَ وَعۡدُهُۥ مَأۡتِيّٗا ﴿٦١﴾ لَّا يَسۡمَعُونَ فِيهَا لَغۡوًا إِلَّا سَلَٰمٗاۖ وَلَهُمۡ رِزۡقُهُمۡ فِيهَا بُكۡرَةٗ وَعَشِيّٗا ﴿٦٢﴾ تِلۡكَ ٱلۡجَنَّةُ ٱلَّتِي نُورِثُ مِنۡ عِبَادِنَا مَن كَانَ تَقِيّٗا ﴿٦٣﴾", "w": [["خلف", "عقب سوء."], ["أضاعوا الصلاة", "أهملوها فتركوها فكانوا بذلك كافرين."], ["اتبعوا الشهوات", "انغمسوا في الذنوب والمعاصي كالزنا وشرب الخمر."], ["يلقون غيّاً", "وادياً في جهنم يُلقون فيه."], ["ولا يُظلمون شيئاً", "لا يُنقصون شيئاً من ثواب حسناتهم."], ["جنات عدن", "إقامة دائمة."], ["بالغيب", "وعدهم بها وهي غائبة عن أعينهم، إذ هي في السماء."], ["مأتيّاً", "موعوده، وهو ما يعد به عباده، آتياً لا محالة."], ["لغواً", "فضل الكلام، وهو ما لا فائدة فيه."], ["بكرة وعشيّاً", "بقدرهما في الدنيا، وإلا فالجنة ليس فيها شمس فيكون فيها ليل ونهار."], ["من كان تقيّاً", "من كان في الدنيا تقياً لم يترك الفرائض ولم يغش المحارم."]], "m": "يخبر تعالى أنه خلف من بعد أولئك الصالحين من النبيين وذرياتهم خلف سوء أضاعوا الصلاة، فمنهم من أخّرها عن أوقاتها ومنهم من تركها، واتبعوا الشهوات فانغمسوا في الرذائل، فشربوا الخمور وشهدوا الزور وأكلوا الحرام وزنوا، كما هو حال النصارى واليهود اليوم، وحتى كثير من المسلمين، فسوف يلقون غيّاً، وورد عن النبي ﷺ أنه بئر في جهنم، وعن ابن مسعود أنه وادٍ فيها، والكل صحيح إذ الآبار توجد في الأودية. إلا من تاب من هذا الخلف وحقّق إيمانه وعمل صالحاً فأدّى الفرائض وترك المحارم، فأولئك يدخلون الجنة مع سلفهم الصالح، ولا يُنقصون شيئاً من ثواب أعمالهم، جنات إقامة أبدية وعدها الرحمن عباده وهي غائبة عنهم، إن وعده آتٍ لا يتخلّف. لا يسمعون فيها باطلاً من القول إلا السلام يتلقّونه من الملائكة، ولهم فيها ما تشتهيه أنفسهم بقدر وقت الغداة والعشي في الدنيا، إذ لا ليل في الجنة ولا نهار. تلك الجنة التي نورث من عبادنا من كان تقياً، فما من إنسان إلا وله منزل في الجنة ومنزل في النار، فيورث الله الأتقياء منازل الفجار التي كانت لهم في الجنة.", "h": ["التنديد بخلف السوء، وهو من يضيّع الصلاة ويتبع الشهوات.", "الوعيد الشديد لمن ينغمس في الشهوات ويترك الصلاة فيموت على ذلك.", "باب التوبة مفتوح، والتوبة مقبولة من كل من أرادها وتاب.", "بيان نعيم الجنة دار المتقين الأبرار.", "تقرير مبدأ التوارث بين أهل الجنة وأهل النار.", "بيان أن ورثة الجنة هم الأتقياء، وأن ورثة النار هم الفجار."], "k": "«أضاعوا الصلاة واتبعوا الشهوات»… الصلاة التي أؤخّرها؛ ما الذي يسبقها في قلبي؟"}, {"lbl": "الآيتان ٦٤ – ٦٥", "q": "وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَۖ لَهُۥ مَا بَيۡنَ أَيۡدِينَا وَمَا خَلۡفَنَا وَمَا بَيۡنَ ذَٰلِكَۚ وَمَا كَانَ رَبُّكَ نَسِيّٗا ﴿٦٤﴾ رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا فَٱعۡبُدۡهُ وَٱصۡطَبِرۡ لِعِبَٰدَتِهِۦۚ هَلۡ تَعۡلَمُ لَهُۥ سَمِيّٗا ﴿٦٥﴾", "w": [["وما نتنزّل", "التنزّل: النزول وقتاً بعد وقت."], ["إلا بأمر ربك", "إلا بإذنه لنا في النزول على من يشاء."], ["له ما بين أيدينا", "مما هو مستقبل من أمر الآخرة."], ["وما خلفنا", "ما مضى من الدنيا."], ["وما بين ذلك", "ما لم يمض من الدنيا إلى يوم القيامة، أي له علم ذلك كله."], ["وما كان ربك نسيّاً", "ذا نسيان، فإنه تعالى لا ينسى، فكيف ينساك ويتركك؟"], ["رب السماوات والأرض", "مالكهما والمتصرّف فيهما."], ["واصطبر لعبادته", "اصبر وتحمّل الصبر في عبادته حتى الموت."], ["هل تعلم له سميّاً", "لا سميّ له ولا مثل ولا نظير."]], "m": "سبب نزولهما: أن الوحي تأخّر عن النبي ﷺ، فلما جاء جبريل ﵇ بعد بطء قال له: «ما يمنعك أن تزورنا أكثر مما تزورنا؟» فأنزل الله: وما نتنزّل، نحن الملائكة، وقتاً بعد وقت إلا بإذن ربك، فليس لأحد منا أن ينزل إلا بإذنه، له أمر وعلم ما أمامنا من أمور الآخرة، وما مضى من الدنيا، وما بين ذلك إلى يوم القيامة، وما كان ربك ناسياً لك ولا تاركاً، فإنه لم يكن النسيان وصفاً له. رب السماوات والأرض وما بينهما، مالكها والمتصرّف فيها، فكل شيء بيده وفي قبضته، فاعبده بما أمرك، واصطبر لعبادته وتحمّل فيها المشاق، هل تعلم له مثلاً أو نظيراً يستحق العبادة؟ لا، إذن فاعبده وحده، فإنه لا معبود بحق إلا هو، إذ كل ما عداه مربوب له خاضع لحكمه.", "h": ["تقرير سلطان الله على كل الخلق، وعلمه بكل الخلق، وقدرته على كل ذلك.", "استحالة النسيان على الله عز وجل.", "تقرير ربوبية الله تعالى للعالمين، وبذلك وجبت له الألوهية على سائر العالمين.", "وجوب عبادة الله تعالى، ووجوب الصبر عليها حتى الموت.", "نفي الشبيه والمثل والنظير لله، إذ هو الله أحد لم يكن له كفواً أحد."], "k": "«فاعبده واصطبر لعبادته»… أي عبادة أحتاج فيها إلى مصابرة؛ وكيف أثبت عليها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 212;
