insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (213, 19, 66, 76, 'سورة مريم ٦٦ – ٧٦', '«أئذا ما متّ لسوف أخرج حيّاً»، و«وإن منكم إلا واردها»، و«ويزيد الله الذين اهتدوا هدى»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 213) = $j$[{"lbl": "الآيات ٦٦ – ٧٢", "q": "وَيَقُولُ ٱلۡإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوۡفَ أُخۡرَجُ حَيًّا ﴿٦٦﴾ أَوَلَا يَذۡكُرُ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن قَبۡلُ وَلَمۡ يَكُ شَيۡـٔٗا ﴿٦٧﴾ فَوَرَبِّكَ لَنَحۡشُرَنَّهُمۡ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحۡضِرَنَّهُمۡ حَوۡلَ جَهَنَّمَ جِثِيّٗا ﴿٦٨﴾ ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَٰنِ عِتِيّٗا ﴿٦٩﴾ ثُمَّ لَنَحۡنُ أَعۡلَمُ بِٱلَّذِينَ هُمۡ أَوۡلَىٰ بِهَا صِلِيّٗا ﴿٧٠﴾ وَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ كَانَ عَلَىٰ رَبِّكَ حَتۡمٗا مَّقۡضِيّٗا ﴿٧١﴾ ثُمَّ نُنَجِّي ٱلَّذِينَ ٱتَّقَواْ وَّنَذَرُ ٱلظَّـٰلِمِينَ فِيهَا جِثِيّٗا ﴿٧٢﴾", "w": [["ويقول الإنسان", "الكافر بلقاء الله تعالى."], ["ولم يك شيئاً", "قبل خلقه، فلا ذات له ولا اسم ولا صفة."], ["جثيّاً", "جاثين على ركبهم في ذل وخوف وحزن."], ["من كل شيعة", "طائفة تعاونت على الباطل وتشيّع بعضها لبعض فيه."], ["عتيّاً", "تكبّراً عن عبادته وظلماً لعباده."], ["أولى بها صليّاً", "أحق بها اصطلاءً واحتراقاً وتعذيباً في النار."], ["إلا واردها", "ماراً بها، إن وقع فيها هلك، وإن مرّ ولم يقع نجا."], ["حتماً مقضيّاً", "أمراً قضى به الله تعالى وحتّمه فهو كائن لا بد."], ["فيها جثيّاً", "في النار جاثين على ركبهم."]], "m": "في تقرير البعث والجزاء يقول تعالى: ويقول الإنسان المنكر للآخرة، وقد يكون أبيّ بن خلف أو العاص بن وائل، وهي قولة كل من لا يؤمن بالآخرة: أئذا ما متّ لسوف أخرج حياً؟ استنكاراً وتكذيباً. أولا يذكر أنا خلقناه من قبل ولم يك شيئاً؟ أليس الذي قدر على خلقه من العدم قادراً على إعادته، والإعادة أهون؟ ثم أقسم تعالى: فوربك لنحشرنّهم جميعاً مع شياطينهم الذين أضلّوهم، ثم لنحضرنّهم حول جهنم جاثين على ركبهم أذلّاء، ثم لنأخذنّ من كل طائفة أشدّهم على الرحمن تمرّداً عن طاعته وتكبّراً عن الإيمان به، ثم لنحن أعلم بالذين هم أحق بالاصطلاء بالنار، فيدخلهم قبل غيرهم. وإن منكم إلا واردها، حكم قضى به: ما من أحد من بني آدم إلا وارد جهنم، وبيانه في الحديث: أن الصراط جسر يُمدّ على ظهر جهنم والناس يمرّون فوقه، فالمؤمنون يمرّون ولا يسقطون، والكافرون يسقطون فيها، ثم ننجّي الذين اتقوا ربهم فلم يشركوا ولم يعصوه، ونذر الظالمين بالكفر والكبائر فيها جاثين على ركبهم يعانون أشد العذاب.", "h": ["تقرير عقيدة البعث والجزاء بالحشر والإحضار حول جهنم والمرور على الصراط.", "تقرير معتقد الصراط في العبور عليه إلى الجنة.", "تقديم رؤساء الضلال وأئمة الكفر إلى جهنم قبل الأتباع الضالين.", "تقرير حتمية المرور على الصراط.", "بيان نجاة الأتقياء، وهلاك الفاجرين الظالمين بالشرك والمعاصي."], "k": "«وإن منكم إلا واردها»… سأمرّ على الصراط حتماً؛ فما الذي أعددته لأعبر؟"}, {"lbl": "الآيات ٧٣ – ٧٦", "q": "وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَيُّ ٱلۡفَرِيقَيۡنِ خَيۡرٞ مَّقَامٗا وَأَحۡسَنُ نَدِيّٗا ﴿٧٣﴾ وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَٰثٗا وَرِءۡيٗا ﴿٧٤﴾ قُلۡ مَن كَانَ فِي ٱلضَّلَٰلَةِ فَلۡيَمۡدُدۡ لَهُ ٱلرَّحۡمَٰنُ مَدًّاۚ حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ إِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعۡلَمُونَ مَنۡ هُوَ شَرّٞ مَّكَانٗا وَأَضۡعَفُ جُندٗا ﴿٧٥﴾ وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهۡتَدَوۡاْ هُدٗىۗ وَٱلۡبَٰقِيَٰتُ ٱلصَّـٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٞ مَّرَدًّا ﴿٧٦﴾", "w": [["آياتنا بيّنات", "آيات القرآن البيّنات الدلائل الواضحات الحجج."], ["خير مقاماً", "نحن أم أنتم؟ والمقام: المنزل ومحل الإقامة، والمراد هنا المنزلة."], ["وأحسن نديّاً", "نادياً، وهو مجتمع الكرام ومحل المشورة وتبادل الآراء."], ["أحسن أثاثاً ورئياً", "مالاً ومتاعاً ومنظراً."], ["إما العذاب وإما الساعة", "العذاب بالقتل والأسر، والساعة: القيامة المشتملة على نار جهنم."], ["من هو شر مكاناً", "منزلة."], ["وأضعف جنداً", "أقل أعواناً."], ["وخير مرداً", "ما يُردّ إليه ويُرجع، وهو نعيم الجنة."]], "m": "ما زال السياق في تقرير النبوة والتوحيد والبعث: وإذا قرأ الرسول ﷺ أو أحد أصحابه على كفار قريش آيات بيّنات في دلائلها، قال الذين كفروا للذين آمنوا: أي الفريقين خير منزلاً ومسكناً وأحسن مجتمعاً؟ وهو رد فعل لا غير، إذ لا يجدون ما يخفّفون به ألم نفوسهم من الوعيد، يقارنون بين منازل فقراء المؤمنين ودار الأرقم، وبين دور أبي سفيان وأغنياء مكة ونادي قريش. فردّ تعالى: وكم أهلكنا قبلهم من أهل قرون كانوا أحسن منهم مالاً ومتاعاً ومنظراً، فلا يغرّهم ما يتبجّحون به. قل: من كان في ضلالة الشرك والعناد فسنّة الرحمن أن يمهله ويملي له استدراجاً، حتى إذا رأوا ما يوعدون، إما العذاب بالقتل والأسر، وإما الساعة، فسيعلمون من هو شر منزلة وأقل ناصراً، ولكن حين لا ينفع العلم. ويزيد الله الذين اهتدوا هدى، فإذا كانت الآيات تزيد المشركين عناداً لظلمة كفرهم، فإن المؤمنين لإشراق نفوسهم بالإيمان يرون ما فيها من الحجج فيزداد إيمانهم. والباقيات الصالحات خير عند ربك ثواباً وخير مردّاً، تسلية للرسول والمؤمنين بأن ما يتبجّح به المشركون من المال والمتاع فانٍ، والصالحات باقية، مردّها الجنة دار السلام.", "h": ["الكشف عن نفسيات الكافرين، وهي الاعتزاز بالمال والقوة، إذا اعتزّ المؤمنون بالإيمان وثمراته في الدنيا والآخرة من حسن العاقبة.", "بيان سنة الله تعالى في إمهال الظلمة والإملاء لهم استدراجاً لهم حتى يهلكوا خاسرين.", "بيان سنة الله تعالى في زيادة إيمان المؤمنين عند سماع القرآن الكريم، أو مشاهدة أخذ الله تعالى للظالمين.", "بيان فضيلة الباقيات الصالحات، ومنها: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله."], "k": "«ويزيد الله الذين اهتدوا هدى»… هل زادتني الآيات التي قرأتها اليوم هدى؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 213;
insert into public.tdb_cards(topic, i, body) select 213, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٦ – ٧٢", "q": "وَيَقُولُ ٱلۡإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوۡفَ أُخۡرَجُ حَيًّا ﴿٦٦﴾ أَوَلَا يَذۡكُرُ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن قَبۡلُ وَلَمۡ يَكُ شَيۡـٔٗا ﴿٦٧﴾ فَوَرَبِّكَ لَنَحۡشُرَنَّهُمۡ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحۡضِرَنَّهُمۡ حَوۡلَ جَهَنَّمَ جِثِيّٗا ﴿٦٨﴾ ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَٰنِ عِتِيّٗا ﴿٦٩﴾ ثُمَّ لَنَحۡنُ أَعۡلَمُ بِٱلَّذِينَ هُمۡ أَوۡلَىٰ بِهَا صِلِيّٗا ﴿٧٠﴾ وَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ كَانَ عَلَىٰ رَبِّكَ حَتۡمٗا مَّقۡضِيّٗا ﴿٧١﴾ ثُمَّ نُنَجِّي ٱلَّذِينَ ٱتَّقَواْ وَّنَذَرُ ٱلظَّـٰلِمِينَ فِيهَا جِثِيّٗا ﴿٧٢﴾", "w": [["ويقول الإنسان", "الكافر بلقاء الله تعالى."], ["ولم يك شيئاً", "قبل خلقه، فلا ذات له ولا اسم ولا صفة."], ["جثيّاً", "جاثين على ركبهم في ذل وخوف وحزن."], ["من كل شيعة", "طائفة تعاونت على الباطل وتشيّع بعضها لبعض فيه."], ["عتيّاً", "تكبّراً عن عبادته وظلماً لعباده."], ["أولى بها صليّاً", "أحق بها اصطلاءً واحتراقاً وتعذيباً في النار."], ["إلا واردها", "ماراً بها، إن وقع فيها هلك، وإن مرّ ولم يقع نجا."], ["حتماً مقضيّاً", "أمراً قضى به الله تعالى وحتّمه فهو كائن لا بد."], ["فيها جثيّاً", "في النار جاثين على ركبهم."]], "m": "في تقرير البعث والجزاء يقول تعالى: ويقول الإنسان المنكر للآخرة، وقد يكون أبيّ بن خلف أو العاص بن وائل، وهي قولة كل من لا يؤمن بالآخرة: أئذا ما متّ لسوف أخرج حياً؟ استنكاراً وتكذيباً. أولا يذكر أنا خلقناه من قبل ولم يك شيئاً؟ أليس الذي قدر على خلقه من العدم قادراً على إعادته، والإعادة أهون؟ ثم أقسم تعالى: فوربك لنحشرنّهم جميعاً مع شياطينهم الذين أضلّوهم، ثم لنحضرنّهم حول جهنم جاثين على ركبهم أذلّاء، ثم لنأخذنّ من كل طائفة أشدّهم على الرحمن تمرّداً عن طاعته وتكبّراً عن الإيمان به، ثم لنحن أعلم بالذين هم أحق بالاصطلاء بالنار، فيدخلهم قبل غيرهم. وإن منكم إلا واردها، حكم قضى به: ما من أحد من بني آدم إلا وارد جهنم، وبيانه في الحديث: أن الصراط جسر يُمدّ على ظهر جهنم والناس يمرّون فوقه، فالمؤمنون يمرّون ولا يسقطون، والكافرون يسقطون فيها، ثم ننجّي الذين اتقوا ربهم فلم يشركوا ولم يعصوه، ونذر الظالمين بالكفر والكبائر فيها جاثين على ركبهم يعانون أشد العذاب.", "h": ["تقرير عقيدة البعث والجزاء بالحشر والإحضار حول جهنم والمرور على الصراط.", "تقرير معتقد الصراط في العبور عليه إلى الجنة.", "تقديم رؤساء الضلال وأئمة الكفر إلى جهنم قبل الأتباع الضالين.", "تقرير حتمية المرور على الصراط.", "بيان نجاة الأتقياء، وهلاك الفاجرين الظالمين بالشرك والمعاصي."], "k": "«وإن منكم إلا واردها»… سأمرّ على الصراط حتماً؛ فما الذي أعددته لأعبر؟"}, {"lbl": "الآيات ٧٣ – ٧٦", "q": "وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَيُّ ٱلۡفَرِيقَيۡنِ خَيۡرٞ مَّقَامٗا وَأَحۡسَنُ نَدِيّٗا ﴿٧٣﴾ وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَٰثٗا وَرِءۡيٗا ﴿٧٤﴾ قُلۡ مَن كَانَ فِي ٱلضَّلَٰلَةِ فَلۡيَمۡدُدۡ لَهُ ٱلرَّحۡمَٰنُ مَدًّاۚ حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ إِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعۡلَمُونَ مَنۡ هُوَ شَرّٞ مَّكَانٗا وَأَضۡعَفُ جُندٗا ﴿٧٥﴾ وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهۡتَدَوۡاْ هُدٗىۗ وَٱلۡبَٰقِيَٰتُ ٱلصَّـٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٞ مَّرَدًّا ﴿٧٦﴾", "w": [["آياتنا بيّنات", "آيات القرآن البيّنات الدلائل الواضحات الحجج."], ["خير مقاماً", "نحن أم أنتم؟ والمقام: المنزل ومحل الإقامة، والمراد هنا المنزلة."], ["وأحسن نديّاً", "نادياً، وهو مجتمع الكرام ومحل المشورة وتبادل الآراء."], ["أحسن أثاثاً ورئياً", "مالاً ومتاعاً ومنظراً."], ["إما العذاب وإما الساعة", "العذاب بالقتل والأسر، والساعة: القيامة المشتملة على نار جهنم."], ["من هو شر مكاناً", "منزلة."], ["وأضعف جنداً", "أقل أعواناً."], ["وخير مرداً", "ما يُردّ إليه ويُرجع، وهو نعيم الجنة."]], "m": "ما زال السياق في تقرير النبوة والتوحيد والبعث: وإذا قرأ الرسول ﷺ أو أحد أصحابه على كفار قريش آيات بيّنات في دلائلها، قال الذين كفروا للذين آمنوا: أي الفريقين خير منزلاً ومسكناً وأحسن مجتمعاً؟ وهو رد فعل لا غير، إذ لا يجدون ما يخفّفون به ألم نفوسهم من الوعيد، يقارنون بين منازل فقراء المؤمنين ودار الأرقم، وبين دور أبي سفيان وأغنياء مكة ونادي قريش. فردّ تعالى: وكم أهلكنا قبلهم من أهل قرون كانوا أحسن منهم مالاً ومتاعاً ومنظراً، فلا يغرّهم ما يتبجّحون به. قل: من كان في ضلالة الشرك والعناد فسنّة الرحمن أن يمهله ويملي له استدراجاً، حتى إذا رأوا ما يوعدون، إما العذاب بالقتل والأسر، وإما الساعة، فسيعلمون من هو شر منزلة وأقل ناصراً، ولكن حين لا ينفع العلم. ويزيد الله الذين اهتدوا هدى، فإذا كانت الآيات تزيد المشركين عناداً لظلمة كفرهم، فإن المؤمنين لإشراق نفوسهم بالإيمان يرون ما فيها من الحجج فيزداد إيمانهم. والباقيات الصالحات خير عند ربك ثواباً وخير مردّاً، تسلية للرسول والمؤمنين بأن ما يتبجّح به المشركون من المال والمتاع فانٍ، والصالحات باقية، مردّها الجنة دار السلام.", "h": ["الكشف عن نفسيات الكافرين، وهي الاعتزاز بالمال والقوة، إذا اعتزّ المؤمنون بالإيمان وثمراته في الدنيا والآخرة من حسن العاقبة.", "بيان سنة الله تعالى في إمهال الظلمة والإملاء لهم استدراجاً لهم حتى يهلكوا خاسرين.", "بيان سنة الله تعالى في زيادة إيمان المؤمنين عند سماع القرآن الكريم، أو مشاهدة أخذ الله تعالى للظالمين.", "بيان فضيلة الباقيات الصالحات، ومنها: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله."], "k": "«ويزيد الله الذين اهتدوا هدى»… هل زادتني الآيات التي قرأتها اليوم هدى؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (214, 19, 77, 87, 'سورة مريم ٧٧ – ٨٧', '«أفرأيت الذي كفر بآياتنا وقال لأوتينّ مالاً وولداً»، و«يوم نحشر المتقين إلى الرحمن وفداً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 214) = $j$[{"lbl": "الآيات ٧٧ – ٨٠", "q": "أَفَرَءَيۡتَ ٱلَّذِي كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالٗا وَوَلَدًا ﴿٧٧﴾ أَطَّلَعَ ٱلۡغَيۡبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا ﴿٧٨﴾ كَلَّاۚ سَنَكۡتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلۡعَذَابِ مَدّٗا ﴿٧٩﴾ وَنَرِثُهُۥ مَا يَقُولُ وَيَأۡتِينَا فَرۡدٗا ﴿٨٠﴾", "w": [["الذي كفر بآياتنا", "هو العاص بن وائل."], ["لأوتينّ مالاً وولداً", "يريد في الآخرة."], ["أطّلع الغيب", "فعرف أنه يُعطى مالاً وولداً يوم القيامة؟"], ["كلا", "ردع وردّ، فإنه لم يطّلع الغيب ولم يكن له عند الله عهد."], ["ونمدّ له من العذاب مدّاً", "نضاعف له العذاب يوم القيامة."], ["ونرثه ما يقول", "نسلبه ما تبجّح به من المال والولد، ويُبعث فرداً ليس معه مال ولا ولد."]], "m": "يقول تعالى لنبيه معجّباً له: أفرأيت الذي كذّب بالوحي وما يدعو إليه، وهو العاص بن وائل، وقال: لأوتينّ مالاً وولداً؟ قاله لخبّاب بن الأرت حين طالبه بدَين له عليه، فأبى أن يعطيه استصغاراً له لأنه كان حداداً، وقال: لا أعطيكه حتى تكفر بمحمد، فقال خباب: والله لا أكفر به حتى تموت ثم تُبعث، فقال العاص: إذا متّ ثم بُعثت كما تقول، ثم جئتني ولي مال وولد قضيتك دينك! فأكذبه الله: أطّلع الغيب فعرف أن له يوم القيامة مالاً وولداً، أم اتخذ عند الرحمن عهداً بذلك؟ كلا، لم يطّلع ولم يكن له عهد. سنكتب ما يقول من الكذب ونحاسبه به، ونضاعف له العذاب، ونسلبه ما يقول من المال والولد بموته أو بنصر رسوله على قومه، ويأتينا في عرصات القيامة فرداً لا مال معه ولا ولد.", "h": ["الكشف عن نفسيات الكافرين، لا سيما إذا كانوا أقوياء بمال أو ولد أو سلطان، فإنهم يعيشون على الغطرسة والاستعلاء وتجاهل الفقراء واحتقارهم.", "تقرير البعث والحساب والجزاء.", "مضاعفة العذاب على الكافرين الظالمين لظلمهم بعد كفرهم.", "تقرير معنى آية: «إنا نحن نرث الأرض ومن عليها وإلينا يرجعون»."], "k": "«ويأتينا فرداً»… سأقف بين يديه وحدي بلا مال ولا ولد؛ فماذا أحمل معي؟"}, {"lbl": "الآيات ٨١ – ٨٧", "q": "وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لِّيَكُونُواْ لَهُمۡ عِزّٗا ﴿٨١﴾ كَلَّاۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا ﴿٨٢﴾ أَلَمۡ تَرَ أَنَّآ أَرۡسَلۡنَا ٱلشَّيَٰطِينَ عَلَى ٱلۡكَٰفِرِينَ تَؤُزُّهُمۡ أَزّٗا ﴿٨٣﴾ فَلَا تَعۡجَلۡ عَلَيۡهِمۡۖ إِنَّمَا نَعُدُّ لَهُمۡ عَدّٗا ﴿٨٤﴾ يَوۡمَ نَحۡشُرُ ٱلۡمُتَّقِينَ إِلَى ٱلرَّحۡمَٰنِ وَفۡدٗا ﴿٨٥﴾ وَنَسُوقُ ٱلۡمُجۡرِمِينَ إِلَىٰ جَهَنَّمَ وِرۡدٗا ﴿٨٦﴾ لَّا يَمۡلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا ﴿٨٧﴾", "w": [["ليكونوا لهم عزّاً", "منعة لهم وقوة، يشفعون لهم عند الله حتى لا يعذَّبوا."], ["سيكفرون بعبادتهم", "يوم القيامة يجحدون أنهم كانوا يعبدونهم."], ["ضدّاً", "أعداء لهم وأعواناً عليهم."], ["تؤزّهم أزّاً", "تزعجهم إزعاجاً وتحرّكهم حراكاً شديداً نحو الشهوات."], ["وفداً", "راكبين على النجائب تحوطهم الملائكة حتى ينتهوا إلى الجنة."], ["إلى جهنم ورداً", "يُساق المجرمون كما تُساق البهائم مشاة عطاشاً."], ["عهداً", "هو شهادة أن لا إله إلا الله محمد رسول الله، ولا حول ولا قوة إلا بالله."]], "m": "يخبر تعالى مندّداً بالمشركين: واتخذوا من دون الله آلهة من الأصنام ليكونوا لهم في نظرهم الفاسد شفعاء يعزّون بهم، كلا، سيكفرون يوم القيامة بعبادتهم وينكرون أنهم أمروهم بها، ويكونون عليهم خصوماً. ألم ينته إلى علمك أنا أرسلنا شياطين الجن والإنس على الكافرين تحرّكهم بشدة نحو الشهوات والجرائم وتزعجهم إليها بالإغراء؟ فلا تعجب من مسارعتهم إلى الشر، ولا تعجل بمطالبتنا بهلاكهم، إنما نعدّ لهم أعمالهم حتى أنفاسهم، ونحاسبهم عليها. واذكر يوم نحشر المتقين، أهل الإيمان والطاعة والتوحيد ومحبة الله ورسوله، إلى جوار الرحمن وفداً راكبين على النجائب، ونسوق المجرمين بالشرك والمعاصي إلى جهنم مشاة عطاشاً كما تُساق البهائم. لا يملكون الشفاعة، لا يشفع بعضهم في بعض ولا يشفع لهم أحد، إلا من اتخذ عند الرحمن عهداً بالإيمان والطاعة، فهذا يملك إن شاء الله الشفاعة، وأهل لا إله إلا الله المتبرّئون من حولهم وقوتهم إلى الله، إن دخلوا النار بذنوبهم يخرجون منها بشفاعة من أراد الله أن يشفّعه فيهم.", "h": ["براءة سائر المعبودات من دون الله من عابديها يوم القيامة، خزياً لهم وإحقاقاً للعذاب عليهم.", "لا عجب مما يُشاهد من مسارعة الكافرين إلى الشر والفساد والشهوات، لوجود شياطين تحرّكهم بعنف إلى ذلك وتدفعهم إليه.", "لا ينبغي طلب العذاب العاجل لأهل الظلم، لأنهم كلما ازدادوا ظلماً ازداد عذابهم شدة يوم القيامة، إذ كل شيء محصيّ عليهم حتى أنفاسهم.", "بيان كرامة المتقين، ومهانة المجرمين."], "k": "«إلا من اتخذ عند الرحمن عهداً»… لا إله إلا الله، ولا حول ولا قوة إلا بالله؛ أجدّد بهما عهدي الآن."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 214;
insert into public.tdb_cards(topic, i, body) select 214, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٧ – ٨٠", "q": "أَفَرَءَيۡتَ ٱلَّذِي كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالٗا وَوَلَدًا ﴿٧٧﴾ أَطَّلَعَ ٱلۡغَيۡبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا ﴿٧٨﴾ كَلَّاۚ سَنَكۡتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلۡعَذَابِ مَدّٗا ﴿٧٩﴾ وَنَرِثُهُۥ مَا يَقُولُ وَيَأۡتِينَا فَرۡدٗا ﴿٨٠﴾", "w": [["الذي كفر بآياتنا", "هو العاص بن وائل."], ["لأوتينّ مالاً وولداً", "يريد في الآخرة."], ["أطّلع الغيب", "فعرف أنه يُعطى مالاً وولداً يوم القيامة؟"], ["كلا", "ردع وردّ، فإنه لم يطّلع الغيب ولم يكن له عند الله عهد."], ["ونمدّ له من العذاب مدّاً", "نضاعف له العذاب يوم القيامة."], ["ونرثه ما يقول", "نسلبه ما تبجّح به من المال والولد، ويُبعث فرداً ليس معه مال ولا ولد."]], "m": "يقول تعالى لنبيه معجّباً له: أفرأيت الذي كذّب بالوحي وما يدعو إليه، وهو العاص بن وائل، وقال: لأوتينّ مالاً وولداً؟ قاله لخبّاب بن الأرت حين طالبه بدَين له عليه، فأبى أن يعطيه استصغاراً له لأنه كان حداداً، وقال: لا أعطيكه حتى تكفر بمحمد، فقال خباب: والله لا أكفر به حتى تموت ثم تُبعث، فقال العاص: إذا متّ ثم بُعثت كما تقول، ثم جئتني ولي مال وولد قضيتك دينك! فأكذبه الله: أطّلع الغيب فعرف أن له يوم القيامة مالاً وولداً، أم اتخذ عند الرحمن عهداً بذلك؟ كلا، لم يطّلع ولم يكن له عهد. سنكتب ما يقول من الكذب ونحاسبه به، ونضاعف له العذاب، ونسلبه ما يقول من المال والولد بموته أو بنصر رسوله على قومه، ويأتينا في عرصات القيامة فرداً لا مال معه ولا ولد.", "h": ["الكشف عن نفسيات الكافرين، لا سيما إذا كانوا أقوياء بمال أو ولد أو سلطان، فإنهم يعيشون على الغطرسة والاستعلاء وتجاهل الفقراء واحتقارهم.", "تقرير البعث والحساب والجزاء.", "مضاعفة العذاب على الكافرين الظالمين لظلمهم بعد كفرهم.", "تقرير معنى آية: «إنا نحن نرث الأرض ومن عليها وإلينا يرجعون»."], "k": "«ويأتينا فرداً»… سأقف بين يديه وحدي بلا مال ولا ولد؛ فماذا أحمل معي؟"}, {"lbl": "الآيات ٨١ – ٨٧", "q": "وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لِّيَكُونُواْ لَهُمۡ عِزّٗا ﴿٨١﴾ كَلَّاۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا ﴿٨٢﴾ أَلَمۡ تَرَ أَنَّآ أَرۡسَلۡنَا ٱلشَّيَٰطِينَ عَلَى ٱلۡكَٰفِرِينَ تَؤُزُّهُمۡ أَزّٗا ﴿٨٣﴾ فَلَا تَعۡجَلۡ عَلَيۡهِمۡۖ إِنَّمَا نَعُدُّ لَهُمۡ عَدّٗا ﴿٨٤﴾ يَوۡمَ نَحۡشُرُ ٱلۡمُتَّقِينَ إِلَى ٱلرَّحۡمَٰنِ وَفۡدٗا ﴿٨٥﴾ وَنَسُوقُ ٱلۡمُجۡرِمِينَ إِلَىٰ جَهَنَّمَ وِرۡدٗا ﴿٨٦﴾ لَّا يَمۡلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا ﴿٨٧﴾", "w": [["ليكونوا لهم عزّاً", "منعة لهم وقوة، يشفعون لهم عند الله حتى لا يعذَّبوا."], ["سيكفرون بعبادتهم", "يوم القيامة يجحدون أنهم كانوا يعبدونهم."], ["ضدّاً", "أعداء لهم وأعواناً عليهم."], ["تؤزّهم أزّاً", "تزعجهم إزعاجاً وتحرّكهم حراكاً شديداً نحو الشهوات."], ["وفداً", "راكبين على النجائب تحوطهم الملائكة حتى ينتهوا إلى الجنة."], ["إلى جهنم ورداً", "يُساق المجرمون كما تُساق البهائم مشاة عطاشاً."], ["عهداً", "هو شهادة أن لا إله إلا الله محمد رسول الله، ولا حول ولا قوة إلا بالله."]], "m": "يخبر تعالى مندّداً بالمشركين: واتخذوا من دون الله آلهة من الأصنام ليكونوا لهم في نظرهم الفاسد شفعاء يعزّون بهم، كلا، سيكفرون يوم القيامة بعبادتهم وينكرون أنهم أمروهم بها، ويكونون عليهم خصوماً. ألم ينته إلى علمك أنا أرسلنا شياطين الجن والإنس على الكافرين تحرّكهم بشدة نحو الشهوات والجرائم وتزعجهم إليها بالإغراء؟ فلا تعجب من مسارعتهم إلى الشر، ولا تعجل بمطالبتنا بهلاكهم، إنما نعدّ لهم أعمالهم حتى أنفاسهم، ونحاسبهم عليها. واذكر يوم نحشر المتقين، أهل الإيمان والطاعة والتوحيد ومحبة الله ورسوله، إلى جوار الرحمن وفداً راكبين على النجائب، ونسوق المجرمين بالشرك والمعاصي إلى جهنم مشاة عطاشاً كما تُساق البهائم. لا يملكون الشفاعة، لا يشفع بعضهم في بعض ولا يشفع لهم أحد، إلا من اتخذ عند الرحمن عهداً بالإيمان والطاعة، فهذا يملك إن شاء الله الشفاعة، وأهل لا إله إلا الله المتبرّئون من حولهم وقوتهم إلى الله، إن دخلوا النار بذنوبهم يخرجون منها بشفاعة من أراد الله أن يشفّعه فيهم.", "h": ["براءة سائر المعبودات من دون الله من عابديها يوم القيامة، خزياً لهم وإحقاقاً للعذاب عليهم.", "لا عجب مما يُشاهد من مسارعة الكافرين إلى الشر والفساد والشهوات، لوجود شياطين تحرّكهم بعنف إلى ذلك وتدفعهم إليه.", "لا ينبغي طلب العذاب العاجل لأهل الظلم، لأنهم كلما ازدادوا ظلماً ازداد عذابهم شدة يوم القيامة، إذ كل شيء محصيّ عليهم حتى أنفاسهم.", "بيان كرامة المتقين، ومهانة المجرمين."], "k": "«إلا من اتخذ عند الرحمن عهداً»… لا إله إلا الله، ولا حول ولا قوة إلا بالله؛ أجدّد بهما عهدي الآن."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (215, 19, 88, 98, 'سورة مريم ٨٨ – ٩٨', '«تكاد السماوات يتفطّرن منه» لدعوى الولد للرحمن، و«سيجعل لهم الرحمن ودّاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 215) = $j$[{"lbl": "الآيات ٨٨ – ٩٥", "q": "وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗا ﴿٨٨﴾ لَّقَدۡ جِئۡتُمۡ شَيۡـًٔا إِدّٗا ﴿٨٩﴾ تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِنۡهُ وَتَنشَقُّ ٱلۡأَرۡضُ وَتَخِرُّ ٱلۡجِبَالُ هَدًّا ﴿٩٠﴾ أَن دَعَوۡاْ لِلرَّحۡمَٰنِ وَلَدٗا ﴿٩١﴾ وَمَا يَنۢبَغِي لِلرَّحۡمَٰنِ أَن يَتَّخِذَ وَلَدًا ﴿٩٢﴾ إِن كُلُّ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ إِلَّآ ءَاتِي ٱلرَّحۡمَٰنِ عَبۡدٗا ﴿٩٣﴾ لَّقَدۡ أَحۡصَىٰهُمۡ وَعَدَّهُمۡ عَدّٗا ﴿٩٤﴾ وَكُلُّهُمۡ ءَاتِيهِ يَوۡمَ ٱلۡقِيَٰمَةِ فَرۡدًا ﴿٩٥﴾", "w": [["وقالوا اتخذ الرحمن ولداً", "قال بعض العرب: الملائكة بنات الله، وقال النصارى: عيسى ابن الله."], ["جئتم شيئاً إدّاً", "منكراً عظيماً."], ["يتفطّرن", "يتشقّقن من عظم هذا القول وشدة قبحه."], ["وتخرّ الجبال هدّاً", "تسقط وتنهدم."], ["أن دعوا للرحمن ولداً", "من أجل ادّعائهم أن للرحمن عز وجل ولداً."], ["وما ينبغي", "لا يصلح ولا يليق به ذلك، لأنه رب كل شيء ومليكه."], ["إلا آتي الرحمن عبداً", "خاضعاً منقاداً كائناً من كان."], ["فرداً", "ليس معه شيء، لا مال ولا سلطان ولا ناصر."]], "m": "ما زال السياق في ذكر مقولات أهل الشرك والرد عليها: وقالوا اتخذ الرحمن ولداً، إذ قالت بعض القبائل العربية: الملائكة بنات الله، واليهود: عزير ابن الله، والنصارى: المسيح ابن الله. لقد جئتم شيئاً منكراً عظيماً، تكاد السماوات يتشقّقن لقبح هذا القول، وتنشقّ الأرض، وتسقط الجبال، لأنه مغضب للجبار عز وجل، ولولا حلمه ورحمته لمسّ الكون كله عذاب أليم، أن نسبوا للرحمن ولداً. وما ينبغي للرحمن ولا يليق بجلاله الولد، فالله منزّه عن مشابهة مخلوقاته، وكيف يشبههم وهو خالقهم من العدم؟ إن كل من في السماوات والأرض من ملائكة وإنس وجن إلا آتي الرحمن يوم القيامة عبداً خاضعاً منقاداً، فكيف يُعقل اتخاذه ولداً، والولد يُطلب للحاجة، والغني عن كل خلقه ما حاجته إلى ذلك؟ لقد علمهم واحداً واحداً وعدّهم عداً، فلو كان بينهم إله معه أو ولد له لعلمه، وكلهم آتيه يوم القيامة فرداً ليس معه شافع ولا ناصر ولا مال ولا سلطان.", "h": ["عظم الكذب على الله بنسبة الولد أو الشريك إليه، أو القول عليه بدون علم.", "بيان أن كل المخلوقات، من أجلّها إلى أحقرها، ليس فيها غير عبد لله.", "بيان إحاطة الله بخلقه ومعرفته لعددهم، فلا يغيب عن علمه أحد منهم، ولا يتخلّف عن موقف القيامة فرد منهم، إذ الكل يأتي الله تعالى يوم القيامة فرداً."], "k": "«إن كل من في السماوات والأرض إلا آتي الرحمن عبداً»… هل أعيش اليوم عبداً كما سآتيه عبداً؟"}, {"lbl": "الآيات ٩٦ – ٩٨", "q": "إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَيَجۡعَلُ لَهُمُ ٱلرَّحۡمَٰنُ وُدّٗا ﴿٩٦﴾ فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلۡمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوۡمٗا لُّدّٗا ﴿٩٧﴾ وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هَلۡ تُحِسُّ مِنۡهُم مِّنۡ أَحَدٍ أَوۡ تَسۡمَعُ لَهُمۡ رِكۡزَۢا ﴿٩٨﴾", "w": [["ودّاً", "حبّاً، فيعيشون متحابّين فيما بينهم ويحبهم ربهم تعالى."], ["فإنما يسّرناه بلسانك", "يسّرنا القرآن، قراءته وفهمه، بلغتك العربية."], ["قوماً لدّاً", "ألدّاء شديدي الخصومة والجدل بالباطل، وهم كفار قريش."], ["وكم أهلكنا", "كثيراً من أهل القرون من قبلهم أهلكناهم."], ["هل تحسّ منهم من أحد", "هل تجد منهم أحداً؟"], ["أو تسمع لهم ركزاً", "صوتاً خفياً؟ والجواب: لا، لأن الاستفهام إنكاري."]], "m": "يخبر تعالى أن الذين آمنوا بالله ورسوله ووعده ووعيده، فتخلّوا عن الشرك، وعملوا الصالحات من أداء الفرائض وكثير من النوافل، سيجعل لهم في قلوب عباده المؤمنين محبة وودّاً، وقد فعل سبحانه، فأهل الإيمان والعمل الصالح متحابّون متوادّون، وهذا التوادّ ثمرة لحب الله تعالى لهم. فإنما سهّلنا هذا القرآن الذي كذّب به المشركون بإنزاله بلسانك لتبشّر به المتقين الذين اتقوا عذاب الله بالإيمان وصالح الأعمال، وتنذر به قوماً شديدي الجدل والخصومة، وهم كفار قريش. وكثيراً من أهل القرون السابقة أهلكناهم لما كذّبوا رسلنا، فهل تجد منهم أحداً تراه بعينك أو تسمع لهم صوتاً خفياً؟ لا، فهلّا يذكر هذا قومك فيتّعظوا ويتوبوا.", "h": ["أعظم بشرى تحملها الآية الأولى، وهي حب الله وأوليائه لمن آمن وعمل صالحاً.", "بيان كون القرآن ميسّراً، إذ نزل بلغة النبي ﷺ، من أجل البشارة لأهل الإيمان والعمل الصالح، والنذارة لأهل الشرك والمعاصي.", "إنذار العتاة والطغاة من الناس أن يحلّ بهم ما حلّ بمن قبلهم من هلاك ودمار، والواقع شاهد: أين أهل القرون الأولى؟"], "k": "«سيجعل لهم الرحمن ودّاً»… المحبة بين المؤمنين ثمرة الإيمان والعمل؛ فهل أزرع ما يثمرها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 215;
insert into public.tdb_cards(topic, i, body) select 215, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٨ – ٩٥", "q": "وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗا ﴿٨٨﴾ لَّقَدۡ جِئۡتُمۡ شَيۡـًٔا إِدّٗا ﴿٨٩﴾ تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِنۡهُ وَتَنشَقُّ ٱلۡأَرۡضُ وَتَخِرُّ ٱلۡجِبَالُ هَدًّا ﴿٩٠﴾ أَن دَعَوۡاْ لِلرَّحۡمَٰنِ وَلَدٗا ﴿٩١﴾ وَمَا يَنۢبَغِي لِلرَّحۡمَٰنِ أَن يَتَّخِذَ وَلَدًا ﴿٩٢﴾ إِن كُلُّ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ إِلَّآ ءَاتِي ٱلرَّحۡمَٰنِ عَبۡدٗا ﴿٩٣﴾ لَّقَدۡ أَحۡصَىٰهُمۡ وَعَدَّهُمۡ عَدّٗا ﴿٩٤﴾ وَكُلُّهُمۡ ءَاتِيهِ يَوۡمَ ٱلۡقِيَٰمَةِ فَرۡدًا ﴿٩٥﴾", "w": [["وقالوا اتخذ الرحمن ولداً", "قال بعض العرب: الملائكة بنات الله، وقال النصارى: عيسى ابن الله."], ["جئتم شيئاً إدّاً", "منكراً عظيماً."], ["يتفطّرن", "يتشقّقن من عظم هذا القول وشدة قبحه."], ["وتخرّ الجبال هدّاً", "تسقط وتنهدم."], ["أن دعوا للرحمن ولداً", "من أجل ادّعائهم أن للرحمن عز وجل ولداً."], ["وما ينبغي", "لا يصلح ولا يليق به ذلك، لأنه رب كل شيء ومليكه."], ["إلا آتي الرحمن عبداً", "خاضعاً منقاداً كائناً من كان."], ["فرداً", "ليس معه شيء، لا مال ولا سلطان ولا ناصر."]], "m": "ما زال السياق في ذكر مقولات أهل الشرك والرد عليها: وقالوا اتخذ الرحمن ولداً، إذ قالت بعض القبائل العربية: الملائكة بنات الله، واليهود: عزير ابن الله، والنصارى: المسيح ابن الله. لقد جئتم شيئاً منكراً عظيماً، تكاد السماوات يتشقّقن لقبح هذا القول، وتنشقّ الأرض، وتسقط الجبال، لأنه مغضب للجبار عز وجل، ولولا حلمه ورحمته لمسّ الكون كله عذاب أليم، أن نسبوا للرحمن ولداً. وما ينبغي للرحمن ولا يليق بجلاله الولد، فالله منزّه عن مشابهة مخلوقاته، وكيف يشبههم وهو خالقهم من العدم؟ إن كل من في السماوات والأرض من ملائكة وإنس وجن إلا آتي الرحمن يوم القيامة عبداً خاضعاً منقاداً، فكيف يُعقل اتخاذه ولداً، والولد يُطلب للحاجة، والغني عن كل خلقه ما حاجته إلى ذلك؟ لقد علمهم واحداً واحداً وعدّهم عداً، فلو كان بينهم إله معه أو ولد له لعلمه، وكلهم آتيه يوم القيامة فرداً ليس معه شافع ولا ناصر ولا مال ولا سلطان.", "h": ["عظم الكذب على الله بنسبة الولد أو الشريك إليه، أو القول عليه بدون علم.", "بيان أن كل المخلوقات، من أجلّها إلى أحقرها، ليس فيها غير عبد لله.", "بيان إحاطة الله بخلقه ومعرفته لعددهم، فلا يغيب عن علمه أحد منهم، ولا يتخلّف عن موقف القيامة فرد منهم، إذ الكل يأتي الله تعالى يوم القيامة فرداً."], "k": "«إن كل من في السماوات والأرض إلا آتي الرحمن عبداً»… هل أعيش اليوم عبداً كما سآتيه عبداً؟"}, {"lbl": "الآيات ٩٦ – ٩٨", "q": "إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَيَجۡعَلُ لَهُمُ ٱلرَّحۡمَٰنُ وُدّٗا ﴿٩٦﴾ فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلۡمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوۡمٗا لُّدّٗا ﴿٩٧﴾ وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هَلۡ تُحِسُّ مِنۡهُم مِّنۡ أَحَدٍ أَوۡ تَسۡمَعُ لَهُمۡ رِكۡزَۢا ﴿٩٨﴾", "w": [["ودّاً", "حبّاً، فيعيشون متحابّين فيما بينهم ويحبهم ربهم تعالى."], ["فإنما يسّرناه بلسانك", "يسّرنا القرآن، قراءته وفهمه، بلغتك العربية."], ["قوماً لدّاً", "ألدّاء شديدي الخصومة والجدل بالباطل، وهم كفار قريش."], ["وكم أهلكنا", "كثيراً من أهل القرون من قبلهم أهلكناهم."], ["هل تحسّ منهم من أحد", "هل تجد منهم أحداً؟"], ["أو تسمع لهم ركزاً", "صوتاً خفياً؟ والجواب: لا، لأن الاستفهام إنكاري."]], "m": "يخبر تعالى أن الذين آمنوا بالله ورسوله ووعده ووعيده، فتخلّوا عن الشرك، وعملوا الصالحات من أداء الفرائض وكثير من النوافل، سيجعل لهم في قلوب عباده المؤمنين محبة وودّاً، وقد فعل سبحانه، فأهل الإيمان والعمل الصالح متحابّون متوادّون، وهذا التوادّ ثمرة لحب الله تعالى لهم. فإنما سهّلنا هذا القرآن الذي كذّب به المشركون بإنزاله بلسانك لتبشّر به المتقين الذين اتقوا عذاب الله بالإيمان وصالح الأعمال، وتنذر به قوماً شديدي الجدل والخصومة، وهم كفار قريش. وكثيراً من أهل القرون السابقة أهلكناهم لما كذّبوا رسلنا، فهل تجد منهم أحداً تراه بعينك أو تسمع لهم صوتاً خفياً؟ لا، فهلّا يذكر هذا قومك فيتّعظوا ويتوبوا.", "h": ["أعظم بشرى تحملها الآية الأولى، وهي حب الله وأوليائه لمن آمن وعمل صالحاً.", "بيان كون القرآن ميسّراً، إذ نزل بلغة النبي ﷺ، من أجل البشارة لأهل الإيمان والعمل الصالح، والنذارة لأهل الشرك والمعاصي.", "إنذار العتاة والطغاة من الناس أن يحلّ بهم ما حلّ بمن قبلهم من هلاك ودمار، والواقع شاهد: أين أهل القرون الأولى؟"], "k": "«سيجعل لهم الرحمن ودّاً»… المحبة بين المؤمنين ثمرة الإيمان والعمل؛ فهل أزرع ما يثمرها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (216, 20, 1, 16, 'سورة طه ١ – ١٦', '«ما أنزلنا عليك القرآن لتشقى»، و«وهل أتاك حديث موسى»: النداء بالوادي المقدس، و«وأقم الصلاة لذكري»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 216) = $j$[{"lbl": "الآيات ١ – ٨", "q": "طه ﴿١﴾ مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ ﴿٢﴾ إِلَّا تَذۡكِرَةٗ لِّمَن يَخۡشَىٰ ﴿٣﴾ تَنزِيلٗا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَٰوَٰتِ ٱلۡعُلَى ﴿٤﴾ ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ ﴿٥﴾ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ ﴿٦﴾ وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى ﴿٧﴾ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ ﴿٨﴾", "w": [["طه", "يا رجل."], ["لتشقى", "لتتعب بما فيه من التكاليف."], ["إلا تذكرة", "ليتذكّر بالقرآن من يخشى عقاب الله عز وجل."], ["على العرش استوى", "ارتفع عليه وعلا."], ["وما تحت الثرى", "الثرى: التراب الندي، يريد ما هو أسفل الأرضين السبع."], ["وأخفى", "من السر، وهو ما علمه الله وقدّر وجوده وهو كائن، ولم يعلمه الإنسان بعد."], ["الحسنى", "مؤنث الأحسن."]], "m": "طه: جائز أن تكون من الحروف المقطّعة، وجائز أن يكون معناها: يا رجل، ورجّحه ابن جرير لوجوده في لغة العرب، فمعنى الكلام: يا رجل، ما أنزلنا عليك القرآن لتشقى، رداً على النضر بن الحارث الذي قال: إن محمداً شقي بهذا القرآن لما فيه من التكاليف، وإنما أنزلناه تذكرة لمن يخشى ربه فيثبت على طاعته متحمّلاً ما يلقى من أذى المشركين. نُزّل تنزيلاً من الله الذي خلق الأرض والسماوات العلى، الرحمن الذي استوى على عرشه استواءً يليق به يدبّر أمر مخلوقاته، له ما في السماوات وما في الأرض وما بينهما وما تحت الثرى من الأرضين السبع. وإن تجهر بالقول أو تسرّ فإنه يعلم السر وأخفى منه، وهو ما قدّره وهو واقع في وقته ولم يعلمه الإنسان بعد. الله المعبود بحق الذي لا معبود بحق سواه، له الأسماء الحسنى التي لا تكون لغيره، وهكذا عرّف تعالى عباده به ليعرفوه فيخافوه ويحبّوه فيؤمنوا به ويطيعوه.", "h": ["إبطال نظرية أن التكاليف الشرعية شاقة ومرهقة للعبد.", "تقرير عقيدة الوحي وإثبات النبوة المحمدية.", "تقرير الصفات الإلهية كالاستواء، ووجوب الإيمان بها بدون تأويل أو تعطيل أو تشبيه، بل إثباتها على الوجه الذي يليق بصاحبها عز وجل.", "تقرير ربوبية الله لكل شيء.", "تقرير التوحيد، وإثبات أسماء الله تعالى الحسنى وصفاته العلى."], "k": "«ما أنزلنا عليك القرآن لتشقى»… هل أرى في التكاليف عبئاً أم تذكرة ورحمة؟"}, {"lbl": "الآيات ٩ – ١٦", "q": "وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ ﴿٩﴾ إِذۡ رَءَا نَارٗا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدٗى ﴿١٠﴾ فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ ﴿١١﴾ إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى ﴿١٢﴾ وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ ﴿١٣﴾ إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ ﴿١٤﴾ إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخۡفِيهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ ﴿١٥﴾ فَلَا يَصُدَّنَّكَ عَنۡهَا مَن لَّا يُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ ﴿١٦﴾", "w": [["هل أتاك", "قد أتاك، فالاستفهام للتحقيق."], ["حديث موسى", "خبره، وموسى هو ابن عمران نبي بني إسرائيل."], ["إذ رأى ناراً", "حين رؤيته ناراً."], ["لأهله", "زوجته بنت شعيب ومن معها."], ["آنست ناراً", "أبصرتها من بعد."], ["بقبس", "القبس: عود في رأسه نار."], ["على النار هدى", "ما يهديني الطريق، وقد ضلّ الطريق إلى مصر."], ["فلما أتاها", "النار، وكانت في شجرة تتلألأ نوراً لا ناراً."], ["المقدّس طوى", "طوى: اسم للوادي المقدّس المطهّر."], ["اخترتك", "من قومك لحمل رسالتي إلى فرعون وبني إسرائيل."], ["لذكري", "لأجل أن تذكرني فيها."], ["أكاد أخفيها", "أبالغ في إخفائها حتى لا يعلم وقت مجيئها أحد."], ["بما تسعى", "سعيها في الخير أو في الشر."], ["فتردى", "تهلك."]], "m": "ما زال السياق في تقرير التوحيد، يقرّره هنا بالإخبار عن موسى، وأن أول ما أوحاه إليه أنه لا إله إلا هو: وقد أتاك حديث موسى، إذ رأى ناراً في ليلة مظلمة شاتية، وزنده لم يقدح له ناراً، وقد ضلّوا طريقهم، فقال لأهله: امكثوا هنا، إني أبصرت ناراً، لعلي آتيكم منها بقبس توقدون به ناراً تستدفئون بها، أو أجد حولها من يهدينا الطريق. فلما أتاها، وكانت شجرة تتلألأ نوراً، ناداه ربه: يا موسى، إني أنا ربك خالقك ومدبّر أمرك، فاخلع نعليك إنك بالوادي المقدّس طوى، ليتبرّك بملامسته بقدميه. وأنا اخترتك لحمل رسالتي، فاستمع لما يوحى إليك: إنني أنا الله لا إله إلا أنا فاعبدني وحدي، وأقم الصلاة لأجل أن تذكرني فيها، فمن لم يصلّ لم يذكر الله. إن الساعة التي يقوم فيها الناس للحساب آتية لا محالة، أكاد أخفيها حتى عن نفسي، لحكمة أن يعمل الناس وهم لا يدرون متى يموتون ولا متى يُبعثون، فتكون أعمالهم بإراداتهم، لتجزى كل نفس بما تسعى. فلا يصدّنك عن الإيمان بها والتزوّد لها من لا يؤمن بها واتبع هواه فتهلك.", "h": ["تقرير النبوة لمحمد ﷺ.", "تقرير التوحيد وإثباته، وأن الدعوة إلى لا إله إلا الله دعوة كافة الرسل.", "إثبات صفة الكلام لله تعالى.", "مشروعية التبرّك بما جعله الله تعالى مباركاً، والتبرّك التماس البركة حسب بيان الرسول ﷺ.", "وجوب إقام الصلاة، وبيان علّة ذلك، وهو ذكر الله تعالى.", "بيان الحكمة في إخفاء الساعة، مع وجوب إتيانها وحتميته."], "k": "«وأقم الصلاة لذكري»… في صلاتي القادمة، هل يكون قلبي ذاكراً لا لساني وحده؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 216;
insert into public.tdb_cards(topic, i, body) select 216, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٨", "q": "طه ﴿١﴾ مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ ﴿٢﴾ إِلَّا تَذۡكِرَةٗ لِّمَن يَخۡشَىٰ ﴿٣﴾ تَنزِيلٗا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَٰوَٰتِ ٱلۡعُلَى ﴿٤﴾ ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ ﴿٥﴾ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ ﴿٦﴾ وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى ﴿٧﴾ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ ﴿٨﴾", "w": [["طه", "يا رجل."], ["لتشقى", "لتتعب بما فيه من التكاليف."], ["إلا تذكرة", "ليتذكّر بالقرآن من يخشى عقاب الله عز وجل."], ["على العرش استوى", "ارتفع عليه وعلا."], ["وما تحت الثرى", "الثرى: التراب الندي، يريد ما هو أسفل الأرضين السبع."], ["وأخفى", "من السر، وهو ما علمه الله وقدّر وجوده وهو كائن، ولم يعلمه الإنسان بعد."], ["الحسنى", "مؤنث الأحسن."]], "m": "طه: جائز أن تكون من الحروف المقطّعة، وجائز أن يكون معناها: يا رجل، ورجّحه ابن جرير لوجوده في لغة العرب، فمعنى الكلام: يا رجل، ما أنزلنا عليك القرآن لتشقى، رداً على النضر بن الحارث الذي قال: إن محمداً شقي بهذا القرآن لما فيه من التكاليف، وإنما أنزلناه تذكرة لمن يخشى ربه فيثبت على طاعته متحمّلاً ما يلقى من أذى المشركين. نُزّل تنزيلاً من الله الذي خلق الأرض والسماوات العلى، الرحمن الذي استوى على عرشه استواءً يليق به يدبّر أمر مخلوقاته، له ما في السماوات وما في الأرض وما بينهما وما تحت الثرى من الأرضين السبع. وإن تجهر بالقول أو تسرّ فإنه يعلم السر وأخفى منه، وهو ما قدّره وهو واقع في وقته ولم يعلمه الإنسان بعد. الله المعبود بحق الذي لا معبود بحق سواه، له الأسماء الحسنى التي لا تكون لغيره، وهكذا عرّف تعالى عباده به ليعرفوه فيخافوه ويحبّوه فيؤمنوا به ويطيعوه.", "h": ["إبطال نظرية أن التكاليف الشرعية شاقة ومرهقة للعبد.", "تقرير عقيدة الوحي وإثبات النبوة المحمدية.", "تقرير الصفات الإلهية كالاستواء، ووجوب الإيمان بها بدون تأويل أو تعطيل أو تشبيه، بل إثباتها على الوجه الذي يليق بصاحبها عز وجل.", "تقرير ربوبية الله لكل شيء.", "تقرير التوحيد، وإثبات أسماء الله تعالى الحسنى وصفاته العلى."], "k": "«ما أنزلنا عليك القرآن لتشقى»… هل أرى في التكاليف عبئاً أم تذكرة ورحمة؟"}, {"lbl": "الآيات ٩ – ١٦", "q": "وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ ﴿٩﴾ إِذۡ رَءَا نَارٗا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدٗى ﴿١٠﴾ فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ ﴿١١﴾ إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى ﴿١٢﴾ وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ ﴿١٣﴾ إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ ﴿١٤﴾ إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخۡفِيهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ ﴿١٥﴾ فَلَا يَصُدَّنَّكَ عَنۡهَا مَن لَّا يُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ ﴿١٦﴾", "w": [["هل أتاك", "قد أتاك، فالاستفهام للتحقيق."], ["حديث موسى", "خبره، وموسى هو ابن عمران نبي بني إسرائيل."], ["إذ رأى ناراً", "حين رؤيته ناراً."], ["لأهله", "زوجته بنت شعيب ومن معها."], ["آنست ناراً", "أبصرتها من بعد."], ["بقبس", "القبس: عود في رأسه نار."], ["على النار هدى", "ما يهديني الطريق، وقد ضلّ الطريق إلى مصر."], ["فلما أتاها", "النار، وكانت في شجرة تتلألأ نوراً لا ناراً."], ["المقدّس طوى", "طوى: اسم للوادي المقدّس المطهّر."], ["اخترتك", "من قومك لحمل رسالتي إلى فرعون وبني إسرائيل."], ["لذكري", "لأجل أن تذكرني فيها."], ["أكاد أخفيها", "أبالغ في إخفائها حتى لا يعلم وقت مجيئها أحد."], ["بما تسعى", "سعيها في الخير أو في الشر."], ["فتردى", "تهلك."]], "m": "ما زال السياق في تقرير التوحيد، يقرّره هنا بالإخبار عن موسى، وأن أول ما أوحاه إليه أنه لا إله إلا هو: وقد أتاك حديث موسى، إذ رأى ناراً في ليلة مظلمة شاتية، وزنده لم يقدح له ناراً، وقد ضلّوا طريقهم، فقال لأهله: امكثوا هنا، إني أبصرت ناراً، لعلي آتيكم منها بقبس توقدون به ناراً تستدفئون بها، أو أجد حولها من يهدينا الطريق. فلما أتاها، وكانت شجرة تتلألأ نوراً، ناداه ربه: يا موسى، إني أنا ربك خالقك ومدبّر أمرك، فاخلع نعليك إنك بالوادي المقدّس طوى، ليتبرّك بملامسته بقدميه. وأنا اخترتك لحمل رسالتي، فاستمع لما يوحى إليك: إنني أنا الله لا إله إلا أنا فاعبدني وحدي، وأقم الصلاة لأجل أن تذكرني فيها، فمن لم يصلّ لم يذكر الله. إن الساعة التي يقوم فيها الناس للحساب آتية لا محالة، أكاد أخفيها حتى عن نفسي، لحكمة أن يعمل الناس وهم لا يدرون متى يموتون ولا متى يُبعثون، فتكون أعمالهم بإراداتهم، لتجزى كل نفس بما تسعى. فلا يصدّنك عن الإيمان بها والتزوّد لها من لا يؤمن بها واتبع هواه فتهلك.", "h": ["تقرير النبوة لمحمد ﷺ.", "تقرير التوحيد وإثباته، وأن الدعوة إلى لا إله إلا الله دعوة كافة الرسل.", "إثبات صفة الكلام لله تعالى.", "مشروعية التبرّك بما جعله الله تعالى مباركاً، والتبرّك التماس البركة حسب بيان الرسول ﷺ.", "وجوب إقام الصلاة، وبيان علّة ذلك، وهو ذكر الله تعالى.", "بيان الحكمة في إخفاء الساعة، مع وجوب إتيانها وحتميته."], "k": "«وأقم الصلاة لذكري»… في صلاتي القادمة، هل يكون قلبي ذاكراً لا لساني وحده؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (217, 20, 17, 35, 'سورة طه ١٧ – ٣٥', 'آيتا العصا واليد، و«اذهب إلى فرعون إنه طغى»، و«رب اشرح لي صدري ويسّر لي أمري»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 217) = $j$[{"lbl": "الآيات ١٧ – ٢٤", "q": "وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ ﴿١٧﴾ قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ ﴿١٨﴾ قَالَ أَلۡقِهَا يَٰمُوسَىٰ ﴿١٩﴾ فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ ﴿٢٠﴾ قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ ﴿٢١﴾ وَٱضۡمُمۡ يَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٍ ءَايَةً أُخۡرَىٰ ﴿٢٢﴾ لِنُرِيَكَ مِنۡ ءَايَٰتِنَا ٱلۡكُبۡرَى ﴿٢٣﴾ ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ﴿٢٤﴾", "w": [["وما تلك بيمينك يا موسى", "الاستفهام للتقرير، ليرتّب عليه المعجزة، وهي انقلابها حيّة."], ["أتوكّأ عليها", "أعتمد عليها."], ["وأهشّ بها على غنمي", "أخبط بها ورق الشجر فيتساقط فتأكله الغنم."], ["ولي فيها مآرب أخرى", "حاجات أخرى كحمل الزاد بتعليقه فيها، وقتل الهوام."], ["حيّة تسعى", "ثعبان عظيم يمشي على بطنه بسرعة كالثعبان الصغير المسمى بالجان."], ["سيرتها الأولى", "حالتها الأولى قبل أن تنقلب حيّة."], ["إلى جناحك", "إلى جنبك الأيسر تحت العضد إلى الإبط."], ["بيضاء من غير سوء", "من غير برص، تضيء كشعاع الشمس."], ["اذهب إلى فرعون", "رسولاً إليه."], ["إنه طغى", "تجاوز الحد في الكفر حتى ادّعى الألوهية."]], "m": "ما زال السياق مع موسى وربه: سأله ربه وهو أعلم: وما تلك بيمينك يا موسى؟ ليقرّر أنها عصا من خشب يابس، فإذا تحوّلت حيّة علم أنها آية. قال: هي عصاي أعتمد عليها، وأخبط بها الشجر فيتساقط الورق فتأكله غنمي، ولي فيها حاجات أخرى كحمل الزاد والماء على عاتقه كعادة الرعاة، وقتل الهوام. قال: ألقها يا موسى، فألقاها فإذا هي ثعبان عظيم يسعى، فخاف وولّى هارباً، فقال ربه: خذها ولا تخف، سنعيدها عصا كما كانت، فأخذها فإذا هي عصاه. واضمم يدك اليمنى إلى جنبك الأيسر تخرج بيضاء من غير برص، فضمّها تحت عضده ثم أخرجها فإذا هي تتلألأ كأنها فلقة قمر، آية أخرى دالة على رسالتك، لنريك من دلائل قدرتنا الكبرى. ثم أمره: اذهب إلى فرعون رسولاً يأمره بعبادة الله وحده، وأن يرسل معه بني إسرائيل، إنه تجاوز حدّه كبشر حتى قال: أنا ربكم الأعلى، فأيّ طغيان أكبر من هذا؟", "h": ["تقرير نبوة الرسول محمد ﷺ، إذ مثل هذه الأخبار لا تصح إلا ممن يوحى إليه.", "استحباب تناول الأشياء غير المستقذرة باليمين.", "مشروعية حمل العصا.", "سنة رعي الغنم للأنبياء.", "مشروعية التدريب على السلاح قبل استعماله في المعارك.", "آية موسى في انقلاب العصا حيّة، وخروج اليد بيضاء كأنها الثلج أو شعاع الشمس.", "بيان الطغيان، وهو ادّعاء العبد ما ليس له كالألوهية ونحوها."], "k": "«وما تلك بيمينك يا موسى»… عصا عادية صارت آية؛ فما الذي في يدي أستعمله في طاعته؟"}, {"lbl": "الآيات ٢٥ – ٣٥", "q": "قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي ﴿٢٥﴾ وَيَسِّرۡ لِيٓ أَمۡرِي ﴿٢٦﴾ وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي ﴿٢٧﴾ يَفۡقَهُواْ قَوۡلِي ﴿٢٨﴾ وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي ﴿٢٩﴾ هَٰرُونَ أَخِي ﴿٣٠﴾ ٱشۡدُدۡ بِهِۦٓ أَزۡرِي ﴿٣١﴾ وَأَشۡرِكۡهُ فِيٓ أَمۡرِي ﴿٣٢﴾ كَيۡ نُسَبِّحَكَ كَثِيرٗا ﴿٣٣﴾ وَنَذۡكُرَكَ كَثِيرًا ﴿٣٤﴾ إِنَّكَ كُنتَ بِنَا بَصِيرٗا ﴿٣٥﴾", "w": [["اشرح لي صدري", "وسّعه لي لأتحمّل الرسالة."], ["ويسّر لي أمري", "سهّله حتى أقوى على القيام به."], ["واحلل عقدة من لساني", "حبسة، حتى أُفهم من أخاطب."], ["وزيراً", "معيناً على تبليغ الرسالة وتحمّل أعبائها."], ["اشدد به أزري", "قوّ به ظهري."], ["وأشركه في أمري", "اجعله نبياً كما نبّأتني."]], "m": "بعد أن أمره الله بالذهاب إلى فرعون، قال موسى: رب اشرح لي صدري لأتحمّل أعباء الرسالة، ويسّر لي أمري، سهّل مهمّتي وارزقني العون عليها فإنها صعبة شاقة، واحلل عقدة من لساني، تلك العقدة التي نشأت من الجمرة التي ألقاها في فمه صغيراً، إذ أخذ بلحية فرعون فهمّ بقتله، فقالت آسية: إنه لا يعقل لصغره، واختبره بجواهر في طبق وجمر في طست، فمدّ يده بتدبير الله إلى الجمر فكانت سبب العقدة، فسأل ربه أن يحلّها ليفصح إذا خاطب فرعون فيُفهم قوله. واجعل لي معيناً من أهلي، هارون أخي، قوّ به ظهري، وأشركه في أمري بتنبئته وإرساله، كي نسبّحك كثيراً ونذكرك كثيراً، إنك كنت بنا بصيراً لا يخفى عليك شيء من أمرنا، وهذا توسّل منه إلى الله بعلمه تعالى به وبأخيه.", "h": ["وجوب اللجوء إلى الله تعالى في كل ما يهمّ العبد.", "مشروعية الأخذ بالأهبة والاستعداد لما يعتزم العبد القيام به.", "فضيلة التسبيح والذكر، والتوسّل بأسماء الله وصفاته."], "k": "«رب اشرح لي صدري ويسّر لي أمري»… أمر صعب أمامي؛ أقدّم بين يديه هذا الدعاء."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 217;
insert into public.tdb_cards(topic, i, body) select 217, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٧ – ٢٤", "q": "وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ ﴿١٧﴾ قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ ﴿١٨﴾ قَالَ أَلۡقِهَا يَٰمُوسَىٰ ﴿١٩﴾ فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ ﴿٢٠﴾ قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ ﴿٢١﴾ وَٱضۡمُمۡ يَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٍ ءَايَةً أُخۡرَىٰ ﴿٢٢﴾ لِنُرِيَكَ مِنۡ ءَايَٰتِنَا ٱلۡكُبۡرَى ﴿٢٣﴾ ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ﴿٢٤﴾", "w": [["وما تلك بيمينك يا موسى", "الاستفهام للتقرير، ليرتّب عليه المعجزة، وهي انقلابها حيّة."], ["أتوكّأ عليها", "أعتمد عليها."], ["وأهشّ بها على غنمي", "أخبط بها ورق الشجر فيتساقط فتأكله الغنم."], ["ولي فيها مآرب أخرى", "حاجات أخرى كحمل الزاد بتعليقه فيها، وقتل الهوام."], ["حيّة تسعى", "ثعبان عظيم يمشي على بطنه بسرعة كالثعبان الصغير المسمى بالجان."], ["سيرتها الأولى", "حالتها الأولى قبل أن تنقلب حيّة."], ["إلى جناحك", "إلى جنبك الأيسر تحت العضد إلى الإبط."], ["بيضاء من غير سوء", "من غير برص، تضيء كشعاع الشمس."], ["اذهب إلى فرعون", "رسولاً إليه."], ["إنه طغى", "تجاوز الحد في الكفر حتى ادّعى الألوهية."]], "m": "ما زال السياق مع موسى وربه: سأله ربه وهو أعلم: وما تلك بيمينك يا موسى؟ ليقرّر أنها عصا من خشب يابس، فإذا تحوّلت حيّة علم أنها آية. قال: هي عصاي أعتمد عليها، وأخبط بها الشجر فيتساقط الورق فتأكله غنمي، ولي فيها حاجات أخرى كحمل الزاد والماء على عاتقه كعادة الرعاة، وقتل الهوام. قال: ألقها يا موسى، فألقاها فإذا هي ثعبان عظيم يسعى، فخاف وولّى هارباً، فقال ربه: خذها ولا تخف، سنعيدها عصا كما كانت، فأخذها فإذا هي عصاه. واضمم يدك اليمنى إلى جنبك الأيسر تخرج بيضاء من غير برص، فضمّها تحت عضده ثم أخرجها فإذا هي تتلألأ كأنها فلقة قمر، آية أخرى دالة على رسالتك، لنريك من دلائل قدرتنا الكبرى. ثم أمره: اذهب إلى فرعون رسولاً يأمره بعبادة الله وحده، وأن يرسل معه بني إسرائيل، إنه تجاوز حدّه كبشر حتى قال: أنا ربكم الأعلى، فأيّ طغيان أكبر من هذا؟", "h": ["تقرير نبوة الرسول محمد ﷺ، إذ مثل هذه الأخبار لا تصح إلا ممن يوحى إليه.", "استحباب تناول الأشياء غير المستقذرة باليمين.", "مشروعية حمل العصا.", "سنة رعي الغنم للأنبياء.", "مشروعية التدريب على السلاح قبل استعماله في المعارك.", "آية موسى في انقلاب العصا حيّة، وخروج اليد بيضاء كأنها الثلج أو شعاع الشمس.", "بيان الطغيان، وهو ادّعاء العبد ما ليس له كالألوهية ونحوها."], "k": "«وما تلك بيمينك يا موسى»… عصا عادية صارت آية؛ فما الذي في يدي أستعمله في طاعته؟"}, {"lbl": "الآيات ٢٥ – ٣٥", "q": "قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي ﴿٢٥﴾ وَيَسِّرۡ لِيٓ أَمۡرِي ﴿٢٦﴾ وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي ﴿٢٧﴾ يَفۡقَهُواْ قَوۡلِي ﴿٢٨﴾ وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي ﴿٢٩﴾ هَٰرُونَ أَخِي ﴿٣٠﴾ ٱشۡدُدۡ بِهِۦٓ أَزۡرِي ﴿٣١﴾ وَأَشۡرِكۡهُ فِيٓ أَمۡرِي ﴿٣٢﴾ كَيۡ نُسَبِّحَكَ كَثِيرٗا ﴿٣٣﴾ وَنَذۡكُرَكَ كَثِيرًا ﴿٣٤﴾ إِنَّكَ كُنتَ بِنَا بَصِيرٗا ﴿٣٥﴾", "w": [["اشرح لي صدري", "وسّعه لي لأتحمّل الرسالة."], ["ويسّر لي أمري", "سهّله حتى أقوى على القيام به."], ["واحلل عقدة من لساني", "حبسة، حتى أُفهم من أخاطب."], ["وزيراً", "معيناً على تبليغ الرسالة وتحمّل أعبائها."], ["اشدد به أزري", "قوّ به ظهري."], ["وأشركه في أمري", "اجعله نبياً كما نبّأتني."]], "m": "بعد أن أمره الله بالذهاب إلى فرعون، قال موسى: رب اشرح لي صدري لأتحمّل أعباء الرسالة، ويسّر لي أمري، سهّل مهمّتي وارزقني العون عليها فإنها صعبة شاقة، واحلل عقدة من لساني، تلك العقدة التي نشأت من الجمرة التي ألقاها في فمه صغيراً، إذ أخذ بلحية فرعون فهمّ بقتله، فقالت آسية: إنه لا يعقل لصغره، واختبره بجواهر في طبق وجمر في طست، فمدّ يده بتدبير الله إلى الجمر فكانت سبب العقدة، فسأل ربه أن يحلّها ليفصح إذا خاطب فرعون فيُفهم قوله. واجعل لي معيناً من أهلي، هارون أخي، قوّ به ظهري، وأشركه في أمري بتنبئته وإرساله، كي نسبّحك كثيراً ونذكرك كثيراً، إنك كنت بنا بصيراً لا يخفى عليك شيء من أمرنا، وهذا توسّل منه إلى الله بعلمه تعالى به وبأخيه.", "h": ["وجوب اللجوء إلى الله تعالى في كل ما يهمّ العبد.", "مشروعية الأخذ بالأهبة والاستعداد لما يعتزم العبد القيام به.", "فضيلة التسبيح والذكر، والتوسّل بأسماء الله وصفاته."], "k": "«رب اشرح لي صدري ويسّر لي أمري»… أمر صعب أمامي؛ أقدّم بين يديه هذا الدعاء."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (218, 20, 36, 48, 'سورة طه ٣٦ – ٤٨', '«ولقد مننّا عليك مرة أخرى… وألقيت عليك محبة مني»، و«فقولا له قولاً ليّناً لعله يتذكّر أو يخشى»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 218) = $j$[{"lbl": "الآيات ٣٦ – ٤١", "q": "قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ ﴿٣٦﴾ وَلَقَدۡ مَنَنَّا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ ﴿٣٧﴾ إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ ﴿٣٨﴾ أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوّٞ لِّي وَعَدُوّٞ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ ﴿٣٩﴾ إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّـٰكَ فُتُونٗاۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ ﴿٤٠﴾ وَٱصۡطَنَعۡتُكَ لِنَفۡسِي ﴿٤١﴾", "w": [["قد أوتيت سؤلك", "مسئولك من انشراح صدرك وتيسير أمرك وانحلال عقدة لسانك وتنبئة أخيك."], ["ولقد مننّا عليك مرة أخرى", "أنعمنا عليك مرة أخرى قبل هذه."], ["ما يوحى", "في شأنك، وهو قوله: أن اقذفيه في التابوت."], ["في التابوت", "الصندوق."], ["فاقذفيه في اليم", "في بحر النيل."], ["ولتُصنع على عيني", "تُربّى بمرأى مني ومحبة وإرادة."], ["نفساً", "هو القبطي الذي قتلته بمصر."], ["فنجّيناك من الغم", "إذ استغفرتنا فغفرنا لك، وائتمروا بك ليقتلوك فنجّيناك منهم."], ["وفتنّاك فتوناً", "اختبرناك اختباراً وابتليناك ابتلاءً عظيماً."], ["جئت على قدر", "جئت للوقت الذي أردنا إرسالك فيه إلى فرعون."], ["واصطنعتك لنفسي", "أنعمت عليك بتلك النعم اجتباءً منا لك لتحمل رسالتنا."]], "m": "أجاب الله موسى: قد أُعطيت ما طلبت يا موسى، ولقد أنعمنا عليك مرة أخرى قبل هذه: لما أمر فرعون بذبح أبناء بني إسرائيل، أوحينا إلى أمك أن اقذفيه في الصندوق، فاقذفيه في النيل، فليلقه اليم بالساحل يأخذه عدو لي وعدو له، فهذه النجاة نعمة. وألقيت عليك محبة مني فأصبح من يراك يحبّك، ولتُربّى على مرأى مني، إذ تمشي أختك فتقول: هل أدلّكم على من يكفله؟ فرجعناك إلى أمك كي تقرّ عينها ولا تحزن. وأعظم من ذلك أنك قتلت نفساً فنجّيناك من الغم بعد ائتمار آل فرعون على قتلك، وغفرنا لك. وابتليناك ابتلاءً عظيماً: حمل أمك بك في سنة القتل، وإلقاؤها بك في اليم، وتحريم المراضع عليك، وأخذك بلحية فرعون، وقتلك القبطي، وغربتك في مدين، وضلالك الطريق بأهلك. فلبثت سنين في أهل مدين ترعى غنم شعيب عشراً، ثم جئت من مدين إلى طور سيناء على موعد قدّرناه لك وما كنت تعلمه، واصطنعتك لنفسي: خلقتك وربّيتك وابتليتك لأحمّلك عبء الرسالة إلى فرعون وبني إسرائيل.", "h": ["مظاهر لطف الله تعالى وحسن تدبيره في خلقه.", "مظاهر إكرام الله تعالى ولطفه بعبده ورسوله موسى ﵇.", "آية حب الله تعالى لموسى، وأثر ذلك في حب الناس له.", "تقرير نبوة محمد ﷺ بإخباره في كتابه بمثل هذه الأحداث في قصص موسى ﵇."], "k": "«وفتنّاك فتوناً»… كل محنة مرّ بها كانت إعداداً؛ فكيف أنظر إلى محنتي الحالية؟"}, {"lbl": "الآيات ٤٢ – ٤٨", "q": "ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي ﴿٤٢﴾ ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ﴿٤٣﴾ فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ ﴿٤٤﴾ قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ ﴿٤٥﴾ قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ ﴿٤٦﴾ فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَـٰٓءِيلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةٖ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰٓ ﴿٤٧﴾ إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ ﴿٤٨﴾", "w": [["بآياتي", "بالمعجزات التي آتيتك كالعصا واليد وغيرها."], ["ولا تنيا في ذكري", "لا تفترا ولا تقصّرا في ذكري، فإنه سر الحياة وعونكما على أداء الرسالة."], ["إنه طغى", "تجاوز قدره بادّعائه الألوهية والربوبية."], ["قولاً ليّناً", "خالياً من الغلظة والعنف."], ["لعله يتذكّر", "فيما تقولان فيهتدي إلى معرفتنا فيخشانا فيؤمن، ويرسل معكما بني إسرائيل."], ["يفرط علينا", "يعجل بعقوبتنا قبل أن ندعوه ونبيّن له."], ["أو أن يطغى", "يزداد طغياناً وظلماً."], ["أسمع وأرى", "أسمع ما تقولانه وما يقال لكما، وأرى ما تعملان وما يُعمل بكما."], ["فأرسل معنا بني إسرائيل", "لنذهب بهم إلى أرض المعاد، أرض أبيهم إبراهيم."], ["بآية", "معجزة تدل على صدقنا وأنا رسولا ربك حقاً."], ["والسلام على من اتبع الهدى", "النجاة من العذاب في الدارين لمن آمن واتقى."], ["من كذّب وتولّى", "كذّب بالحق وأعرض عنه فلم يقبله."]], "m": "أمره بالذهاب مع أخيه هارون مزوّدين بالعصا واليد، ونهاهما عن التقصير في ذكره، فقال: اذهب أنت وأخوك بآياتي ولا تفترا في ذكري، اذهبا إلى فرعون إنه تجاوز حدّه من عبد إلى مدّعٍ للربوبية، وعلّمهما أسلوب الدعوة: فقولا له قولاً ليّناً خالياً من الغلظة والجفاء، رجاء أن يتذكّر فيراجع نفسه فيؤمن، أو يخشى العذاب فيرسل معكما بني إسرائيل. قالا: إننا نخاف أن يعجل بعقوبتنا بالضرب أو القتل، أو أن يزداد طغياناً. قال: لا تخافا، إنني معكما بنصري وتأييدي، أسمع ما تقولان وما يقول لكما، وأرى ما تعملان وما يعمل، فأحقّ عملكما وأبطل عمله. فأتياه فقولا: إنا رسولا ربك، فأرسل معنا بني إسرائيل ولا تعذّبهم بقتل رجالهم واستحياء نسائهم، قد جئناك بحجة من ربك، والأمان لمن اتبع الهدى، فاتبعه تسلم، إنا قد أوحي إلينا أن العذاب على من كذّب بالحق وأعرض عنه كبرياءً وعناداً.", "h": ["عظم شأن الذكر بالقلب واللسان والجوارح، أي بالطاعة فعلاً وتركاً.", "وجوب مراعاة الحكمة في دعوة الناس إلى ربهم.", "تقرير معيّة الله تعالى مع أوليائه وصالحي عباده بنصرهم وتأييدهم.", "تقرير أن السلامة من عذاب الدنيا والآخرة هي من نصيب متّبعي الهدى.", "شرعية إتيان الظالم وأمره ونهيه والصبر على أذاه.", "عدم المؤاخذة على الخوف حيث وُجدت أسبابه."], "k": "«فقولا له قولاً ليّناً»… أُمرا باللين مع فرعون؛ فكيف ألين مع من أختلف معه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 218;
insert into public.tdb_cards(topic, i, body) select 218, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٦ – ٤١", "q": "قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ ﴿٣٦﴾ وَلَقَدۡ مَنَنَّا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ ﴿٣٧﴾ إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ ﴿٣٨﴾ أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوّٞ لِّي وَعَدُوّٞ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ ﴿٣٩﴾ إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّـٰكَ فُتُونٗاۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ ﴿٤٠﴾ وَٱصۡطَنَعۡتُكَ لِنَفۡسِي ﴿٤١﴾", "w": [["قد أوتيت سؤلك", "مسئولك من انشراح صدرك وتيسير أمرك وانحلال عقدة لسانك وتنبئة أخيك."], ["ولقد مننّا عليك مرة أخرى", "أنعمنا عليك مرة أخرى قبل هذه."], ["ما يوحى", "في شأنك، وهو قوله: أن اقذفيه في التابوت."], ["في التابوت", "الصندوق."], ["فاقذفيه في اليم", "في بحر النيل."], ["ولتُصنع على عيني", "تُربّى بمرأى مني ومحبة وإرادة."], ["نفساً", "هو القبطي الذي قتلته بمصر."], ["فنجّيناك من الغم", "إذ استغفرتنا فغفرنا لك، وائتمروا بك ليقتلوك فنجّيناك منهم."], ["وفتنّاك فتوناً", "اختبرناك اختباراً وابتليناك ابتلاءً عظيماً."], ["جئت على قدر", "جئت للوقت الذي أردنا إرسالك فيه إلى فرعون."], ["واصطنعتك لنفسي", "أنعمت عليك بتلك النعم اجتباءً منا لك لتحمل رسالتنا."]], "m": "أجاب الله موسى: قد أُعطيت ما طلبت يا موسى، ولقد أنعمنا عليك مرة أخرى قبل هذه: لما أمر فرعون بذبح أبناء بني إسرائيل، أوحينا إلى أمك أن اقذفيه في الصندوق، فاقذفيه في النيل، فليلقه اليم بالساحل يأخذه عدو لي وعدو له، فهذه النجاة نعمة. وألقيت عليك محبة مني فأصبح من يراك يحبّك، ولتُربّى على مرأى مني، إذ تمشي أختك فتقول: هل أدلّكم على من يكفله؟ فرجعناك إلى أمك كي تقرّ عينها ولا تحزن. وأعظم من ذلك أنك قتلت نفساً فنجّيناك من الغم بعد ائتمار آل فرعون على قتلك، وغفرنا لك. وابتليناك ابتلاءً عظيماً: حمل أمك بك في سنة القتل، وإلقاؤها بك في اليم، وتحريم المراضع عليك، وأخذك بلحية فرعون، وقتلك القبطي، وغربتك في مدين، وضلالك الطريق بأهلك. فلبثت سنين في أهل مدين ترعى غنم شعيب عشراً، ثم جئت من مدين إلى طور سيناء على موعد قدّرناه لك وما كنت تعلمه، واصطنعتك لنفسي: خلقتك وربّيتك وابتليتك لأحمّلك عبء الرسالة إلى فرعون وبني إسرائيل.", "h": ["مظاهر لطف الله تعالى وحسن تدبيره في خلقه.", "مظاهر إكرام الله تعالى ولطفه بعبده ورسوله موسى ﵇.", "آية حب الله تعالى لموسى، وأثر ذلك في حب الناس له.", "تقرير نبوة محمد ﷺ بإخباره في كتابه بمثل هذه الأحداث في قصص موسى ﵇."], "k": "«وفتنّاك فتوناً»… كل محنة مرّ بها كانت إعداداً؛ فكيف أنظر إلى محنتي الحالية؟"}, {"lbl": "الآيات ٤٢ – ٤٨", "q": "ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي ﴿٤٢﴾ ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ﴿٤٣﴾ فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ ﴿٤٤﴾ قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ ﴿٤٥﴾ قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ ﴿٤٦﴾ فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَـٰٓءِيلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةٖ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰٓ ﴿٤٧﴾ إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ ﴿٤٨﴾", "w": [["بآياتي", "بالمعجزات التي آتيتك كالعصا واليد وغيرها."], ["ولا تنيا في ذكري", "لا تفترا ولا تقصّرا في ذكري، فإنه سر الحياة وعونكما على أداء الرسالة."], ["إنه طغى", "تجاوز قدره بادّعائه الألوهية والربوبية."], ["قولاً ليّناً", "خالياً من الغلظة والعنف."], ["لعله يتذكّر", "فيما تقولان فيهتدي إلى معرفتنا فيخشانا فيؤمن، ويرسل معكما بني إسرائيل."], ["يفرط علينا", "يعجل بعقوبتنا قبل أن ندعوه ونبيّن له."], ["أو أن يطغى", "يزداد طغياناً وظلماً."], ["أسمع وأرى", "أسمع ما تقولانه وما يقال لكما، وأرى ما تعملان وما يُعمل بكما."], ["فأرسل معنا بني إسرائيل", "لنذهب بهم إلى أرض المعاد، أرض أبيهم إبراهيم."], ["بآية", "معجزة تدل على صدقنا وأنا رسولا ربك حقاً."], ["والسلام على من اتبع الهدى", "النجاة من العذاب في الدارين لمن آمن واتقى."], ["من كذّب وتولّى", "كذّب بالحق وأعرض عنه فلم يقبله."]], "m": "أمره بالذهاب مع أخيه هارون مزوّدين بالعصا واليد، ونهاهما عن التقصير في ذكره، فقال: اذهب أنت وأخوك بآياتي ولا تفترا في ذكري، اذهبا إلى فرعون إنه تجاوز حدّه من عبد إلى مدّعٍ للربوبية، وعلّمهما أسلوب الدعوة: فقولا له قولاً ليّناً خالياً من الغلظة والجفاء، رجاء أن يتذكّر فيراجع نفسه فيؤمن، أو يخشى العذاب فيرسل معكما بني إسرائيل. قالا: إننا نخاف أن يعجل بعقوبتنا بالضرب أو القتل، أو أن يزداد طغياناً. قال: لا تخافا، إنني معكما بنصري وتأييدي، أسمع ما تقولان وما يقول لكما، وأرى ما تعملان وما يعمل، فأحقّ عملكما وأبطل عمله. فأتياه فقولا: إنا رسولا ربك، فأرسل معنا بني إسرائيل ولا تعذّبهم بقتل رجالهم واستحياء نسائهم، قد جئناك بحجة من ربك، والأمان لمن اتبع الهدى، فاتبعه تسلم، إنا قد أوحي إلينا أن العذاب على من كذّب بالحق وأعرض عنه كبرياءً وعناداً.", "h": ["عظم شأن الذكر بالقلب واللسان والجوارح، أي بالطاعة فعلاً وتركاً.", "وجوب مراعاة الحكمة في دعوة الناس إلى ربهم.", "تقرير معيّة الله تعالى مع أوليائه وصالحي عباده بنصرهم وتأييدهم.", "تقرير أن السلامة من عذاب الدنيا والآخرة هي من نصيب متّبعي الهدى.", "شرعية إتيان الظالم وأمره ونهيه والصبر على أذاه.", "عدم المؤاخذة على الخوف حيث وُجدت أسبابه."], "k": "«فقولا له قولاً ليّناً»… أُمرا باللين مع فرعون؛ فكيف ألين مع من أختلف معه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (219, 20, 49, 59, 'سورة طه ٤٩ – ٥٩', '«ربنا الذي أعطى كل شيء خلقه ثم هدى»، و«منها خلقناكم وفيها نعيدكم»، وموعد يوم الزينة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 219) = $j$[{"lbl": "الآيات ٤٩ – ٥٥", "q": "قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ ﴿٤٩﴾ قَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ ﴿٥٠﴾ قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ ﴿٥١﴾ قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبٖۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى ﴿٥٢﴾ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَسَلَكَ لَكُمۡ فِيهَا سُبُلٗا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّن نَّبَاتٖ شَتَّىٰ ﴿٥٣﴾ كُلُواْ وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ ﴿٥٤﴾ ۞مِنۡهَا خَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ ﴿٥٥﴾", "w": [["أعطى كل شيء خلقه", "خلقه الذي هو عليه متميّز به عن غيره."], ["ثم هدى", "هدى الحيوان منه إلى طلب مطعمه ومشربه ومسكنه."], ["فما بال القرون الأولى", "قاله فرعون ليصرف موسى عن الإدلاء بالحجج حتى لا يفتضح: فما حال قوم نوح وعاد وثمود في عبادتهم الأوثان؟"], ["علمها عند ربي", "علم أعمالهم وجزائهم عليها عند ربي، دعنا من هذا فإنه لا يعنينا."], ["لا يضلّ ربي ولا ينسى", "أعمال تلك الأمم في كتاب محفوظ وسيجزيهم بها، فإن ربي لا يخطئ ولا ينسى."], ["مهداً", "فراشاً."], ["وسلك لكم فيها سبلاً", "سهّل لكم فيها طرقاً."], ["أزواجاً من نبات شتى", "أصنافاً مختلفة الألوان والطعوم."], ["لآيات", "لدلائل واضحات على قدرة الله وعلمه وحكمته ورحمته."], ["لأولي النهى", "أصحاب العقول، وسُمّي العقل نُهية لأنه ينهى صاحبه عن ارتكاب القبائح."], ["منها خلقناكم", "من الأرض."], ["تارة أخرى", "مرة أخرى، إذ الأولى كانت خلقاً من طين الأرض، وهذه إخراجاً من الأرض."]], "m": "وصل موسى وأخوه إلى فرعون فدعواه بأسلوب هادئ ليّن كما أُمرا، ولم يقولا له: لا سلام عليك، فقال فرعون: فمن ربكما يا موسى؟ أفرده بالذكر للإدلال عليه بنعمة التربية ولأنه الرسول الأول. قال موسى: ربنا الذي أعطى كل مخلوق خلقه الذي يتميّز به من شكل ولون وصفة، ثم هدى الأحياء إلى طلب رزقها وطرق بقائها. فلما أُفحم قال صارفاً له خشية الفضيحة أمام ملئه: فما بال القرون الأولى من قوم نوح وهود وصالح؟ فعرف موسى أنه يريد صرفه، فقال: علمها عند ربي في كتاب محفوظ، وسيجزيهم بعملهم، وما عجّل أو أخّر من العقوبة فلحكمة، لا يخطئ ربي ولا ينسى. ثم اغتنم الفرصة فوصف ربه: الذي جعل لكم الأرض فراشاً، وسهّل لكم فيها طرقاً، وأنزل من السماء ماءً، فأخرجنا به أصنافاً من نبات مختلفة الألوان والطعوم، وهذا من قول الله تتميماً لكلام موسى وتذكيراً لأهل مكة، كلوا وارعوا أنعامكم واشكروا لنا بعبادتنا، إن في ذلك لدلالات على قدرته واستحقاقه العبادة لا يعقلها إلا أصحاب العقول. من الأرض خلقنا أصلكم آدم، وفيها نعيدكم بالموت، ومنها نخرجكم مرة أخرى يوم القيامة للحساب والجزاء.", "h": ["تعيّن إجابة السائل، ولتكن بالعلم الصحيح النافع.", "تقرير مبدأ: من حسن إسلام المرء تركه ما لا يعنيه.", "تنزّه الرب تعالى عن الخطأ والنسيان.", "الاستدلال بالآيات الكونية على الخالق عز وجل وقدرته وألوهيته.", "احترام العقول وتقديرها لأنها تعقل صاحبها دون الباطل والشر.", "تسمية العقل نُهية لأنه ينهى صاحبه عن القبائح."], "k": "«علمها عند ربي»… سؤال لا يعنيني أشتغل به؛ فهل أدعه لما ينفعني؟"}, {"lbl": "الآيات ٥٦ – ٥٩", "q": "وَلَقَدۡ أَرَيۡنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ ﴿٥٦﴾ قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَٰمُوسَىٰ ﴿٥٧﴾ فَلَنَأۡتِيَنَّكَ بِسِحۡرٖ مِّثۡلِهِۦ فَٱجۡعَلۡ بَيۡنَنَا وَبَيۡنَكَ مَوۡعِدٗا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَآ أَنتَ مَكَانٗا سُوٗى ﴿٥٨﴾ قَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحٗى ﴿٥٩﴾", "w": [["أريناه آياتنا كلها", "أبصرناه حججنا وأدلّتنا على صدق رسولينا موسى وهارون كلها، فرفضها."], ["من أرضنا", "أرض مصر التي فرعون ملك عليها."], ["بسحرك يا موسى", "يشير إلى العصا واليد البيضاء."], ["مكاناً سوى", "مكاناً عدلاً بيننا وبينك، ساحة كبرى مكشوفة مستوية يرى ما فيها كل ناظر."], ["يوم الزينة", "يوم عيد يتزيّنون فيه ويقعدون عن العمل."], ["وأن يُحشر الناس ضحى", "يؤتى بالناس من كل أنحاء البلاد للنظر في المباراة."], ["فتولّى فرعون", "انصرف من مجلس الحوار في كبرياء."], ["فجمع كيده", "ذوي كيده وقوته من السحرة."]], "m": "ما زال السياق في الحوار بين موسى وهارون وفرعون: ولقد أرينا فرعون أدلّتنا كلها على أنهما رسولان من قبلنا، فكذّب بها وأبى الاعتراف، وقال: أجئتنا لتخرجنا من ديارنا ومملكتنا بسحرك الذي انقلبت به عصاك حيّة؟ فلنأتينّك بسحر مثله، فاجعل بيننا وبينك موعداً لا نخلفه نحن ولا أنت، مكاناً عدلاً متّسعاً يرى كل ناظر ما يجري فيه. قال موسى: موعدكم يوم الزينة، يوم عيد للأقباط يتجمّلون فيه، وأن يُجمع الناس ضحى من كل أنحاء المملكة. فانصرف فرعون من مجلس المحاورة وكله كبر وعناد، فجمع قواته من السحرة لإنفاذ كيده، ثم أتى.", "h": ["بيان كبر فرعون وصلفه وطغيانه.", "للسحر آثار، وله مدارس يُتعلّم فيها، ورجال يحذقونه ويعلّمونه.", "مشروعية المبارزة والمباراة لإظهار الحق وإبطال الباطل.", "مشروعية اختيار المكان والزمان اللائق للقتال والمباراة ونحوهما."], "k": "«موعدكم يوم الزينة وأن يُحشر الناس ضحى»… اختار للحق أوضح ساحة؛ فهل أعرض الحق بوضوح أم أخفيه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 219;
insert into public.tdb_cards(topic, i, body) select 219, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٩ – ٥٥", "q": "قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ ﴿٤٩﴾ قَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ ﴿٥٠﴾ قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ ﴿٥١﴾ قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبٖۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى ﴿٥٢﴾ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَسَلَكَ لَكُمۡ فِيهَا سُبُلٗا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّن نَّبَاتٖ شَتَّىٰ ﴿٥٣﴾ كُلُواْ وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ ﴿٥٤﴾ ۞مِنۡهَا خَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ ﴿٥٥﴾", "w": [["أعطى كل شيء خلقه", "خلقه الذي هو عليه متميّز به عن غيره."], ["ثم هدى", "هدى الحيوان منه إلى طلب مطعمه ومشربه ومسكنه."], ["فما بال القرون الأولى", "قاله فرعون ليصرف موسى عن الإدلاء بالحجج حتى لا يفتضح: فما حال قوم نوح وعاد وثمود في عبادتهم الأوثان؟"], ["علمها عند ربي", "علم أعمالهم وجزائهم عليها عند ربي، دعنا من هذا فإنه لا يعنينا."], ["لا يضلّ ربي ولا ينسى", "أعمال تلك الأمم في كتاب محفوظ وسيجزيهم بها، فإن ربي لا يخطئ ولا ينسى."], ["مهداً", "فراشاً."], ["وسلك لكم فيها سبلاً", "سهّل لكم فيها طرقاً."], ["أزواجاً من نبات شتى", "أصنافاً مختلفة الألوان والطعوم."], ["لآيات", "لدلائل واضحات على قدرة الله وعلمه وحكمته ورحمته."], ["لأولي النهى", "أصحاب العقول، وسُمّي العقل نُهية لأنه ينهى صاحبه عن ارتكاب القبائح."], ["منها خلقناكم", "من الأرض."], ["تارة أخرى", "مرة أخرى، إذ الأولى كانت خلقاً من طين الأرض، وهذه إخراجاً من الأرض."]], "m": "وصل موسى وأخوه إلى فرعون فدعواه بأسلوب هادئ ليّن كما أُمرا، ولم يقولا له: لا سلام عليك، فقال فرعون: فمن ربكما يا موسى؟ أفرده بالذكر للإدلال عليه بنعمة التربية ولأنه الرسول الأول. قال موسى: ربنا الذي أعطى كل مخلوق خلقه الذي يتميّز به من شكل ولون وصفة، ثم هدى الأحياء إلى طلب رزقها وطرق بقائها. فلما أُفحم قال صارفاً له خشية الفضيحة أمام ملئه: فما بال القرون الأولى من قوم نوح وهود وصالح؟ فعرف موسى أنه يريد صرفه، فقال: علمها عند ربي في 