insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (220, 20, 60, 71, 'سورة طه ٦٠ – ٧١', '«ويلكم لا تفتروا على الله كذباً»، والمباراة: «فأوجس في نفسه خيفة موسى»، و«فأُلقي السحرة سجّداً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 220) = $j$[{"lbl": "الآيات ٦٠ – ٦٦", "q": "فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ ﴿٦٠﴾ قَالَ لَهُم مُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُواْ عَلَى ٱللَّهِ كَذِبٗا فَيُسۡحِتَكُم بِعَذَابٖۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ ﴿٦١﴾ فَتَنَٰزَعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ وَأَسَرُّواْ ٱلنَّجۡوَىٰ ﴿٦٢﴾ قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ ﴿٦٣﴾ فَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفّٗاۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ ﴿٦٤﴾ قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ ﴿٦٥﴾ قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ ﴿٦٦﴾", "w": [["ويلكم", "دعاء عليهم، معناه: ألزمكم الله الويل، وهو الهلاك."], ["فيسحتكم بعذاب", "يهلككم بعذاب من عنده."], ["فتنازعوا أمرهم", "في شأن موسى وهارون: هل هما رسولان أو ساحران؟"], ["وأسرّوا النجوى", "قولهم: إن هذان لساحران."], ["بطريقتكم المثلى", "بأشراف قومكم وساداتهم."], ["فأجمعوا كيدكم", "أحكموا أمر كيدكم حتى لا تختلفوا فيه."], ["قد أفلح اليوم من استعلى", "قد فاز من غلب."], ["إما أن تلقي", "عصاك."], ["يخيّل إليه أنها تسعى", "خُيّل إلى موسى أنها حيّات تسعى، لأنهم طلوها بالزئبق، فلما ضربت الشمس عليها اضطربت واهتزّت."]], "m": "ما زال السياق في الحوار بين موسى والسحرة الذين جمعهم فرعون: قال لهم مخوّفاً لعلهم يتوبون: ويلكم، لا تتقوّلوا على الله كذباً فيهلككم بعذاب استئصال، وقد خسر من كذب على الله. فلما سمعوا كلامه اختلفوا: أهذا كلام ساحر أم رسول؟ وأخفوا ما تناجوا به: إن هذان لساحران يريدان أن يخرجاكم من دياركم المصرية بسحرهما، ويذهبا بأشرافكم وساداتكم فيتابعوهما على دينهما، فأحكموا أمركم حتى لا تختلفوا، ثم ائتوا صفاً واحداً متراصّاً، وقد فاز اليوم من غلب. ثم قالوا بأمر فرعون: يا موسى، إما أن تلقي عصاك، وإما أن نكون أول من ألقى. قال: بل ألقوا، فألقوا حبالهم وعصيّهم، وكانت ألوفاً، فغطّت الساحة وهي تتحرّك وتضطرب لأنها مطليّة بالزئبق، فلما سخنت بحر الشمس خُيّل إلى موسى من سحرهم أنها تسعى.", "h": ["حرمة الكذب على الله تعالى، وأنه ذنب يسبّب دمار الكاذب وخسرانه.", "من مكر الإنسان اللئيم أن يحوّل القضية الدينية البحتة إلى سياسة، خوفاً من التأثير على النفوس فتؤمن وتهتدي إلى الحق.", "معيّة الله تعالى لموسى وهارون تجلّت في تصرّفات موسى، إذ الإذن لهم بالإلقاء أولاً من الحكمة، وذلك أن الذي يبقى في نفوس النظّارة هو المشهد الأخير والكلمة الأخيرة."], "k": "«لا تفتروا على الله كذباً»… قالها لخصومه نصحاً قبل المباراة؛ فهل أنصح حتى من أخاصمه؟"}, {"lbl": "الآيات ٦٧ – ٧١", "q": "فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ ﴿٦٧﴾ قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ ﴿٦٨﴾ وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرٖۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ ﴿٦٩﴾ فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدٗا قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ ﴿٧٠﴾ قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابٗا وَأَبۡقَىٰ ﴿٧١﴾", "w": [["فأوجس في نفسه خيفة", "أحسّ بالخوف في نفسه."], ["أنت الأعلى", "الغالب المنتصر."], ["تلقف", "تبتلع بسرعة ما صنع السحرة من تلك الحبال والعصي."], ["كيد ساحر", "كيد سحر لا بقاء له ولا ثبات."], ["ولا يفلح الساحر", "لا يفوز بمطلوبه حيثما كان."], ["فأُلقي السحرة سجّداً", "ألقوا بأنفسهم ورءوسهم على الأرض ساجدين."], ["إنه لكبيركم", "لمعلّمكم الذي علّمكم السحر."], ["من خلاف", "يد يمنى مع رجل يسرى."], ["في جذوع النخل", "على جذوع النخل."], ["أيّنا أشد عذاباً وأبقى", "يعني نفسه، ورب موسى: أيّنا أشد عذاباً وأدومه على مخالفته."]], "m": "لما ألقى السحرة حبالهم وعصيّهم وامتلأت بها الساحة شعر موسى بخوف في نفسه، فأوحى إليه ربه في اللحظة: لا تخف إنك أنت الغالب، وألق ما في يمينك تبتلع بسرعة ما صنعوا، إنما صنعوا مكر ساحر وخدعته، ولا يفوز الساحر بما أراد حيث أتى، لأنه مجرد تخييلات. فلما شاهد السحرة ابتلاع العصا لكل حبالهم وعصيّهم عرفوا أنه ليس سحراً، وإنما معجزة سماوية، فألقوا بأنفسهم ساجدين لله لما بهر نفوسهم، وقالوا في وضوح: آمنّا برب هارون وموسى. فصاح فرعون مهدّداً ليتلافى شرّ الهزيمة: آمنتم له قبل أن آذن لكم؟ إنه لمعلّمكم الذي علّمكم السحر فتواطأتم معه، فلأقطعنّ أيديكم وأرجلكم من خلاف تعذيباً وتنكيلاً، ولأصلبنّكم على جذوع النخل عبرة لغيركم، ولتعلمنّ أيّنا أشد عذاباً وأدوم: رب موسى أو أنا!", "h": ["الشعور بالخوف والإحساس به عند معاينة أسبابه لا يقدح في الإيمان.", "تقرير أن ما يُظهر السحرة من تحويل الشيء إلى آخر إنما هو مجرد تخييل لا حقيقة له.", "حرمة السحر لأنه تزوير وخداع.", "قوة تأثير المعجزة في نفس السحرة لما ظهر لهم من الفرق بين الآية والسحر.", "شجاعة المؤمن لا يرهبها خوف بقتل ولا بصلب."], "k": "«فأُلقي السحرة سجّداً»… ساعة واحدة نقلتهم من الكفر إلى السجود؛ فلا أيأس من هداية أحد."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 220;
insert into public.tdb_cards(topic, i, body) select 220, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٠ – ٦٦", "q": "فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ ﴿٦٠﴾ قَالَ لَهُم مُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُواْ عَلَى ٱللَّهِ كَذِبٗا فَيُسۡحِتَكُم بِعَذَابٖۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ ﴿٦١﴾ فَتَنَٰزَعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ وَأَسَرُّواْ ٱلنَّجۡوَىٰ ﴿٦٢﴾ قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ ﴿٦٣﴾ فَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفّٗاۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ ﴿٦٤﴾ قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ ﴿٦٥﴾ قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ ﴿٦٦﴾", "w": [["ويلكم", "دعاء عليهم، معناه: ألزمكم الله الويل، وهو الهلاك."], ["فيسحتكم بعذاب", "يهلككم بعذاب من عنده."], ["فتنازعوا أمرهم", "في شأن موسى وهارون: هل هما رسولان أو ساحران؟"], ["وأسرّوا النجوى", "قولهم: إن هذان لساحران."], ["بطريقتكم المثلى", "بأشراف قومكم وساداتهم."], ["فأجمعوا كيدكم", "أحكموا أمر كيدكم حتى لا تختلفوا فيه."], ["قد أفلح اليوم من استعلى", "قد فاز من غلب."], ["إما أن تلقي", "عصاك."], ["يخيّل إليه أنها تسعى", "خُيّل إلى موسى أنها حيّات تسعى، لأنهم طلوها بالزئبق، فلما ضربت الشمس عليها اضطربت واهتزّت."]], "m": "ما زال السياق في الحوار بين موسى والسحرة الذين جمعهم فرعون: قال لهم مخوّفاً لعلهم يتوبون: ويلكم، لا تتقوّلوا على الله كذباً فيهلككم بعذاب استئصال، وقد خسر من كذب على الله. فلما سمعوا كلامه اختلفوا: أهذا كلام ساحر أم رسول؟ وأخفوا ما تناجوا به: إن هذان لساحران يريدان أن يخرجاكم من دياركم المصرية بسحرهما، ويذهبا بأشرافكم وساداتكم فيتابعوهما على دينهما، فأحكموا أمركم حتى لا تختلفوا، ثم ائتوا صفاً واحداً متراصّاً، وقد فاز اليوم من غلب. ثم قالوا بأمر فرعون: يا موسى، إما أن تلقي عصاك، وإما أن نكون أول من ألقى. قال: بل ألقوا، فألقوا حبالهم وعصيّهم، وكانت ألوفاً، فغطّت الساحة وهي تتحرّك وتضطرب لأنها مطليّة بالزئبق، فلما سخنت بحر الشمس خُيّل إلى موسى من سحرهم أنها تسعى.", "h": ["حرمة الكذب على الله تعالى، وأنه ذنب يسبّب دمار الكاذب وخسرانه.", "من مكر الإنسان اللئيم أن يحوّل القضية الدينية البحتة إلى سياسة، خوفاً من التأثير على النفوس فتؤمن وتهتدي إلى الحق.", "معيّة الله تعالى لموسى وهارون تجلّت في تصرّفات موسى، إذ الإذن لهم بالإلقاء أولاً من الحكمة، وذلك أن الذي يبقى في نفوس النظّارة هو المشهد الأخير والكلمة الأخيرة."], "k": "«لا تفتروا على الله كذباً»… قالها لخصومه نصحاً قبل المباراة؛ فهل أنصح حتى من أخاصمه؟"}, {"lbl": "الآيات ٦٧ – ٧١", "q": "فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ ﴿٦٧﴾ قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ ﴿٦٨﴾ وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرٖۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ ﴿٦٩﴾ فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدٗا قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ ﴿٧٠﴾ قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابٗا وَأَبۡقَىٰ ﴿٧١﴾", "w": [["فأوجس في نفسه خيفة", "أحسّ بالخوف في نفسه."], ["أنت الأعلى", "الغالب المنتصر."], ["تلقف", "تبتلع بسرعة ما صنع السحرة من تلك الحبال والعصي."], ["كيد ساحر", "كيد سحر لا بقاء له ولا ثبات."], ["ولا يفلح الساحر", "لا يفوز بمطلوبه حيثما كان."], ["فأُلقي السحرة سجّداً", "ألقوا بأنفسهم ورءوسهم على الأرض ساجدين."], ["إنه لكبيركم", "لمعلّمكم الذي علّمكم السحر."], ["من خلاف", "يد يمنى مع رجل يسرى."], ["في جذوع النخل", "على جذوع النخل."], ["أيّنا أشد عذاباً وأبقى", "يعني نفسه، ورب موسى: أيّنا أشد عذاباً وأدومه على مخالفته."]], "m": "لما ألقى السحرة حبالهم وعصيّهم وامتلأت بها الساحة شعر موسى بخوف في نفسه، فأوحى إليه ربه في اللحظة: لا تخف إنك أنت الغالب، وألق ما في يمينك تبتلع بسرعة ما صنعوا، إنما صنعوا مكر ساحر وخدعته، ولا يفوز الساحر بما أراد حيث أتى، لأنه مجرد تخييلات. فلما شاهد السحرة ابتلاع العصا لكل حبالهم وعصيّهم عرفوا أنه ليس سحراً، وإنما معجزة سماوية، فألقوا بأنفسهم ساجدين لله لما بهر نفوسهم، وقالوا في وضوح: آمنّا برب هارون وموسى. فصاح فرعون مهدّداً ليتلافى شرّ الهزيمة: آمنتم له قبل أن آذن لكم؟ إنه لمعلّمكم الذي علّمكم السحر فتواطأتم معه، فلأقطعنّ أيديكم وأرجلكم من خلاف تعذيباً وتنكيلاً، ولأصلبنّكم على جذوع النخل عبرة لغيركم، ولتعلمنّ أيّنا أشد عذاباً وأدوم: رب موسى أو أنا!", "h": ["الشعور بالخوف والإحساس به عند معاينة أسبابه لا يقدح في الإيمان.", "تقرير أن ما يُظهر السحرة من تحويل الشيء إلى آخر إنما هو مجرد تخييل لا حقيقة له.", "حرمة السحر لأنه تزوير وخداع.", "قوة تأثير المعجزة في نفس السحرة لما ظهر لهم من الفرق بين الآية والسحر.", "شجاعة المؤمن لا يرهبها خوف بقتل ولا بصلب."], "k": "«فأُلقي السحرة سجّداً»… ساعة واحدة نقلتهم من الكفر إلى السجود؛ فلا أيأس من هداية أحد."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (221, 20, 72, 82, 'سورة طه ٧٢ – ٨٢', '«لن نؤثرك على ما جاءنا من البيّنات»، وإغراق فرعون، و«وإني لغفّار لمن تاب وآمن وعمل صالحاً ثم اهتدى»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 221) = $j$[{"lbl": "الآيات ٧٢ – ٧٦", "q": "قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ ﴿٧٢﴾ إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرٞ وَأَبۡقَىٰٓ ﴿٧٣﴾ إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ ﴿٧٤﴾ وَمَن يَأۡتِهِۦ مُؤۡمِنٗا قَدۡ عَمِلَ ٱلصَّـٰلِحَٰتِ فَأُوْلَـٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ ﴿٧٥﴾ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ ﴿٧٦﴾", "w": [["لن نؤثرك", "لن نختارك يا فرعون."], ["فاقض ما أنت قاض", "اصنع ما قلت إنك تصنعه بنا."], ["والله خير وأبقى", "خير منك ثواباً إذا أُطيع، وأبقى منك عذاباً إذا عُصي."], ["مجرماً", "على نفسه مفسداً لها بآثار الشرك والكفر والمعاصي."], ["جزاء من تزكّى", "ثواب من تطهّر من آثار الشرك والمعاصي بالإيمان والعمل الصالح."]], "m": "لما هدّدهم فرعون بالقتل والصلب لإيمانهم بالله وكفرهم به وهو الطاغوت، قالوا: لن نختارك يا فرعون على ما جاءنا من البيّنات القاطعة على أن رب موسى وهارون هو الرب الحق، وعلى الذي خلقنا، فاصنع ما أنت عازم عليه من القتل والصلب، إنما تقضي في هذه الحياة الدنيا بما لك فيها من سلطان، أما الآخرة فسوف يُقضى عليك فيها بالخلد في العذاب. إنا آمنا بربنا خالقنا ومدبّر أمرنا ليغفر لنا ذنوبنا، وما أكرهتنا عليه من تعلّم السحر والعمل به، فقد كان فرعون ألزمهم به لمحاربة موسى، والله خير ثواباً لمن آمن به، وأبقى عذاباً لمن كفر به وعصاه. إنه من يأت ربه مجرماً على نفسه بالشرك والمعاصي فإن له جهنم لا يموت فيها فيستريح، ولا يحيا حياة يسعد فيها، ومن يأته مؤمناً قد عمل الصالحات فأدّى الفرائض واجتنب المناهي فأولئك لهم الدرجات العلى، جنات إقامة تجري من تحتها الأنهار خالدين فيها، وذلك جزاء من تطهّر بالإيمان وصالح الأعمال. ولا شك أن هذا العلم حصل للسحرة من دعوة موسى وهارون، إذ أقاما بينهم زمناً طويلاً.", "h": ["لا يؤثر الكفر على الإيمان، والباطل على الحق، والخرافة على الدين الصحيح، إلا أحمق جاهل.", "تقرير مبدأ أن عذاب الدنيا يُتحمّل ويُصبر عليه بالنظر إلى عذاب الآخرة.", "الإكراه نوعان: ما كان بالضرب الذي لا يُطاق يُغفر لصاحبه، وما كان لمجرد تهديد ومطالبة فإنه لا يُغفر إلا بالتوبة الصادقة، وإكراه السحرة كان من النوع الآخر.", "بيان جزاء كل من الكفر والمعاصي، والإيمان والعمل الصالح، في الدار الآخرة."], "k": "«إنما تقضي هذه الحياة الدنيا»… كل سلطان على الأرض ينتهي هنا؛ فلمن أخاف؟"}, {"lbl": "الآيات ٧٧ – ٨٢", "q": "وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقٗا فِي ٱلۡبَحۡرِ يَبَسٗا لَّا تَخَٰفُ دَرَكٗا وَلَا تَخۡشَىٰ ﴿٧٧﴾ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ ﴿٧٨﴾ وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ ﴿٧٩﴾ يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ قَدۡ أَنجَيۡنَٰكُم مِّنۡ عَدُوِّكُمۡ وَوَٰعَدۡنَٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ ﴿٨٠﴾ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ ﴿٨١﴾ وَإِنِّي لَغَفَّارٞ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا ثُمَّ ٱهۡتَدَىٰ ﴿٨٢﴾", "w": [["أن أسر بعبادي", "سِر ليلاً من أرض مصر."], ["طريقاً في البحر يبساً", "طريقاً في وسط البحر يابساً لا ماء فيه."], ["لا تخاف دركاً", "لا تخشى أن يدركك فرعون، ولا تخشى غرقاً."], ["فغشيهم من اليم", "غطّاهم من ماء البحر ما غطّاهم حتى غرقوا فيه."], ["وأضلّ فرعون قومه", "بدعائهم إلى الإيمان به والكفر بالله رب العالمين."], ["وما هدى", "لم يهدهم كما وعدهم بقوله: «وما أهديكم إلا سبيل الرشاد»."], ["جانب الطور الأيمن", "لأجل إعطاء موسى التوراة التي فيها نظام حياتهم ديناً ودنيا."], ["المنّ والسلوى", "المنّ: شيء أبيض كالثلج، والسلوى: طائر يقال له السُّمانى."], ["ولا تطغوا فيه", "بالإسراف فيه وعدم شكر الله تعالى عليه."], ["ثم اهتدى", "بالاستقامة على الإيمان والتوحيد والعمل الصالح حتى الموت."]], "m": "بعد الجدال الطويل وإباء فرعون وقومه الحق أوحى الله إلى موسى أن سِر ببني إسرائيل ليلاً، فاجعل لهم طريقاً في وسط البحر يابساً، وذلك بعد ضربه البحر بالعصا فانفلق فرقتين، لا تخاف أن يدركك فرعون ولا تخشى غرقاً. فاجتاز بنو إسرائيل، فأتبعهم فرعون بجنوده، فأطبق الله عليهم البحر فغطّاهم من مائه الشيء العظيم فأغرقهم أجمعين. وأضلّ فرعون قومه، إذ حرمهم الإيمان ودعاهم إلى الكفر، وما هداهم، وكان يزعم أنه ما يهديهم إلا سبيل الرشاد، وكذب. يا بني إسرائيل قد أنجيناكم من عدوكم، وواعدناكم مع نبيّكم جانب الطور الأيمن لإنزال التوراة، ونزّلنا عليكم المنّ والسلوى غذاءً في التيه، كلوا من حلال ما رزقناكم، ولا تطغوا فيه بترك الحلال إلى الحرام والإسراف وعدم الشكر، فيحلّ عليكم غضبي، ومن يحلل عليه غضبي فقد هوى في قعر جهنم وهلك. وإني لغفّار لمن تاب منكم ومن غيركم، وآمن، وعمل صالحاً فأدّى الفرائض واجتنب المناهي، ثم استمر على ذلك حتى مات.", "h": ["تقرير النبوة المحمدية، إذ مثل هذا القصص لا يقصّه إلا من يوحى إليه.", "آية انفلاق البحر ووجود طريق يابس فيه لبني إسرائيل حتى اجتازوه دالة على وجود الله تعالى وقدرته وعلمه ورحمته وحكمته.", "تذكير اليهود المعاصرين للدعوة الإسلامية بإنعام الله تعالى على سلفهم لعلهم يشكرون فيتوبون فيسلمون.", "تحريم الإسراف والظلم وكفر النعم.", "الغضب صفة لله تعالى كما يليق بجلاله وكماله، لا كصفات المحدثين."], "k": "«وإني لغفّار لمن تاب وآمن وعمل صالحاً ثم اهتدى»… التوبة بداية، والثبات «ثم اهتدى»؛ فهل أثبت بعد توبتي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 221;
insert into public.tdb_cards(topic, i, body) select 221, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٢ – ٧٦", "q": "قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ ﴿٧٢﴾ إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرٞ وَأَبۡقَىٰٓ ﴿٧٣﴾ إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ ﴿٧٤﴾ وَمَن يَأۡتِهِۦ مُؤۡمِنٗا قَدۡ عَمِلَ ٱلصَّـٰلِحَٰتِ فَأُوْلَـٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ ﴿٧٥﴾ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ ﴿٧٦﴾", "w": [["لن نؤثرك", "لن نختارك يا فرعون."], ["فاقض ما أنت قاض", "اصنع ما قلت إنك تصنعه بنا."], ["والله خير وأبقى", "خير منك ثواباً إذا أُطيع، وأبقى منك عذاباً إذا عُصي."], ["مجرماً", "على نفسه مفسداً لها بآثار الشرك والكفر والمعاصي."], ["جزاء من تزكّى", "ثواب من تطهّر من آثار الشرك والمعاصي بالإيمان والعمل الصالح."]], "m": "لما هدّدهم فرعون بالقتل والصلب لإيمانهم بالله وكفرهم به وهو الطاغوت، قالوا: لن نختارك يا فرعون على ما جاءنا من البيّنات القاطعة على أن رب موسى وهارون هو الرب الحق، وعلى الذي خلقنا، فاصنع ما أنت عازم عليه من القتل والصلب، إنما تقضي في هذه الحياة الدنيا بما لك فيها من سلطان، أما الآخرة فسوف يُقضى عليك فيها بالخلد في العذاب. إنا آمنا بربنا خالقنا ومدبّر أمرنا ليغفر لنا ذنوبنا، وما أكرهتنا عليه من تعلّم السحر والعمل به، فقد كان فرعون ألزمهم به لمحاربة موسى، والله خير ثواباً لمن آمن به، وأبقى عذاباً لمن كفر به وعصاه. إنه من يأت ربه مجرماً على نفسه بالشرك والمعاصي فإن له جهنم لا يموت فيها فيستريح، ولا يحيا حياة يسعد فيها، ومن يأته مؤمناً قد عمل الصالحات فأدّى الفرائض واجتنب المناهي فأولئك لهم الدرجات العلى، جنات إقامة تجري من تحتها الأنهار خالدين فيها، وذلك جزاء من تطهّر بالإيمان وصالح الأعمال. ولا شك أن هذا العلم حصل للسحرة من دعوة موسى وهارون، إذ أقاما بينهم زمناً طويلاً.", "h": ["لا يؤثر الكفر على الإيمان، والباطل على الحق، والخرافة على الدين الصحيح، إلا أحمق جاهل.", "تقرير مبدأ أن عذاب الدنيا يُتحمّل ويُصبر عليه بالنظر إلى عذاب الآخرة.", "الإكراه نوعان: ما كان بالضرب الذي لا يُطاق يُغفر لصاحبه، وما كان لمجرد تهديد ومطالبة فإنه لا يُغفر إلا بالتوبة الصادقة، وإكراه السحرة كان من النوع الآخر.", "بيان جزاء كل من الكفر والمعاصي، والإيمان والعمل الصالح، في الدار الآخرة."], "k": "«إنما تقضي هذه الحياة الدنيا»… كل سلطان على الأرض ينتهي هنا؛ فلمن أخاف؟"}, {"lbl": "الآيات ٧٧ – ٨٢", "q": "وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقٗا فِي ٱلۡبَحۡرِ يَبَسٗا لَّا تَخَٰفُ دَرَكٗا وَلَا تَخۡشَىٰ ﴿٧٧﴾ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ ﴿٧٨﴾ وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ ﴿٧٩﴾ يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ قَدۡ أَنجَيۡنَٰكُم مِّنۡ عَدُوِّكُمۡ وَوَٰعَدۡنَٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ ﴿٨٠﴾ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ ﴿٨١﴾ وَإِنِّي لَغَفَّارٞ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا ثُمَّ ٱهۡتَدَىٰ ﴿٨٢﴾", "w": [["أن أسر بعبادي", "سِر ليلاً من أرض مصر."], ["طريقاً في البحر يبساً", "طريقاً في وسط البحر يابساً لا ماء فيه."], ["لا تخاف دركاً", "لا تخشى أن يدركك فرعون، ولا تخشى غرقاً."], ["فغشيهم من اليم", "غطّاهم من ماء البحر ما غطّاهم حتى غرقوا فيه."], ["وأضلّ فرعون قومه", "بدعائهم إلى الإيمان به والكفر بالله رب العالمين."], ["وما هدى", "لم يهدهم كما وعدهم بقوله: «وما أهديكم إلا سبيل الرشاد»."], ["جانب الطور الأيمن", "لأجل إعطاء موسى التوراة التي فيها نظام حياتهم ديناً ودنيا."], ["المنّ والسلوى", "المنّ: شيء أبيض كالثلج، والسلوى: طائر يقال له السُّمانى."], ["ولا تطغوا فيه", "بالإسراف فيه وعدم شكر الله تعالى عليه."], ["ثم اهتدى", "بالاستقامة على الإيمان والتوحيد والعمل الصالح حتى الموت."]], "m": "بعد الجدال الطويل وإباء فرعون وقومه الحق أوحى الله إلى موسى أن سِر ببني إسرائيل ليلاً، فاجعل لهم طريقاً في وسط البحر يابساً، وذلك بعد ضربه البحر بالعصا فانفلق فرقتين، لا تخاف أن يدركك فرعون ولا تخشى غرقاً. فاجتاز بنو إسرائيل، فأتبعهم فرعون بجنوده، فأطبق الله عليهم البحر فغطّاهم من مائه الشيء العظيم فأغرقهم أجمعين. وأضلّ فرعون قومه، إذ حرمهم الإيمان ودعاهم إلى الكفر، وما هداهم، وكان يزعم أنه ما يهديهم إلا سبيل الرشاد، وكذب. يا بني إسرائيل قد أنجيناكم من عدوكم، وواعدناكم مع نبيّكم جانب الطور الأيمن لإنزال التوراة، ونزّلنا عليكم المنّ والسلوى غذاءً في التيه، كلوا من حلال ما رزقناكم، ولا تطغوا فيه بترك الحلال إلى الحرام والإسراف وعدم الشكر، فيحلّ عليكم غضبي، ومن يحلل عليه غضبي فقد هوى في قعر جهنم وهلك. وإني لغفّار لمن تاب منكم ومن غيركم، وآمن، وعمل صالحاً فأدّى الفرائض واجتنب المناهي، ثم استمر على ذلك حتى مات.", "h": ["تقرير النبوة المحمدية، إذ مثل هذا القصص لا يقصّه إلا من يوحى إليه.", "آية انفلاق البحر ووجود طريق يابس فيه لبني إسرائيل حتى اجتازوه دالة على وجود الله تعالى وقدرته وعلمه ورحمته وحكمته.", "تذكير اليهود المعاصرين للدعوة الإسلامية بإنعام الله تعالى على سلفهم لعلهم يشكرون فيتوبون فيسلمون.", "تحريم الإسراف والظلم وكفر النعم.", "الغضب صفة لله تعالى كما يليق بجلاله وكماله، لا كصفات المحدثين."], "k": "«وإني لغفّار لمن تاب وآمن وعمل صالحاً ثم اهتدى»… التوبة بداية، والثبات «ثم اهتدى»؛ فهل أثبت بعد توبتي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (222, 20, 83, 98, 'سورة طه ٨٣ – ٩٨', 'فتنة العجل: «وأضلّهم السامري»، وعتاب موسى لهارون ﵉، و«وانظر إلى إلهك الذي ظلت عليه عاكفاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 222) = $j$[{"lbl": "الآيات ٨٣ – ٨٩", "q": "۞وَمَآ أَعۡجَلَكَ عَن قَوۡمِكَ يَٰمُوسَىٰ ﴿٨٣﴾ قَالَ هُمۡ أُوْلَآءِ عَلَىٰٓ أَثَرِي وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ ﴿٨٤﴾ قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِيُّ ﴿٨٥﴾ فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗاۚ قَالَ يَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبٞ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِي ﴿٨٦﴾ قَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ أَوۡزَارٗا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ ﴿٨٧﴾ فَأَخۡرَجَ لَهُمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٞ فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ ﴿٨٨﴾ أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا ﴿٨٩﴾", "w": [["وما أعجلك", "أي شيء جعلك تترك قومك وتأتي قبلهم؟"], ["هم أولاء على أثري", "آتون بعدي، ليسوا ببعيدين مني."], ["وعجلت إليك رب لترضى", "استعجلت المجيء إليك طلباً لرضاك عني."], ["قد فتنّا قومك", "ابتليناهم بعبادة العجل."], ["وأضلّهم السامري", "عن الهدى الذي هو الإسلام إلى الشرك وعبادة غير الرب."], ["غضبان أسفاً", "شديد الغضب والحزن."], ["وعداً حسناً", "بأن يعطيكم التوراة فيها نظام حياتكم وشريعة ربكم."], ["أفطال عليكم العهد", "مدة الموعد، وهي ثلاثون يوماً."], ["فأخلفتم موعدي", "بترككم المجيء بعدي."], ["بملكنا", "بأمرنا وطاقتنا، ولكن غلب علينا الهوى."], ["أوزاراً", "أحمالاً من حلي نساء الأقباط."], ["فقذفناها", "ألقيناها في الحفرة."], ["ألقى السامري", "ألقى التراب الذي أخذه من تحت حافر فرس جبريل على الحلي."], ["عجلاً جسداً", "ذا جثّة."], ["له خوار", "الخوار: صوت البقر."], ["فنسي", "نسي موسى ربه هنا وذهب يطلبه."], ["ألا يرجع إليهم قولاً", "أنه لا يكلّمهم إذا كلّموه."]], "m": "بعد إنجاء بني إسرائيل وإغراق فرعون أُمر موسى أن يأتي بقومه إلى جانب الطور الأيمن ليؤتيهم التوراة، فاستعجل المسير واستخلف أخاه هارون ليسير بهم وراءه، فقال له ربه: وما أعجلك عن قومك يا موسى؟ قال: هم آتون بعدي، وعجلت إليك رب لترضى عني. قال: فإنا قد ابتليناهم من بعدك، وأضلّهم السامري بصنع العجل ودعوتهم إلى عبادته بحجة أنه الرب وأن موسى لم يهتد إليه. فلما أُعطي الألواح رجع إلى قومه شديد الغضب والحزن، فقال: يا قوم، ألم يعدكم ربكم وعداً حسناً بالتوراة وبالملك والسيادة؟ أفطال عليكم العهد، وهو ثلاثون يوماً لم تكتمل، أم أردتم أن يحلّ عليكم غضب من ربكم فأخلفتم موعدي بعكوفكم على العجل؟ قالوا معتذرين: ما أخلفنا موعدك بطاقتنا، إذ كنا مغلوبين لغلبة الهوى، ولكنا حُمّلنا أحمالاً من حلي القبط استعارها نساؤنا، فقال لنا السامري: لا تحل لكم، فحفر حفرة وأوقد فيها النار، فقذفناها فيها، فكذلك ألقى السامري ما معه من التراب، فأخرج لهم عجلاً جسداً له خوار، فقالوا: هذا إلهكم وإله موسى فنسي موسى وضلّ الطريق إليه. أفلا يرون أنه لا يجيبهم إذا كلّموه، ولا يملك لهم ضراً ولا نفعاً؟ ولكنه الجهل واتباع الهوى.", "h": ["ذمّ العجلة وبيان آثارها الضارة، فاستعجال موسى الموعد وتركه قومه وراءه كان سبباً في أمر عظيم، وهو عبادة العجل.", "مشروعية طلب رضا الله تعالى، ولكن بما يحب أن يُتقرّب به إليه.", "مشروعية الغضب لله تعالى، والحزن على ترك عبادته بمخالفة أمره ونهيه.", "مشروعية استعارة الحلي للنساء والزينة، وحرمة جحدها وأخذها بالباطل.", "وجوب استعمال العقل واستخدام الفكر للتمييز بين الحق والباطل، والخير والشر."], "k": "«أفلا يرون ألا يرجع إليهم قولاً»… ما الذي أعطيه قلبي وهو لا يملك لي ضراً ولا نفعاً؟"}, {"lbl": "الآيات ٩٠ – ٩٤", "q": "وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي وَأَطِيعُوٓاْ أَمۡرِي ﴿٩٠﴾ قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ ﴿٩١﴾ قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ ﴿٩٢﴾ أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي ﴿٩٣﴾ قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَلَمۡ تَرۡقُبۡ قَوۡلِي ﴿٩٤﴾", "w": [["فُتنتم به", "ابتُليتم به، أي بالعجل."], ["لن نبرح عليه عاكفين", "لن نزال عاكفين على عبادته."], ["إذ رأيتهم ضلّوا", "بعبادة العجل واتخاذه إلهاً من دون الله تعالى."], ["لا تأخذ بلحيتي", "حيث أخذ موسى من شدة غضبه بلحية أخيه وشعر رأسه يجرّه إليه يلومه."], ["ولم ترقب قولي", "لم تنتظر قولي فيما رأيته في ذلك."]], "m": "ما زال السياق في الحوار بعد رجوع موسى: ولقد قال لهم هارون من قبل رجوع موسى: يا قوم، إنما ابتُليتم بهذا العجل ليرى الله صبركم على عبادته ولزوم طاعة رسوله، وإن ربكم الرحمن الذي شاهدتم آثار رحمته، فاتبعوني في عبادة الله وحده، وأطيعوا أمري فإني خليفة الرسول فيكم. قالوا: لن نزال عاكفين على عبادته حتى يرجع إلينا موسى. فالتفت موسى إلى هارون معاتباً: ما منعك إذ رأيتهم ضلّوا بعبادة العجل ألا تلحق بي بمن معك من المسلمين وتترك المشركين؟ أفعصيت أمري؟ ومن شدة الوجد أخذ بشعر رأسه بيمينه وبلحيته بيساره يجرّه إليه، فقال هارون: يا ابن أم، لا تأخذ بلحيتي ولا برأسي، إن لي عذراً، إني خشيت إن أتيتك ببعض قومك وتركت عبّاد العجل أن تقول: فرّقت بين بني إسرائيل، ولم تنتظر قولي فيما رأيت.", "h": ["معصية الرسول تؤدّي إلى فتنة العاصي في دينه ودنياه.", "جواز العذل والعتاب للحبيب عند تقصيره فيما عُهد به إليه.", "جواز الاعتذار لمن اتُّهم بالتقصير وإن كان حقاً.", "قد يخطئ المجتهد في اجتهاده وقد يصيب."], "k": "«يا ابن أم لا تأخذ بلحيتي ولا برأسي»… حين يُعاتبني أحد بشدة، هل أجيبه بهذا الرفق؟"}, {"lbl": "الآيات ٩٥ – ٩٨", "q": "قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ ﴿٩٥﴾ قَالَ بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةٗ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي ﴿٩٦﴾ قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدٗا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفٗاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا ﴿٩٧﴾ إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمٗا ﴿٩٨﴾", "w": [["فما خطبك", "ما شأنك، وما هذا الأمر العظيم الذي صدر منك؟"], ["بصرت بما لم يبصروا به", "علمت من طريق الإبصار ما لم يعلموا به لأنهم لم يروه."], ["قبضة من أثر الرسول", "قبضة من تراب أثر حافر فرس الرسول جبريل ﵇."], ["فنبذتها", "ألقيتها وطرحتها على الحلي المصنوع عجلاً."], ["سوّلت لي نفسي", "زيّنت لي هذا العمل الذي هو صنع العجل."], ["أن تقول لا مساس", "اذهب تائهاً في الأرض طول حياتك وأنت تقول: لا مساس، أي لا يمسّني أحد ولا أمسّه."], ["ظلت", "ظللت طوال الوقت عاكفاً عليه."], ["في اليم نسفاً", "في البحر ننسفه بعد إحراقه وجعله كالنشارة."], ["إنما إلهكم الله", "لا معبود لكم إلا الله الذي لا إله إلا هو."]], "m": "بعد عذله أخاه التفت موسى إلى السامري، المنافق الذي أظهر الإسلام ثم عاد إلى عبادة البقر فصنع العجل ودعا إلى عبادته، فقال في غضب: ما شأنك يا سامري؟ قال: علمت ما لم يعلمه قومك، فقبضت قبضة من تراب أثر فرس الرسول فطرحتها في الحلي المصنوع عجلاً فخار، وكذلك زيّنت لي نفسي ذلك ففعلته. قال موسى: فاذهب، فإن لك مدة حياتك أن تقول لمن أراد أن يقربك: لا مساس، لتتيه طول عمرك في البرية عقوبة لك، وإن لك موعداً لعذاب يوم القيامة لن تخلفه. وانظر إلى إلهك المزعوم الذي ظللت عليه عاكفاً، والله لنحرقنّه ثم لننسفنّه في البحر نسفاً، ففعل حتى لا يُعثر له على أثر. ثم قال للمغرّر بهم: إنما إلهكم الحق الله الذي لا إله إلا هو، وسع كل شيء علماً، وما لم يكن ذا علم بكل شيء وقدرة على كل شيء فكيف يُعبد ويُطاع؟", "h": ["مشروعية الاستنطاق للمتّهم والاستجواب له.", "ما سوّلت النفس لأحد ولا زيّنت له شيئاً إلا تورّط فيه إن هو عمل بما سوّلته له.", "قد يجمع الله تعالى للعبد ذي الذنب العظيم بين عذاب الدنيا وعذاب الآخرة.", "مشروعية هجران المبتدع ونفيه وطرده، فلا يُسمح لأحد بالاتصال به والقرب منه.", "كسر الأصنام والأوثان والصور وآلات اللهو والباطل الصارفة عن عبادة الله تعالى."], "k": "«وكذلك سوّلت لي نفسي»… ما الذي تزيّنه لي نفسي الآن، وهل أعرضه على الوحي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 222;
insert into public.tdb_cards(topic, i, body) select 222, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٣ – ٨٩", "q": "۞وَمَآ أَعۡجَلَكَ عَن قَوۡمِكَ يَٰمُوسَىٰ ﴿٨٣﴾ قَالَ هُمۡ أُوْلَآءِ عَلَىٰٓ أَثَرِي وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ ﴿٨٤﴾ قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِيُّ ﴿٨٥﴾ فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗاۚ قَالَ يَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبٞ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِي ﴿٨٦﴾ قَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ أَوۡزَارٗا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ ﴿٨٧﴾ فَأَخۡرَجَ لَهُمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٞ فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ ﴿٨٨﴾ أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا ﴿٨٩﴾", "w": [["وما أعجلك", "أي شيء جعلك تترك قومك وتأتي قبلهم؟"], ["هم أولاء على أثري", "آتون بعدي، ليسوا ببعيدين مني."], ["وعجلت إليك رب لترضى", "استعجلت المجيء إليك طلباً لرضاك عني."], ["قد فتنّا قومك", "ابتليناهم بعبادة العجل."], ["وأضلّهم السامري", "عن الهدى الذي هو الإسلام إلى الشرك وعبادة غير الرب."], ["غضبان أسفاً", "شديد الغضب والحزن."], ["وعداً حسناً", "بأن يعطيكم التوراة فيها نظام حياتكم وشريعة ربكم."], ["أفطال عليكم العهد", "مدة الموعد، وهي ثلاثون يوماً."], ["فأخلفتم موعدي", "بترككم المجيء بعدي."], ["بملكنا", "بأمرنا وطاقتنا، ولكن غلب علينا الهوى."], ["أوزاراً", "أحمالاً من حلي نساء الأقباط."], ["فقذفناها", "ألقيناها في الحفرة."], ["ألقى السامري", "ألقى التراب الذي أخذه من تحت حافر فرس جبريل على الحلي."], ["عجلاً جسداً", "ذا جثّة."], ["له خوار", "الخوار: صوت البقر."], ["فنسي", "نسي موسى ربه هنا وذهب يطلبه."], ["ألا يرجع إليهم قولاً", "أنه لا يكلّمهم إذا كلّموه."]], "m": "بعد إنجاء بني إسرائيل وإغراق فرعون أُمر موسى أن يأتي بقومه إلى جانب الطور الأيمن ليؤتيهم التوراة، فاستعجل المسير واستخلف أخاه هارون ليسير بهم وراءه، فقال له ربه: وما أعجلك عن قومك يا موسى؟ قال: هم آتون بعدي، وعجلت إليك رب لترضى عني. قال: فإنا قد ابتليناهم من بعدك، وأضلّهم السامري بصنع العجل ودعوتهم إلى عبادته بحجة أنه الرب وأن موسى لم يهتد إليه. فلما أُعطي الألواح رجع إلى قومه شديد الغضب والحزن، فقال: يا قوم، ألم يعدكم ربكم وعداً حسناً بالتوراة وبالملك والسيادة؟ أفطال عليكم العهد، وهو ثلاثون يوماً لم تكتمل، أم أردتم أن يحلّ عليكم غضب من ربكم فأخلفتم موعدي بعكوفكم على العجل؟ قالوا معتذرين: ما أخلفنا موعدك بطاقتنا، إذ كنا مغلوبين لغلبة الهوى، ولكنا حُمّلنا أحمالاً من حلي القبط استعارها نساؤنا، فقال لنا السامري: لا تحل لكم، فحفر حفرة وأوقد فيها النار، فقذفناها فيها، فكذلك ألقى السامري ما معه من التراب، فأخرج لهم عجلاً جسداً له خوار، فقالوا: هذا إلهكم وإله موسى فنسي موسى وضلّ الطريق إليه. أفلا يرون أنه لا يجيبهم إذا كلّموه، ولا يملك لهم ضراً ولا نفعاً؟ ولكنه الجهل واتباع الهوى.", "h": ["ذمّ العجلة وبيان آثارها الضارة، فاستعجال موسى الموعد وتركه قومه وراءه كان سبباً في أمر عظيم، وهو عبادة العجل.", "مشروعية طلب رضا الله تعالى، ولكن بما يحب أن يُتقرّب به إليه.", "مشروعية الغضب لله تعالى، والحزن على ترك عبادته بمخالفة أمره ونهيه.", "مشروعية استعارة الحلي للنساء والزينة، وحرمة جحدها وأخذها بالباطل.", "وجوب استعمال العقل واستخدام الفكر للتمييز بين الحق والباطل، والخير والشر."], "k": "«أفلا يرون ألا يرجع إليهم قولاً»… ما الذي أعطيه قلبي وهو لا يملك لي ضراً ولا نفعاً؟"}, {"lbl": "الآيات ٩٠ – ٩٤", "q": "وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي وَأَطِيعُوٓاْ أَمۡرِي ﴿٩٠﴾ قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ ﴿٩١﴾ قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ ﴿٩٢﴾ أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي ﴿٩٣﴾ قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَلَمۡ تَرۡقُبۡ قَوۡلِي ﴿٩٤﴾", "w": [["فُتنتم به", "ابتُليتم به، أي بالعجل."], ["لن نبرح عليه عاكفين", "لن نزال عاكفين على عبادته."], ["إذ رأيتهم ضلّوا", "بعبادة العجل واتخاذه إلهاً من دون الله تعالى."], ["لا تأخذ بلحيتي", "حيث أخذ موسى من شدة غضبه بلحية أخيه وشعر رأسه يجرّه إليه يلومه."], ["ولم ترقب قولي", "لم تنتظر قولي فيما رأيته في ذلك."]], "m": "ما زال السياق في الحوار بعد رجوع موسى: ولقد قال لهم هارون من قبل رجوع موسى: يا قوم، إنما ابتُليتم بهذا العجل ليرى الله صبركم على عبادته ولزوم طاعة رسوله، وإن ربكم الرحمن الذي شاهدتم آثار رحمته، فاتبعوني في عبادة الله وحده، وأطيعوا أمري فإني خليفة الرسول فيكم. قالوا: لن نزال عاكفين على عبادته حتى يرجع إلينا موسى. فالتفت موسى إلى هارون معاتباً: ما منعك إذ رأيتهم ضلّوا بعبادة العجل ألا تلحق بي بمن معك من المسلمين وتترك المشركين؟ أفعصيت أمري؟ ومن شدة الوجد أخذ بشعر رأسه بيمينه وبلحيته بيساره يجرّه إليه، فقال هارون: يا ابن أم، لا تأخذ بلحيتي ولا برأسي، إن لي عذراً، إني خشيت إن أتيتك ببعض قومك وتركت عبّاد العجل أن تقول: فرّقت بين بني إسرائيل، ولم تنتظر قولي فيما رأيت.", "h": ["معصية الرسول تؤدّي إلى فتنة العاصي في دينه ودنياه.", "جواز العذل والعتاب للحبيب عند تقصيره فيما عُهد به إليه.", "جواز الاعتذار لمن اتُّهم بالتقصير وإن كان حقاً.", "قد يخطئ المجتهد في اجتهاده وقد يصيب."], "k": "«يا ابن أم لا تأخذ بلحيتي ولا برأسي»… حين يُعاتبني أحد بشدة، هل أجيبه بهذا الرفق؟"}, {"lbl": "الآيات ٩٥ – ٩٨", "q": "قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ ﴿٩٥﴾ قَالَ بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةٗ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي ﴿٩٦﴾ قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدٗا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفٗاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا ﴿٩٧﴾ إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمٗا ﴿٩٨﴾", "w": [["فما خطبك", "ما شأنك، وما هذا الأمر العظيم الذي صدر منك؟"], ["بصرت بما لم يبصروا به", "علمت من طريق الإبصار ما لم يعلموا به لأنهم لم يروه."], ["قبضة من أثر الرسول", "قبضة من تراب أثر حافر فرس الرسول جبريل ﵇."], ["فنبذتها", "ألقيتها وطرحتها على الحلي المصنوع عجلاً."], ["سوّلت لي نفسي", "زيّنت لي هذا العمل الذي هو صنع العجل."], ["أن تقول لا مساس", "اذهب تائهاً في الأرض طول حياتك وأنت تقول: لا مساس، أي لا يمسّني أحد ولا أمسّه."], ["ظلت", "ظللت طوال الوقت عاكفاً عليه."], ["في اليم نسفاً", "في البحر ننسفه بعد إحراقه وجعله كالنشارة."], ["إنما إلهكم الله", "لا معبود لكم إلا الله الذي لا إله إلا هو."]], "m": "بعد عذله أخاه التفت موسى إلى السامري، المنافق الذي أظهر الإسلام ثم عاد إلى عبادة البقر فصنع العجل ودعا إلى عبادته، فقال في غضب: ما شأنك يا سامري؟ قال: علمت ما لم يعلمه قومك، فقبضت قبضة من تراب أثر فرس الرسول فطرحتها في الحلي المصنوع عجلاً فخار، وكذلك زيّنت لي نفسي ذلك ففعلته. قال موسى: فاذهب، فإن لك مدة حياتك أن تقول لمن أراد أن يقربك: لا مساس، لتتيه طول عمرك في البرية عقوبة لك، وإن لك موعداً لعذاب يوم القيامة لن تخلفه. وانظر إلى إلهك المزعوم الذي ظللت عليه عاكفاً، والله لنحرقنّه ثم لننسفنّه في البحر نسفاً، ففعل حتى لا يُعثر له على أثر. ثم قال للمغرّر بهم: إنما إلهكم الحق الله الذي لا إله إلا هو، وسع كل شيء علماً، وما لم يكن ذا علم بكل شيء وقدرة على كل شيء فكيف يُعبد ويُطاع؟", "h": ["مشروعية الاستنطاق للمتّهم والاستجواب له.", "ما سوّلت النفس لأحد ولا زيّنت له شيئاً إلا تورّط فيه إن هو عمل بما سوّلته له.", "قد يجمع الله تعالى للعبد ذي الذنب العظيم بين عذاب الدنيا وعذاب الآخرة.", "مشروعية هجران المبتدع ونفيه وطرده، فلا يُسمح لأحد بالاتصال به والقرب منه.", "كسر الأصنام والأوثان والصور وآلات اللهو والباطل الصارفة عن عبادة الله تعالى."], "k": "«وكذلك سوّلت لي نفسي»… ما الذي تزيّنه لي نفسي الآن، وهل أعرضه على الوحي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (223, 20, 99, 112, 'سورة طه ٩٩ – ١١٢', '«وقد آتيناك من لدنّا ذكراً»، ونسف الجبال، و«وعنت الوجوه للحي القيوم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 223) = $j$[{"lbl": "الآيات ٩٩ – ١٠٤", "q": "كَذَٰلِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا ذِكۡرٗا ﴿٩٩﴾ مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ يَحۡمِلُ يَوۡمَ ٱلۡقِيَٰمَةِ وِزۡرًا ﴿١٠٠﴾ خَٰلِدِينَ فِيهِۖ وَسَآءَ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ حِمۡلٗا ﴿١٠١﴾ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ زُرۡقٗا ﴿١٠٢﴾ يَتَخَٰفَتُونَ بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرٗا ﴿١٠٣﴾ نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمٗا ﴿١٠٤﴾", "w": [["كذلك", "كما قصصنا عليك قصة موسى وفرعون، وموسى وبني إسرائيل، نقصّ عليك من أنباء الرسل."], ["من لدنّا ذكراً", "قرآناً، وهو القرآن الكريم."], ["من أعرض عنه", "لم يؤمن به ولم يقرأه ولم يعمل به."], ["وزراً", "حملاً ثقيلاً من الآثام."], ["يوم يُنفخ في الصور", "النفخة الثانية، نفخة البعث، والصور هو القرن."], ["زرقاً", "عيونهم زرق ووجوههم سود، آية أنهم أصحاب الجحيم."], ["يتخافتون بينهم", "يخفضون أصواتهم يتسارّون من شدة الهول."], ["أمثلهم طريقة", "أعدلهم رأياً في ذلك، وهذا كله لعظم الموقف."]], "m": "بعد نهاية الحديث عن موسى قال تعالى لرسوله: كما قصصنا عليك نبأ موسى وفرعون وبني إسرائيل، نقصّ عليك من أنباء الأمم السابقة ليكون ذلك آية نبوتك، وعبرة للمؤمنين، وقد أعطيناك تفضّلاً منا ذكراً، القرآن العظيم، يذكر به العبد ربه ويهتدي به إلى سبيل النجاة. من أعرض عنه فلم يؤمن به ولم يعمل بما فيه فإنه يحمل يوم القيامة إثماً عظيماً، خالدين فيه في النار، وقبح ذلك الحمل يوم القيامة. يوم يُنفخ في الصور النفخة الثانية، ونحشر المجرمين المكذّبين يومئذ زرق الأعين مع اسوداد الوجوه، يتهامسون بينهم: كم لبثتم في الدنيا والقبور؟ فيقول بعضهم: ما لبثتم إلا عشر ليالٍ، نحن أعلم بما يقولون إذ يقول أعدلهم رأياً: إن لبثتم إلا يوماً، وهذا التقالّ للزمن الطويل سببه هول القيامة وما يشاهدون فيها من الفزع.", "h": ["تقرير نبوة محمد ﷺ، إذ يقصّ تعالى عليه أنباء ما قد سبق بعد قصّه عليه أنباء موسى وفرعون بالحق، وإيتائه القرآن الكريم.", "كون القرآن ذكراً للذاكرين لما يحمل من الحجج والدلائل والبراهين.", "سوء حال المجرمين يوم القيامة، الذين أعرضوا عن القرآن الكريم.", "عظم أهوال يوم القيامة، حتى يتقالّ معها المرء مدة الحياة الدنيا التي هي آلاف الأعوام."], "k": "«وقد آتيناك من لدنّا ذكراً»… هذا الذكر بين يديّ؛ فهل هو حجة لي أم حمل عليّ؟"}, {"lbl": "الآيات ١٠٥ – ١١٢", "q": "وَيَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ فَقُلۡ يَنسِفُهَا رَبِّي نَسۡفٗا ﴿١٠٥﴾ فَيَذَرُهَا قَاعٗا صَفۡصَفٗا ﴿١٠٦﴾ لَّا تَرَىٰ فِيهَا عِوَجٗا وَلَآ أَمۡتٗا ﴿١٠٧﴾ يَوۡمَئِذٖ يَتَّبِعُونَ ٱلدَّاعِيَ لَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسٗا ﴿١٠٨﴾ يَوۡمَئِذٖ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ قَوۡلٗا ﴿١٠٩﴾ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يُحِيطُونَ بِهِۦ عِلۡمٗا ﴿١١٠﴾ ۞وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمٗا ﴿١١١﴾ وَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا يَخَافُ ظُلۡمٗا وَلَا هَضۡمٗا ﴿١١٢﴾", "w": [["ويسألونك عن الجبال", "يسألك المشركون عن الجبال كيف تكون يوم القيامة."], ["فقل ينسفها ربي نسفاً", "يفتّتها ثم تذروها الرياح فتكون هباءً منبثاً."], ["قاعاً صفصفاً", "مستوياً."], ["عوجاً ولا أمتاً", "لا ترى فيها انخفاضاً ولا ارتفاعاً."], ["الداعي", "الذي يدعوهم إلى المحشر للعرض على الرب تعالى."], ["وخشعت الأصوات", "سكنت فلا يُسمع إلا الهمس، وهو صوت الأقدام الخفي."], ["ورضي له قولاً", "بأن قال: لا إله إلا الله، من قلبه صادقاً."], ["ولا يحيطون به علماً", "يعلم الله ما بين أيدي الناس وما خلفهم، وهم لا يحيطون به علماً."], ["وعنت الوجوه للحي القيوم", "ذلّت وخضعت للرب الحي الذي لا يموت."], ["من حمل ظلماً", "جاء يوم القيامة يحمل أوزار الظلم، وهو الشرك."], ["ظلماً ولا هضماً", "لا يخاف ظلماً بأن يُزاد في سيئاته، ولا هضماً بأن يُنقص من حسناته."]], "m": "ويسألك المشركون المكذّبون بالبعث عن مصير الجبال يوم القيامة، فقل: يفتّتها ربي ثم ينسفها فتكون هباءً، فيترك أماكنها أرضاً مستوية لا ترى فيها انخفاضاً ولا ارتفاعاً. يومئذ يدعوهم الداعي: هلمّوا إلى أرض المحشر، فلا يميلون عن صوته يمنة ولا يسرة، وخشعت الأصوات للرحمن فلا تسمع إلا صوتاً خفياً. يومئذ لا تنفع شفاعة أحد أحداً إلا من أذن له الرحمن في الشفاعة، ورضي له قولاً، أي كان المشفوع فيه من أهل لا إله إلا الله. يعلم ما بين أيدي أهل المحشر مما سيُحكم به عليهم، وما خلفهم مما تركوه من أعمال، وهم لا يحيطون به علماً، فيكون الجزاء عادلاً. وذلّت الوجوه وخضعت للحي القيوم كما يعنو الأسير بوجهه، وقد خسر من حمل الشرك، ومن يعمل من الصالحات وهو مؤمن بالله وملائكته وكتبه ورسله واليوم الآخر فلا يخاف زيادة في سيئاته ولا نقصاً من حسناته.", "h": ["بيان جهل المشركين في سؤالهم عن الجبال.", "تقرير مبدأ البعث الآخر.", "لا شفاعة لغير أهل التوحيد، فلا يُشفّع مشرك، ولا يُشفع لمشرك.", "بيان خيبة المشركين وفوز الموحّدين يوم القيامة."], "k": "«وعنت الوجوه للحي القيوم»… سيخضع وجهي يومها؛ فهل يخضع اليوم في سجودي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 223;
