شفاعة أحد أحداً إلا من أذن له الرحمن في الشفاعة، ورضي له قولاً، أي كان المشفوع فيه من أهل لا إله إلا الله. يعلم ما بين أيدي أهل المحشر مما سيُحكم به عليهم، وما خلفهم مما تركوه من أعمال، وهم لا يحيطون به علماً، فيكون الجزاء عادلاً. وذلّت الوجوه وخضعت للحي القيوم كما يعنو الأسير بوجهه، وقد خسر من حمل الشرك، ومن يعمل من الصالحات وهو مؤمن بالله وملائكته وكتبه ورسله واليوم الآخر فلا يخاف زيادة في سيئاته ولا نقصاً من حسناته.", "h": ["بيان جهل المشركين في سؤالهم عن الجبال.", "تقرير مبدأ البعث الآخر.", "لا شفاعة لغير أهل التوحيد، فلا يُشفّع مشرك، ولا يُشفع لمشرك.", "بيان خيبة المشركين وفوز الموحّدين يوم القيامة."], "k": "«وعنت الوجوه للحي القيوم»… سيخضع وجهي يومها؛ فهل يخضع اليوم في سجودي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (224, 20, 113, 122, 'سورة طه ١١٣ – ١٢٢', '«ولا تعجل بالقرآن… وقل رب زدني علماً»، وقصة آدم ﵇: «فنسي ولم نجد له عزماً»، و«ثم اجتباه ربه فتاب عليه وهدى»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 224) = $j$[{"lbl": "الآيات ١١٣ – ١١٥", "q": "وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيّٗا وَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرٗا ﴿١١٣﴾ فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا ﴿١١٤﴾ وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمٗا ﴿١١٥﴾", "w": [["وكذلك أنزلناه", "مثل ذلك الإنزال أنزلنا قرآناً عربياً، أي بلغة العرب."], ["وصرّفنا فيه من الوعيد", "من أنواع الوعيد وفنون العذاب الدنيوي والأخروي."], ["أو يحدث لهم ذكراً", "بهلاك الأمم السابقة فيتّعظون فيتوبون ويسلمون."], ["فتعالى الله الملك الحق", "عما يقول المفترون ويشرك المشركون."], ["ولا تعجل بالقرآن", "بقراءته."], ["من قبل أن يُقضى إليك وحيه", "من قبل أن يفرغ جبريل من قراءته عليك."], ["عهدنا إلى آدم", "وصّيناه ألا يأكل من الشجرة."], ["فنسي", "عهدنا وتركه."], ["ولم نجد له عزماً", "حزماً وصبراً عما نهيناه عنه."]], "m": "ومثل ما أنزلنا من تلك الآيات أنزلنا القرآن بلغة العرب ليفهموه ويهتدوا به، وكرّرنا فيه أنواع الوعيد لعل قومك يتّقون ما كان سبباً في إهلاك الأمم من الشرك والتكذيب، أو يوجد لهم ذكراً في أنفسهم فيتّعظوا ويتوبوا. فتعالى الله الملك الحق على سائر خلقه بقهره وتصرّفه، المنزّه عن الشريك والولد وكل نقص. ويعلّم رسوله كيفية تلقّي القرآن: لا تستعجل في قراءة الآيات ولا في إملائها ولا في الحكم بها حتى يفرغ جبريل من قراءتها وبيان مراد الله منها، وقل: رب زدني علماً، وفيه إشعار بأنه دائماً في حاجة إلى المزيد، وعلماء أمته أحوج إلى ذلك منه، فالاستعجال في الفتيا وإصدار الحكم كثيراً ما يُخطئ صاحبه. ولقد وصّينا آدم من قبل هذه الأمم بألا يطيع عدوه إبليس ولا يأكل من الشجرة، فترك وصيّتنا ناسياً لها، وأطاع عدوه، ولم نجد له عزماً، بل ضعف أمام الإغراء، فكيف بغيره من ذرّيته؟ فلا تأس على عدم إيمان قومك.", "h": ["بيان الحكمة من إنزال القرآن باللسان العربي وتصريف الوعيد فيه.", "إثبات علوّ الله تعالى وقهره لعباده وملكه لهم، وتنزّهه عن الولد والشريك وكل نقص يصفه به المبطلون.", "استحباب التريّث والتأنّي في قراءة القرآن وتفسيره وإصدار الحكم والفتيا منه.", "الترغيب في طلب العلم والمزيد من التحصيل العلمي.", "التسلية بنسيان آدم وضعف قلبه أمام الإغراء الشيطاني."], "k": "«وقل رب زدني علماً»… دعاء أمر الله به نبيّه؛ فهل أدعو به وأسعى إليه؟"}, {"lbl": "الآيات ١١٦ – ١٢٢", "q": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ ﴿١١٦﴾ فَقُلۡنَا يَـٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوّٞ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ ﴿١١٧﴾ إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ ﴿١١٨﴾ وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ ﴿١١٩﴾ فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَـٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكٖ لَّا يَبۡلَىٰ ﴿١٢٠﴾ فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ ﴿١٢١﴾ ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ ﴿١٢٢﴾", "w": [["وإذ قلنا للملائكة", "اذكر قولنا للعظة والاعتبار."], ["إلا إبليس أبى", "امتنع من السجود لكبر في نفسه، إذ هو ليس من الملائكة، وإنما هو أبو الجان كان معهم يعبد الله."], ["عدو لك ولزوجك", "لا يحب لكما الخير، بل يريد لكما الشر، وزوجه حواء."], ["فتشقى", "بالعمل في الأرض، إذ تزرع وتحصد وتطحن وتخبز."], ["لا تظمأ فيها ولا تضحى", "لا تعطش، ولا يصيبك حرّ شمس الضحى المؤلم كما في الأرض."], ["شجرة الخلد", "التي يخلد من أكل منها."], ["وملك لا يبلى", "لا يفنى ولا يبيد."], ["فبدت لهما سوءاتهما", "ظهر لكل منهما قُبل صاحبه ودُبره فاستاءا لذلك."], ["وطفقا يخصفان", "أخذا يلزقان ورق الشجر عليهما ستراً لسوءاتهما."], ["فغوى", "بالأكل من الشجرة المنهي عنها."], ["فاجتباه ربه فتاب عليه", "اختاره لولايته فهداه للتوبة فتاب ليكون عبداً صالحاً."]], "m": "لما ذكر نسيان آدم العهد ناسب ذكر قصته بتمامها موعظة للمتقين: اذكر إذ قلنا للملائكة اسجدوا لآدم، وسجودهم عبادة لله وتحية لآدم لشرفه وعلمه، فسجدوا إلا إبليس أبى لما داخله من الكبر، ولأنه كان من الجن يتعبّد مع الملائكة. فقلنا: يا آدم، إن هذا عدو لك ولزوجك فلا تطيعاه فيخرجكما من الجنة فتشقى بالعمل للعيش كالزرع والحصاد، ووُجّه الخطاب إليه لأن الزوج هو المسئول عن إعاشة زوجته. إن لك ألا تجوع فيها ولا تعرى، ولا تعطش ولا يصيبك حرّ الشمس. فوسوس إليه الشيطان: يا آدم، هل أدلّك على شجرة الخلد وملك لا يفنى؟ فاستجاب لوسوسته، فأكلت حواء أولاً ثم أكل آدم، فانكشفت سوءاتهما بذهاب النور الساتر بسبب المعصية، فأخذا يشدّان ورق الشجر على عوراتهما، وهكذا عصى آدم ربه فغوى. ثم اجتباه ربه نبياً وقرّبه ولياً، فتاب عليه، وهداه للعمل بطاعته ليكون من صالح عباده.", "h": ["تقرير النبوة المحمدية بذكر مثل هذا القصص الذي لا يُعلم إلا بالوحي الإلهي.", "تقرير عداوة إبليس لبني آدم.", "بيان أن الجنة لا نصب فيها ولا تعب، وإنما ذلك في الأرض.", "التحذير من أخطار الاستجابة لوسوسة إبليس، فإنها تُردي صاحبها.", "ضعف المرأة وقلة عزمها، فقد أكلت قبل آدم فسهّلت عليه المعصية.", "كون المرأة تابعة للرجل، وليس لها أن تستقل بحال من الأحوال.", "حرمة كشف العورات ووجوب سترها.", "إثبات نبوة آدم، وتوبة الله عليه وقبولها منه، وهدايته إلى العمل بمحابّه وترك مكارهه."], "k": "«ثم اجتباه ربه فتاب عليه وهدى»… زلّة أبي البشر لم تُغلق باب الاجتباء؛ فلا أيأس بعد ذنبي."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 224;
insert into public.tdb_cards(topic, i, body) select 224, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١٣ – ١١٥", "q": "وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيّٗا وَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرٗا ﴿١١٣﴾ فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا ﴿١١٤﴾ وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمٗا ﴿١١٥﴾", "w": [["وكذلك أنزلناه", "مثل ذلك الإنزال أنزلنا قرآناً عربياً، أي بلغة العرب."], ["وصرّفنا فيه من الوعيد", "من أنواع الوعيد وفنون العذاب الدنيوي والأخروي."], ["أو يحدث لهم ذكراً", "بهلاك الأمم السابقة فيتّعظون فيتوبون ويسلمون."], ["فتعالى الله الملك الحق", "عما يقول المفترون ويشرك المشركون."], ["ولا تعجل بالقرآن", "بقراءته."], ["من قبل أن يُقضى إليك وحيه", "من قبل أن يفرغ جبريل من قراءته عليك."], ["عهدنا إلى آدم", "وصّيناه ألا يأكل من الشجرة."], ["فنسي", "عهدنا وتركه."], ["ولم نجد له عزماً", "حزماً وصبراً عما نهيناه عنه."]], "m": "ومثل ما أنزلنا من تلك الآيات أنزلنا القرآن بلغة العرب ليفهموه ويهتدوا به، وكرّرنا فيه أنواع الوعيد لعل قومك يتّقون ما كان سبباً في إهلاك الأمم من الشرك والتكذيب، أو يوجد لهم ذكراً في أنفسهم فيتّعظوا ويتوبوا. فتعالى الله الملك الحق على سائر خلقه بقهره وتصرّفه، المنزّه عن الشريك والولد وكل نقص. ويعلّم رسوله كيفية تلقّي القرآن: لا تستعجل في قراءة الآيات ولا في إملائها ولا في الحكم بها حتى يفرغ جبريل من قراءتها وبيان مراد الله منها، وقل: رب زدني علماً، وفيه إشعار بأنه دائماً في حاجة إلى المزيد، وعلماء أمته أحوج إلى ذلك منه، فالاستعجال في الفتيا وإصدار الحكم كثيراً ما يُخطئ صاحبه. ولقد وصّينا آدم من قبل هذه الأمم بألا يطيع عدوه إبليس ولا يأكل من الشجرة، فترك وصيّتنا ناسياً لها، وأطاع عدوه، ولم نجد له عزماً، بل ضعف أمام الإغراء، فكيف بغيره من ذرّيته؟ فلا تأس على عدم إيمان قومك.", "h": ["بيان الحكمة من إنزال القرآن باللسان العربي وتصريف الوعيد فيه.", "إثبات علوّ الله تعالى وقهره لعباده وملكه لهم، وتنزّهه عن الولد والشريك وكل نقص يصفه به المبطلون.", "استحباب التريّث والتأنّي في قراءة القرآن وتفسيره وإصدار الحكم والفتيا منه.", "الترغيب في طلب العلم والمزيد من التحصيل العلمي.", "التسلية بنسيان آدم وضعف قلبه أمام الإغراء الشيطاني."], "k": "«وقل رب زدني علماً»… دعاء أمر الله به نبيّه؛ فهل أدعو به وأسعى إليه؟"}, {"lbl": "الآيات ١١٦ – ١٢٢", "q": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ ﴿١١٦﴾ فَقُلۡنَا يَـٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوّٞ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ ﴿١١٧﴾ إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ ﴿١١٨﴾ وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ ﴿١١٩﴾ فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَـٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكٖ لَّا يَبۡلَىٰ ﴿١٢٠﴾ فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ ﴿١٢١﴾ ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ ﴿١٢٢﴾", "w": [["وإذ قلنا للملائكة", "اذكر قولنا للعظة والاعتبار."], ["إلا إبليس أبى", "امتنع من السجود لكبر في نفسه، إذ هو ليس من الملائكة، وإنما هو أبو الجان كان معهم يعبد الله."], ["عدو لك ولزوجك", "لا يحب لكما الخير، بل يريد لكما الشر، وزوجه حواء."], ["فتشقى", "بالعمل في الأرض، إذ تزرع وتحصد وتطحن وتخبز."], ["لا تظمأ فيها ولا تضحى", "لا تعطش، ولا يصيبك حرّ شمس الضحى المؤلم كما في الأرض."], ["شجرة الخلد", "التي يخلد من أكل منها."], ["وملك لا يبلى", "لا يفنى ولا يبيد."], ["فبدت لهما سوءاتهما", "ظهر لكل منهما قُبل صاحبه ودُبره فاستاءا لذلك."], ["وطفقا يخصفان", "أخذا يلزقان ورق الشجر عليهما ستراً لسوءاتهما."], ["فغوى", "بالأكل من الشجرة المنهي عنها."], ["فاجتباه ربه فتاب عليه", "اختاره لولايته فهداه للتوبة فتاب ليكون عبداً صالحاً."]], "m": "لما ذكر نسيان آدم العهد ناسب ذكر قصته بتمامها موعظة للمتقين: اذكر إذ قلنا للملائكة اسجدوا لآدم، وسجودهم عبادة لله وتحية لآدم لشرفه وعلمه، فسجدوا إلا إبليس أبى لما داخله من الكبر، ولأنه كان من الجن يتعبّد مع الملائكة. فقلنا: يا آدم، إن هذا عدو لك ولزوجك فلا تطيعاه فيخرجكما من الجنة فتشقى بالعمل للعيش كالزرع والحصاد، ووُجّه الخطاب إليه لأن الزوج هو المسئول عن إعاشة زوجته. إن لك ألا تجوع فيها ولا تعرى، ولا تعطش ولا يصيبك حرّ الشمس. فوسوس إليه الشيطان: يا آدم، هل أدلّك على شجرة الخلد وملك لا يفنى؟ فاستجاب لوسوسته، فأكلت حواء أولاً ثم أكل آدم، فانكشفت سوءاتهما بذهاب النور الساتر بسبب المعصية، فأخذا يشدّان ورق الشجر على عوراتهما، وهكذا عصى آدم ربه فغوى. ثم اجتباه ربه نبياً وقرّبه ولياً، فتاب عليه، وهداه للعمل بطاعته ليكون من صالح عباده.", "h": ["تقرير النبوة المحمدية بذكر مثل هذا القصص الذي لا يُعلم إلا بالوحي الإلهي.", "تقرير عداوة إبليس لبني آدم.", "بيان أن الجنة لا نصب فيها ولا تعب، وإنما ذلك في الأرض.", "التحذير من أخطار الاستجابة لوسوسة إبليس، فإنها تُردي صاحبها.", "ضعف المرأة وقلة عزمها، فقد أكلت قبل آدم فسهّلت عليه المعصية.", "كون المرأة تابعة للرجل، وليس لها أن تستقل بحال من الأحوال.", "حرمة كشف العورات ووجوب سترها.", "إثبات نبوة آدم، وتوبة الله عليه وقبولها منه، وهدايته إلى العمل بمحابّه وترك مكارهه."], "k": "«ثم اجتباه ربه فتاب عليه وهدى»… زلّة أبي البشر لم تُغلق باب الاجتباء؛ فلا أيأس بعد ذنبي."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (225, 20, 123, 135, 'سورة طه ١٢٣ – ١٣٥', '«فمن اتبع هداي فلا يضلّ ولا يشقى ومن أعرض عن ذكري فإن له معيشة ضنكاً»، و«وأمر أهلك بالصلاة واصطبر عليها»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 225) = $j$[{"lbl": "الآيات ١٢٣ – ١٢٧", "q": "قَالَ ٱهۡبِطَا مِنۡهَا جَمِيعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ ﴿١٢٣﴾ وَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةٗ ضَنكٗا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ أَعۡمَىٰ ﴿١٢٤﴾ قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرٗا ﴿١٢٥﴾ قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ ﴿١٢٦﴾ وَكَذَٰلِكَ نَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ وَأَبۡقَىٰٓ ﴿١٢٧﴾", "w": [["قال اهبطا منها جميعاً", "آدم وحواء من الجنة، وإبليس سبق أن أُبلس وهبط."], ["بعضكم لبعض عدو", "آدم وحواء وذريتهما عدو لإبليس وذريته، وإبليس وذريته عدو لهم."], ["فإما يأتينّكم مني هدى", "كتاب ورسول."], ["فمن اتبع هداي", "الذي أرسلت به رسولي، وهو القرآن."], ["فلا يضلّ", "في الدنيا."], ["ولا يشقى", "في الآخرة."], ["ومن أعرض عن ذكري", "عن القرآن فلم يؤمن به ولم يعمل بما فيه."], ["معيشة ضنكاً", "ضيّقة تضيق بها نفسه ولا يسعد بها ولو كانت واسعة."], ["أعمى", "أعمى البصر لا يبصر."], ["وقد كنت بصيراً", "ذا بصر في الدنيا وعند البعث."], ["قال كذلك", "الأمر كذلك، أتتك آياتنا فنسيتها، فكما نسيتها تُنسى في النار."], ["من أسرف", "أسرف في المعاصي ولم يقف عند حدّ ولم يؤمن بآيات ربه."], ["أشد وأبقى", "أشد من عذاب الدنيا وأدوم فلا ينقضي."]], "m": "ما زال السياق في قصة آدم: لما أكلا من الشجرة وعاتبهما ربهما، وأنزل على آدم كلمة التوبة فقالها مع زوجه فتاب الله عليهما، قال: اهبطا منها جميعاً، بعضكم لبعض عدو، فإن يأتكم مني هدى، بيان عبادتي تحمله كتبي وتبيّنه رسلي، فمن اتبعه فآمن به وعمل بما فيه فلا يضلّ في حياته ولا يشقى في آخرته. ومن أعرض عن ذكري فلم يؤمن به ولم يعمل بما فيه فإن له معيشة ضيّقة، تضيق بها نفسه فلا يشعر بالسعادة وإن اتسع رزقه، كما يضيق عليه قبره، ونحشره يوم القيامة أعمى لا حجة له ولا بصر. فيسأل متعجّباً: رب لم حشرتني أعمى وقد كنت بصيراً؟ فيجيبه: الأمر كذلك، أتتك آياتنا تحملها كتبنا وتبيّنها رسلنا فتركتها معرضاً عنها، فاليوم تُترك في جهنم منسياً. وكذلك نجزي من أسرف في معاصينا ولم يؤمن بآيات ربه، معيشة ضنكاً في الدنيا والبرزخ، ولعذاب الآخرة أشد وأدوم لا ينقضي.", "h": ["تقرير عداوة الشيطان للإنسان.", "عِدة الله تعالى لمن آمن بالقرآن وعمل بما فيه ألا يضلّ في حياته ولا يشقى في آخرته.", "بيان جزاء من أعرض عن القرآن في الدنيا والآخرة.", "التنديد بالإسراف في الذنوب والمعاصي مع الكفر بآيات الله، وبيان جزاء ذلك."], "k": "«فإن له معيشة ضنكاً»… الضيق الذي أجده أحياناً، هل له صلة ببعدي عن الذكر؟"}, {"lbl": "الآيات ١٢٨ – ١٣٢", "q": "أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ ﴿١٢٨﴾ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامٗا وَأَجَلٞ مُّسَمّٗى ﴿١٢٩﴾ فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ ﴿١٣٠﴾ وَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرٞ وَأَبۡقَىٰ ﴿١٣١﴾ وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ ﴿١٣٢﴾", "w": [["أفلم يهد لهم", "أفلم يتبيّن لهم؟"], ["من القرون", "من أهل القرون."], ["لأولي النهى", "أصحاب العقول الراجحة، إذ النُّهية العقل."], ["ولولا كلمة سبقت", "بتأخير العذاب عنهم."], ["لكان لزاماً", "لكان العذاب لازماً لا يتأخر عنهم بحال."], ["ما يقولون", "من كلمات الكفر، ومن مطالبتهم بالآيات."], ["ومن آناء الليل", "ساعات الليل."], ["لعلك ترضى", "رجاء أن تُثاب الثواب الحسن الذي ترضى به."], ["إلى ما متّعنا به أزواجاً منهم", "أصنافاً من الكافرين."], ["زهرة الحياة الدنيا", "زينة الحياة الدنيا، وقيل فيها زهرة لأنها سرعان ما تذبل."], ["لنفتنهم فيه", "لنبتليهم في ذلك أيشكرون أم يكفرون."], ["والعاقبة للتقوى", "العاقبة الحميدة في الدنيا والآخرة لأهل التقوى."]], "m": "بعد قصة آدم قال تعالى: أغفل أهل مكة فلم يتبيّن لهم كم أهلكنا قبلهم من أهل القرون يمشون في مساكنهم، كثمود وأصحاب مدين والمؤتفكات، فيؤمنوا وينجوا؟ إن في ذلك لدلائل واضحة لأصحاب العقول، أما الذين عطّلوا عقولهم فلا. ولولا كلمة سبقت من ربك بألا تموت نفس حتى تستوفي أجلها، وأجل مسمّى في كتاب المقادير، لكان عذابهم لازماً لهم. فاصبر على ما يقولون من أنك ساحر وشاعر وكاهن، واستعن بالصلاة: قبل طلوع الشمس، صلاة الصبح، وقبل غروبها، صلاة العصر، ومن ساعات الليل، المغرب والعشاء، وأطراف النهار، صلاة الظهر عند الزوال، لعلك ترضى بثواب الله. ولا تتطلّع ناظراً إلى ما متّعنا به أصنافاً منهم من زينة الحياة الدنيا لنختبرهم فيه، ورزق ربك من الأجر والمثوبة خير في نوعه وأبقى في مدته، واختيار الباقي على الفاني مطلب العقلاء. وأمر أهلك من أزواجك وبناتك وأتباعك المؤمنين بالصلاة، ففيها الملاذ والشفاء من آلام الحاجة، واصطبر عليها، لا نكلّفك رزقاً، ولكن نكلّفك صلاة فأدّها على أكمل وجوهها، نحن نرزقك، والعاقبة الحميدة في الدنيا والآخرة لأهل التقوى.", "h": ["تقرير مبدأ: العاقل من اعتبر بغيره.", "بيان فضيلة العقل وشرف صاحبه وانتفاعه به.", "وجوب الصبر على دعوة الله، والاستعانة على ذلك بالصلاة.", "بيان أوقات الصلوات الخمس، والحصول على رضا النفس بثوابها.", "وجوب عدم تعلّق النفس بما عند أهل الكفر من مال ومتاع، لأنهم ممتحنون به.", "وجوب الرضا بما قسم الله للعبد من رزق انتظاراً لرزق الآخرة الخالد الباقي.", "وجوب الأمر بالصلاة بين الأهل والأولاد والمسلمين، والصبر على ذلك.", "فضل التقوى وكرامة أصحابها وفوزهم بحسن العاقبة في الدنيا والآخرة.", "إقام الصلاة بين أفراد الأسرة المسلمة ييسّر الله تعالى به أسباب الرزق وتوسعته عليهم."], "k": "«وأمر أهلك بالصلاة واصطبر عليها لا نسألك رزقاً نحن نرزقك»… هل أذكّر أهلي بالصلاة كما أذكّرهم بالعمل والرزق؟"}, {"lbl": "الآيات ١٣٣ – ١٣٥", "q": "وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةٖ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ ﴿١٣٣﴾ وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابٖ مِّن قَبۡلِهِۦ لَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ ﴿١٣٤﴾ قُلۡ كُلّٞ مُّتَرَبِّصٞ فَتَرَبَّصُواْۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِيِّ وَمَنِ ٱهۡتَدَىٰ ﴿١٣٥﴾", "w": [["لولا", "هلّا، أداة تحضيض."], ["بآية من ربه", "معجزة تدل على صدقه في نبوته ورسالته."], ["بيّنة ما في الصحف الأولى", "ما اشتمل عليه القرآن من أنباء الأمم الماضية وهلاكهم بتكذيبهم رسلهم."], ["من قبله", "من قبل إرسالنا محمداً ﷺ وإنزالنا القرآن."], ["من قبل أن نذلّ ونخزى", "من قبل أن يصيبنا الذل والخزي يوم القيامة في جهنم."], ["متربّص", "منتظر ما يؤول إليه الأمر."], ["فستعلمون", "يوم القيامة."], ["الصراط السوي", "الدين الصحيح، وهو الإسلام."], ["ومن اهتدى", "ومن ضلّ، نحن أم أنتم."]], "m": "ما زال السياق مع المشركين طلباً لهدايتهم: أصرّوا على التكذيب وقالوا: هلّا يأتينا محمد بمعجزة كالتي أتى بها صالح وموسى وعيسى تدل على صدقه! فردّ عليهم: أولم تأتهم بالقرآن بيّنة ما في الصحف الأولى، فعرفوا ما حلّ بالأمم التي طالبت بالآيات فلما جاءتها كذّبت بها فأُهلكت؟ فما يؤمن هؤلاء أنها لو جاءتهم ما آمنوا فأُهلكوا كمن قبلهم. ولو أنا أهلكناهم بعذاب من قبل إرسال محمد وإنزال الكتاب لقالوا: ربنا هلّا أرسلت إلينا رسولاً فنتّبع آياتك من قبل أن نذلّ ونخزى في نار جهنم، فإن كان هذا قولهم فلم لا يؤمنون الآن قبل حلول العذاب؟ قل: كل منا منتظر ما يؤول إليه الأمر، فانتظروا، فستعلمون عندما توقفون في عرصات القيامة من أصحاب الصراط السوي الذي هو الإسلام، ومن اهتدى إلى سبيل النجاة ممن ضلّ فخسر.", "h": ["المطالبة بالآيات سنة متّبعة للأمم والشعوب عندما تعرض عن الحق وتتنكّر للعقل.", "الذلة والخزي تصيب أهل النار يوم القيامة لما فرّطوا فيه من الإيمان والعمل الصالح.", "في الآية إشارة إلى حديث: «يحتجّ على الله يوم القيامة ثلاثة: الهالك في الفترة، والمغلوب على عقله، والصبي الصغير… فتُرفع لهم نار ويقال لهم: رِدوها، فيردها من كان في علم الله أنه سعيد، ويتلكّأ عنها من كان في علم الله أنه شقي»."], "k": "«فستعلمون من أصحاب الصراط السوي ومن اهتدى»… أختم السورة بسؤال لنفسي: على أي صراط أنا اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 225;
insert into public.tdb_cards(topic, i, body) select 225, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢٣ – ١٢٧", "q": "قَالَ ٱهۡبِطَا مِنۡهَا جَمِيعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ ﴿١٢٣﴾ وَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةٗ ضَنكٗا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ أَعۡمَىٰ ﴿١٢٤﴾ قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرٗا ﴿١٢٥﴾ قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ ﴿١٢٦﴾ وَكَذَٰلِكَ نَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ وَأَبۡقَىٰٓ ﴿١٢٧﴾", "w": [["قال اهبطا منها جميعاً", "آدم وحواء من الجنة، وإبليس سبق أن أُبلس وهبط."], ["بعضكم لبعض عدو", "آدم وحواء وذريتهما عدو لإبليس وذريته، وإبليس وذريته عدو لهم."], ["فإما يأتينّكم مني هدى", "كتاب ورسول."], ["فمن اتبع هداي", "الذي أرسلت به رسولي، وهو القرآن."], ["فلا يضلّ", "في الدنيا."], ["ولا يشقى", "في الآخرة."], ["ومن أعرض عن ذكري", "عن القرآن فلم يؤمن به ولم يعمل بما فيه."], ["معيشة ضنكاً", "ضيّقة تضيق بها نفسه ولا يسعد بها ولو كانت واسعة."], ["أعمى", "أعمى البصر لا يبصر."], ["وقد كنت بصيراً", "ذا بصر في الدنيا وعند البعث."], ["قال كذلك", "الأمر كذلك، أتتك آياتنا فنسيتها، فكما نسيتها تُنسى في النار."], ["من أسرف", "أسرف في المعاصي ولم يقف عند حدّ ولم يؤمن بآيات ربه."], ["أشد وأبقى", "أشد من عذاب الدنيا وأدوم فلا ينقضي."]], "m": "ما زال السياق في قصة آدم: لما أكلا من الشجرة وعاتبهما ربهما، وأنزل على آدم كلمة التوبة فقالها مع زوجه فتاب الله عليهما، قال: اهبطا منها جميعاً، بعضكم لبعض عدو، فإن يأتكم مني هدى، بيان عبادتي تحمله كتبي وتبيّنه رسلي، فمن اتبعه فآمن به وعمل بما فيه فلا يضلّ في حياته ولا يشقى في آخرته. ومن أعرض عن ذكري فلم يؤمن به ولم يعمل بما فيه فإن له معيشة ضيّقة، تضيق بها نفسه فلا يشعر بالسعادة وإن اتسع رزقه، كما يضيق عليه قبره، ونحشره يوم القيامة أعمى لا حجة له ولا بصر. فيسأل متعجّباً: رب لم حشرتني أعمى وقد كنت بصيراً؟ فيجيبه: الأمر كذلك، أتتك آياتنا تحملها كتبنا وتبيّنها رسلنا فتركتها معرضاً عنها، فاليوم تُترك في جهنم منسياً. وكذلك نجزي من أسرف في معاصينا ولم يؤمن بآيات ربه، معيشة ضنكاً في الدنيا والبرزخ، ولعذاب الآخرة أشد وأدوم لا ينقضي.", "h": ["تقرير عداوة الشيطان للإنسان.", "عِدة الله تعالى لمن آمن بالقرآن وعمل بما فيه ألا يضلّ في حياته ولا يشقى في آخرته.", "بيان جزاء من أعرض عن القرآن في الدنيا والآخرة.", "التنديد بالإسراف في الذنوب والمعاصي مع الكفر بآيات الله، وبيان جزاء ذلك."], "k": "«فإن له معيشة ضنكاً»… الضيق الذي أجده أحياناً، هل له صلة ببعدي عن الذكر؟"}, {"lbl": "الآيات ١٢٨ – ١٣٢", "q": "أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ ﴿١٢٨﴾ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامٗا وَأَجَلٞ مُّسَمّٗى ﴿١٢٩﴾ فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ ﴿١٣٠﴾ وَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرٞ وَأَبۡقَىٰ ﴿١٣١﴾ وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ ﴿١٣٢﴾", "w": [["أفلم يهد لهم", "أفلم يتبيّن لهم؟"], ["من القرون", "من أهل القرون."], ["لأولي النهى", "أصحاب العقول الراجحة، إذ النُّهية العقل."], ["ولولا كلمة سبقت", "بتأخير العذاب عنهم."], ["لكان لزاماً", "لكان العذاب لازماً لا يتأخر عنهم بحال."], ["ما يقولون", "من كلمات الكفر، ومن مطالبتهم بالآيات."], ["ومن آناء الليل", "ساعات الليل."], ["لعلك ترضى", "رجاء أن تُثاب الثواب الحسن الذي ترضى به."], ["إلى ما متّعنا به أزواجاً منهم", "أصنافاً من الكافرين."], ["زهرة الحياة الدنيا", "زينة الحياة الدنيا، وقيل فيها زهرة لأنها سرعان ما تذبل."], ["لنفتنهم فيه", "لنبتليهم في ذلك أيشكرون أم يكفرون."], ["والعاقبة للتقوى", "العاقبة الحميدة في الدنيا والآخرة لأهل التقوى."]], "m": "بعد قصة آدم قال تعالى: أغفل أهل مكة فلم يتبيّن لهم كم أهلكنا قبلهم من أهل القرون يمشون في مساكنهم، كثمود وأصحاب مدين والمؤتفكات، فيؤمنوا وينجوا؟ إن في ذلك لدلائل واضحة لأصحاب العقول، أما الذين عطّلوا عقولهم فلا. ولولا كلمة سبقت من ربك بألا تموت نفس حتى تستوفي أجلها، وأجل مسمّى في كتاب المقادير، لكان عذابهم لازماً لهم. فاصبر على ما يقولون من أنك ساحر وشاعر وكاهن، واستعن بالصلاة: قبل طلوع الشمس، صلاة الصبح، وقبل غروبها، صلاة العصر، ومن ساعات الليل، المغرب والعشاء، وأطراف النهار، صلاة الظهر عند الزوال، لعلك ترضى بثواب الله. ولا تتطلّع ناظراً إلى ما متّعنا به أصنافاً منهم من زينة الحياة الدنيا لنختبرهم فيه، ورزق ربك من الأجر والمثوبة خير في نوعه وأبقى في مدته، واختيار الباقي على الفاني مطلب العقلاء. وأمر أهلك من أزواجك وبناتك وأتباعك المؤمنين بالصلاة، ففيها الملاذ والشفاء من آلام الحاجة، واصطبر عليها، لا نكلّفك رزقاً، ولكن نكلّفك صلاة فأدّها على أكمل وجوهها، نحن نرزقك، والعاقبة الحميدة في الدنيا والآخرة لأهل التقوى.", "h": ["تقرير مبدأ: العاقل من اعتبر بغيره.", "بيان فضيلة العقل وشرف صاحبه وانتفاعه به.", "وجوب الصبر على دعوة الله، والاستعانة على ذلك بالصلاة.", "بيان أوقات الصلوات الخمس، والحصول على رضا النفس بثوابها.", "وجوب عدم تعلّق النفس بما عند أهل الكفر من مال ومتاع، لأنهم ممتحنون به.", "وجوب الرضا بما قسم الله للعبد من رزق انتظاراً لرزق الآخرة الخالد الباقي.", "وجوب الأمر بالصلاة بين الأهل والأولاد والمسلمين، والصبر على ذلك.", "فضل التقوى وكرامة أصحابها وفوزهم بحسن العاقبة في الدنيا والآخرة.", "إقام الصلاة بين أفراد الأسرة المسلمة ييسّر الله تعالى به أسباب الرزق وتوسعته عليهم."], "k": "«وأمر أهلك بالصلاة واصطبر عليها لا نسألك رزقاً نحن نرزقك»… هل أذكّر أهلي بالصلاة كما أذكّرهم بالعمل والرزق؟"}, {"lbl": "الآيات ١٣٣ – ١٣٥", "q": "وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةٖ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ ﴿١٣٣﴾ وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابٖ مِّن قَبۡلِهِۦ لَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ ﴿١٣٤﴾ قُلۡ كُلّٞ مُّتَرَبِّصٞ فَتَرَبَّصُواْۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِيِّ وَمَنِ ٱهۡتَدَىٰ ﴿١٣٥﴾", "w": [["لولا", "هلّا، أداة تحضيض."], ["بآية من ربه", "معجزة تدل على صدقه في نبوته ورسالته."], ["بيّنة ما في الصحف الأولى", "ما اشتمل عليه القرآن من أنباء الأمم الماضية وهلاكهم بتكذيبهم رسلهم."], ["من قبله", "من قبل إرسالنا محمداً ﷺ وإنزالنا القرآن."], ["من قبل أن نذلّ ونخزى", "من قبل أن يصيبنا الذل والخزي يوم القيامة في جهنم."], ["متربّص", "منتظر ما يؤول إليه الأمر."], ["فستعلمون", "يوم القيامة."], ["الصراط السوي", "الدين الصحيح، وهو الإسلام."], ["ومن اهتدى", "ومن ضلّ، نحن أم أنتم."]], "m": "ما زال السياق مع المشركين طلباً لهدايتهم: أصرّوا على التكذيب وقالوا: هلّا يأتينا محمد بمعجزة كالتي أتى بها صالح وموسى وعيسى تدل على صدقه! فردّ عليهم: أولم تأتهم بالقرآن بيّنة ما في الصحف الأولى، فعرفوا ما حلّ بالأمم التي طالبت بالآيات فلما جاءتها كذّبت بها فأُهلكت؟ فما يؤمن هؤلاء أنها لو جاءتهم ما آمنوا فأُهلكوا كمن قبلهم. ولو أنا أهلكناهم بعذاب من قبل إرسال محمد وإنزال الكتاب لقالوا: ربنا هلّا أرسلت إلينا رسولاً فنتّبع آياتك من قبل أن نذلّ ونخزى في نار جهنم، فإن كان هذا قولهم فلم لا يؤمنون الآن قبل حلول العذاب؟ قل: كل منا منتظر ما يؤول إليه الأمر، فانتظروا، فستعلمون عندما توقفون في عرصات القيامة من أصحاب الصراط السوي الذي هو الإسلام، ومن اهتدى إلى سبيل النجاة ممن ضلّ فخسر.", "h": ["المطالبة بالآيات سنة متّبعة للأمم والشعوب عندما تعرض عن الحق وتتنكّر للعقل.", "الذلة والخزي تصيب أهل النار يوم القيامة لما فرّطوا فيه من الإيمان والعمل الصالح.", "في الآية إشارة إلى حديث: «يحتجّ على الله يوم القيامة ثلاثة: الهالك في الفترة، والمغلوب على عقله، والصبي الصغير… فتُرفع لهم نار ويقال لهم: رِدوها، فيردها من كان في علم الله أنه سعيد، ويتلكّأ عنها من كان في علم الله أنه شقي»."], "k": "«فستعلمون من أصحاب الصراط السوي ومن اهتدى»… أختم السورة بسؤال لنفسي: على أي صراط أنا اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;